function ensureDefaultTeamAndSeason() {
  try {
    let teams = JSON.parse(window.localStorage.getItem("tf_teams") || "null");
    if (!teams || teams.length === 0) {
      let existingName = "Mon équipe";
      try { existingName = window.localStorage.getItem("tf_club_name") || existingName; } catch (e) {}
      teams = [{ id: DEFAULT_TEAM_ID, name: existingName, category: "" }];
      window.localStorage.setItem("tf_teams", JSON.stringify(teams));
    }
    let seasons = JSON.parse(window.localStorage.getItem("tf_seasons") || "null");
    if (!seasons || seasons.length === 0) {
      seasons = [{ id: DEFAULT_SEASON_ID, label: "Saison actuelle", startDate: "", endDate: "" }];
      window.localStorage.setItem("tf_seasons", JSON.stringify(seasons));
    }
    if (!window.localStorage.getItem("tf_active_team")) window.localStorage.setItem("tf_active_team", DEFAULT_TEAM_ID);
    if (!window.localStorage.getItem("tf_active_season")) window.localStorage.setItem("tf_active_season", DEFAULT_SEASON_ID);
  } catch (e) {}
}
ensureDefaultTeamAndSeason();

function switchTeamAndSeason(teamId, seasonId) {
  window.localStorage.setItem("tf_active_team", teamId);
  window.localStorage.setItem("tf_active_season", seasonId);
  window.location.reload();
}

