const ALL_EVENTS = EVENT_CATEGORIES.flatMap((c) => c.events);
const EVENT_MAP = Object.fromEntries(ALL_EVENTS.map((e) => [e.key, e]));

// Raccourcis personnalisés : customHotkeys est une map { eventKey: "X" } stockée dans
// tf_custom_hotkeys, chargée indépendamment par chaque écran de tagging (Studio et Observation)
// pour rester cohérent avec le principe déjà suivi ailleurs — pas de prop-drilling entre écrans
// qui n'ont pas de lien parent/enfant direct.
function effectiveHotkeyFor(eventKey, customHotkeys) {
  if (customHotkeys && customHotkeys[eventKey]) return customHotkeys[eventKey];
  const ev = EVENT_MAP[eventKey];
  return ev ? ev.hotkey : "";
}
// Résout quel événement une touche pressée doit déclencher. Les raccourcis personnalisés sont
// prioritaires ; sinon, la touche par défaut d'un événement ne s'applique QUE s'il n'a pas été
// réaffecté ailleurs — sinon presser l'ancienne touche par défaut déclencherait encore l'événement
// en plus de sa nouvelle touche, ce qui serait déroutant.
function findEventForKeyPress(pressedKeyUpper, customHotkeys) {
  if (customHotkeys) {
    const customMatch = Object.keys(customHotkeys).find((k) => customHotkeys[k] && customHotkeys[k].toUpperCase() === pressedKeyUpper);
    if (customMatch && EVENT_MAP[customMatch]) return EVENT_MAP[customMatch];
  }
  return ALL_EVENTS.find((ev) => {
    if (ev.hotkey !== pressedKeyUpper) return false;
    const custom = customHotkeys && customHotkeys[ev.key];
    if (custom && custom.toUpperCase() !== ev.hotkey) return false;
    return true;
  });
}

