function computeGlobalSearchResults(query) {
  const q = query.trim().toLowerCase();
  if (q.length < 2) return [];
  const results = [];

  try {
    const roster = JSON.parse(localStorage.getItem("tf_roster") || "[]");
    roster.forEach((p) => {
      const name = playerFullName(p);
      if (name.toLowerCase().includes(q)) {
        results.push({ type: "Effectif", label: name, meta: p.positionPrecise || p.position, section: "squad" });
      }
    });
  } catch (e) {}

  try {
    const scouted = JSON.parse(localStorage.getItem("tf_scouting") || "[]");
    scouted.forEach((p) => {
      if ((p.name || "").toLowerCase().includes(q) || (p.club || "").toLowerCase().includes(q)) {
        results.push({ type: "Scouting", label: p.name || "Joueur non identifié", meta: p.club, section: "scouting" });
      }
    });
  } catch (e) {}

  try {
    const compRaw = localStorage.getItem("tf_competitions");
    const comp = migrateCompetitionsData(compRaw ? JSON.parse(compRaw) : null);
    comp.competitions.forEach((c) => {
      if (c.name.toLowerCase().includes(q) || (c.groupName || "").toLowerCase().includes(q)) {
        results.push({ type: "Compétition", label: c.name, meta: c.groupName || COMPETITION_TYPES.find((t) => t.key === c.type).label, section: "competitions" });
      }
    });
  } catch (e) {}

  try {
    const clubs = JSON.parse(localStorage.getItem("tf_adversaire_clubs") || "[]");
    clubs.forEach((c) => {
      if (c.name.toLowerCase().includes(q)) {
        results.push({ type: "Club", label: c.name, meta: "Effectifs → Adversaire", section: "squad" });
      }
    });
  } catch (e) {}

  try {
    const library = JSON.parse(window.localStorage.getItem("tf_bibliotheque") || "[]");
    library.forEach((e) => {
      if (e.title.toLowerCase().includes(q) || (e.author || "").toLowerCase().includes(q) || (e.theme || "").toLowerCase().includes(q)) {
        results.push({ type: "Bibliothèque", label: e.title, meta: e.theme || e.type, section: "bibliotheque" });
      }
    });
  } catch (e) {}

  try {
    const journal = JSON.parse(window.localStorage.getItem("tf_journal_entries") || "[]");
    journal.forEach((e) => {
      if ((e.title || "").toLowerCase().includes(q) || (e.content || "").toLowerCase().includes(q)) {
        results.push({ type: "Journal de bord", label: e.title || formatDateFr(e.date), meta: formatDateFr(e.date), section: "assistant" });
      }
    });
  } catch (e) {}

  try {
    const staff = JSON.parse(window.localStorage.getItem("tf_club_staff") || "[]");
    staff.forEach((s) => {
      const name = `${s.firstName} ${s.lastName}`;
      const roles = staffRoles(s);
      if (name.toLowerCase().includes(q) || roles.some((r) => r.toLowerCase().includes(q))) {
        results.push({ type: "Staff", label: name, meta: roles.join(", "), section: "club" });
      }
    });
  } catch (e) {}

  try {
    const clubExercises = JSON.parse(window.localStorage.getItem("tf_club_exercise_library") || "[]");
    clubExercises.forEach((ex) => {
      if (ex.name.toLowerCase().includes(q)) {
        results.push({ type: "Exercice (club)", label: ex.name, meta: ex.objectif, section: "club" });
      }
    });
  } catch (e) {}

  try {
    const exercises = JSON.parse(localStorage.getItem("tf_exercices") || "[]");
    exercises.forEach((ex) => {
      if (ex.name.toLowerCase().includes(q)) {
        results.push({ type: "Exercice", label: ex.name, meta: ex.objectif, section: "seance" });
      }
    });
  } catch (e) {}

  try {
    const sessions = JSON.parse(localStorage.getItem("tf_sessions") || "[]");
    sessions.forEach((s) => {
      if (s.name.toLowerCase().includes(q)) {
        results.push({ type: "Séance", label: s.name, meta: formatDateFr(s.date), section: "seance" });
      }
    });
  } catch (e) {}

  try {
    const causeries = JSON.parse(localStorage.getItem("tf_causeries") || "[]");
    causeries.forEach((c) => {
      if (c.name.toLowerCase().includes(q) || (c.opponent || "").toLowerCase().includes(q)) {
        results.push({ type: "Causerie", label: c.name, meta: formatDateFr(c.date), section: "causerie" });
      }
    });
  } catch (e) {}

  try {
    const events = JSON.parse(window.localStorage.getItem("tf_club_events") || "[]");
    events.forEach((e) => {
      if (e.name.toLowerCase().includes(q)) {
        results.push({ type: "Événement (club)", label: e.name, meta: formatDateFr(e.date), section: "club" });
      }
    });
  } catch (e) {}

  try {
    const teams = JSON.parse(window.localStorage.getItem("tf_teams") || "[]");
    teams.forEach((t) => {
      if (t.name.toLowerCase().includes(q)) {
        results.push({ type: "Équipe", label: t.name, meta: t.category || "", section: "club" });
      }
    });
  } catch (e) {}

  return results.slice(0, 20);
}

