// ============ Vidéothèque : stockage persistant des clips (IndexedDB) ============
function clipsDbName() {
  const suffix = getScopeSuffix();
  return suffix ? "tf_videotheque" + suffix : "tf_videotheque";
}
const CLIPS_STORE = "clips";

function openClipsDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(clipsDbName(), 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(CLIPS_STORE)) {
        db.createObjectStore(CLIPS_STORE, { keyPath: "id" });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function saveClip(clip) {
  const db = await openClipsDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(CLIPS_STORE, "readwrite");
    tx.objectStore(CLIPS_STORE).put(clip);
    tx.oncomplete = () => resolve(true);
    tx.onerror = () => reject(tx.error);
  });
}

async function getAllClips() {
  const db = await openClipsDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(CLIPS_STORE, "readonly");
    const req = tx.objectStore(CLIPS_STORE).getAll();
    req.onsuccess = () => resolve(req.result || []);
    req.onerror = () => reject(req.error);
  });
}

