// Stockage des matchs (potentiellement volumineux) via IndexedDB plutôt que localStorage,
// qui a une limite d'environ 5-10 Mo par site. Un cache mémoire garde les lectures synchrones
// pour ne pas devoir rendre tout l'appli asynchrone.
function matchesDbName() {
  const suffix = getScopeSuffix();
  return suffix ? "tf_matches_db" + suffix : "tf_matches_db";
}
const MATCHES_STORE = "matches";
const matchCache = {};
let matchCacheLoadPromise = null;

function openMatchesDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(matchesDbName(), 2);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(MATCHES_STORE)) {
        db.createObjectStore(MATCHES_STORE, { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains(OBS_STORE)) {
        db.createObjectStore(OBS_STORE, { keyPath: "id" });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function matchesDbNameFor(teamId, seasonId) {
  const suffix = (teamId === DEFAULT_TEAM_ID && seasonId === DEFAULT_SEASON_ID) ? "" : `__${teamId}__${seasonId}`;
  return suffix ? "tf_matches_db" + suffix : "tf_matches_db";
}
function readTeamMatchesSummary(teamId, seasonId) {
  return new Promise((resolve) => {
    try {
      const req = indexedDB.open(matchesDbNameFor(teamId, seasonId), 2);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(MATCHES_STORE)) db.createObjectStore(MATCHES_STORE, { keyPath: "id" });
        if (!db.objectStoreNames.contains(OBS_STORE)) db.createObjectStore(OBS_STORE, { keyPath: "id" });
      };
      req.onsuccess = () => {
        const db = req.result;
        try {
          const tx = db.transaction(MATCHES_STORE, "readonly");
          const getReq = tx.objectStore(MATCHES_STORE).getAll();
          getReq.onsuccess = () => {
            const matches = (getReq.result || []).filter((m) => m.closed);
            let wins = 0, draws = 0, losses = 0, cartons = 0;
            matches.forEach((m) => {
              const gf = m.tags.filter((t) => t.eventKey === "but" && t.team === "us").length;
              const ga = m.tags.filter((t) => t.eventKey === "but" && t.team === "opp").length;
              if (gf > ga) wins++; else if (gf < ga) losses++; else draws++;
              cartons += m.tags.filter((t) => (t.eventKey === "carton_jaune" || t.eventKey === "carton_rouge") && t.team === "us").length;
            });
            resolve({ played: matches.length, wins, draws, losses, cartons });
          };
          getReq.onerror = () => resolve({ played: 0, wins: 0, draws: 0, losses: 0, cartons: 0 });
        } catch (e) {
          resolve({ played: 0, wins: 0, draws: 0, losses: 0, cartons: 0 });
        }
      };
      req.onerror = () => resolve({ played: 0, wins: 0, draws: 0, losses: 0, cartons: 0 });
    } catch (e) {
      resolve({ played: 0, wins: 0, draws: 0, losses: 0, cartons: 0 });
    }
  });
}


function loadMatchCacheOnce() {
  if (matchCacheLoadPromise) return matchCacheLoadPromise;
  matchCacheLoadPromise = (async () => {
    try {
      const db = await openMatchesDB();
      const all = await new Promise((resolve, reject) => {
        const tx = db.transaction(MATCHES_STORE, "readonly");
        const req = tx.objectStore(MATCHES_STORE).getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => reject(req.error);
      });
      all.forEach((m) => { matchCache[m.id] = m; });
      // Migration ponctuelle : reprend d'éventuels matchs restés dans l'ancien stockage localStorage
      readIndex().forEach((summary) => {
        if (!matchCache[summary.id]) {
          try {
            const raw = localStorage.getItem(matchStorageKey(summary.id));
            if (raw) matchCache[summary.id] = JSON.parse(raw);
          } catch (e) {}
        }
      });
    } catch (e) {
      console.error("Erreur de chargement des matchs", e);
    }
  })();
  return matchCacheLoadPromise;
}

async function writeMatch(match) {
  matchCache[match.id] = match;
  try {
    const db = await openMatchesDB();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(MATCHES_STORE, "readwrite");
      tx.objectStore(MATCHES_STORE).put(match);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => reject(tx.error);
    });
    return true;
  } catch (e) {
    console.error("Erreur de sauvegarde du match", e);
    return false;
  }
}

async function deleteMatchDB(id) {
  delete matchCache[id];
  try {
    const db = await openMatchesDB();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(MATCHES_STORE, "readwrite");
      tx.objectStore(MATCHES_STORE).delete(id);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => reject(tx.error);
    });
  } catch (e) {
    console.error("Erreur de suppression du match", e);
  }
}

function readMatchFromCache(id) {
  return matchCache[id] || null;
}

function computeRatingSuggestions(match) {
  const byPlayer = {};
  match.tags.forEach((t) => {
    if (!t.player) return;
    const key = `${t.team}_${t.player}`;
    if (!byPlayer[key]) byPlayer[key] = { pos: 0, neg: 0, but: 0, rouge: 0, jaune: 0, arret: 0 };
    const ev = EVENT_MAP[t.eventKey];
    if (ev.positive) byPlayer[key].pos++; else byPlayer[key].neg++;
    if (t.eventKey === "but") byPlayer[key].but++;
    if (t.eventKey === "carton_rouge") byPlayer[key].rouge++;
    if (t.eventKey === "carton_jaune") byPlayer[key].jaune++;
    if (t.eventKey === "gardien_arret_ok") byPlayer[key].arret++;
  });

  const players = {};
  Object.entries(byPlayer).forEach(([key, d]) => {
    const total = d.pos + d.neg;
    const ratio = total > 0 ? d.pos / total : 0.5;
    let score = 5 + (ratio - 0.5) * 6;
    score += d.but * 1.2 - d.rouge * 2.5 - d.jaune * 0.6 + d.arret * 0.4;
    players[key] = Math.max(0, Math.min(10, Math.round(score * 2) / 2));
  });

  const teamAgg = { us: { pos: 0, neg: 0, but: 0 }, opp: { pos: 0, neg: 0, but: 0 } };
  match.tags.forEach((t) => {
    const ev = EVENT_MAP[t.eventKey];
    if (ev.positive) teamAgg[t.team].pos++; else teamAgg[t.team].neg++;
    if (t.eventKey === "but") teamAgg[t.team].but++;
  });
  function teamStatScore(team, other) {
    const totalT = teamAgg[team].pos + teamAgg[team].neg;
    const totalO = teamAgg[other].pos + teamAgg[other].neg;
    const ratioT = totalT > 0 ? teamAgg[team].pos / totalT : 0.5;
    const ratioO = totalO > 0 ? teamAgg[other].pos / totalO : 0.5;
    const s = 5 + (ratioT - ratioO) * 5 + (teamAgg[team].but - teamAgg[other].but) * 0.8;
    return Math.max(0, Math.min(10, Math.round(s * 2) / 2));
  }

  const teamPlayerAvg = { us: null, opp: null };
  ["us", "opp"].forEach((team) => {
    const scores = Object.entries(players)
      .filter(([k]) => k.startsWith(`${team}_`))
      .map(([, v]) => v);
    if (scores.length > 0) {
      teamPlayerAvg[team] = Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 2) / 2;
    }
  });

  return {
    players,
    team: { us: teamStatScore("us", "opp"), opp: teamStatScore("opp", "us") },
    teamPlayerAvg,
  };
}

