function TeamSeasonSelector() {
  const [teams, setTeams] = useState([]);
  const [seasons, setSeasons] = useState([]);
  const [categories, setCategories] = useState([]);
  const [activeTeam, setActiveTeam] = useState(DEFAULT_TEAM_ID);
  const [activeSeason, setActiveSeason] = useState(DEFAULT_SEASON_ID);
  const [categoryFilter, setCategoryFilter] = useState("");

  useEffect(() => {
    try { setTeams(JSON.parse(window.localStorage.getItem("tf_teams") || "[]")); } catch (e) {}
    try { setSeasons(JSON.parse(window.localStorage.getItem("tf_seasons") || "[]")); } catch (e) {}
    try { setCategories(JSON.parse(window.localStorage.getItem("tf_club_categories") || "[]")); } catch (e) {}
    setActiveTeam(getActiveTeamId());
    setActiveSeason(getActiveSeasonId());
    try { setCategoryFilter(window.localStorage.getItem("tf_category_filter") || ""); } catch (e) {}
  }, []);

  function changeCategoryFilter(value) {
    setCategoryFilter(value);
    try { window.localStorage.setItem("tf_category_filter", value); } catch (e) {}
  }

  if (teams.length <= 1 && seasons.length <= 1) return null; // rien à choisir tant qu'une seule équipe/saison existe

  const filteredTeams = categoryFilter ? teams.filter((t) => t.category === categoryFilter) : teams;

  return (
    <div className="team-season-selector">
      {categories.length > 0 && teams.length > 1 && (
        <select value={categoryFilter} onChange={(e) => changeCategoryFilter(e.target.value)}>
          <option value="">Toutes catégories</option>
          {categories.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
      )}
      {teams.length > 1 && (
        <select value={activeTeam} onChange={(e) => switchTeamAndSeason(e.target.value, activeSeason)}>
          {filteredTeams.length === 0 && <option value={activeTeam}>Aucune équipe dans cette catégorie</option>}
          {filteredTeams.map((t) => <option key={t.id} value={t.id}>{t.name}{t.category ? ` (${t.category})` : ""}{t.isEntente ? " — entente" : ""}</option>)}
        </select>
      )}
      {seasons.length > 1 && (
        <select value={activeSeason} onChange={(e) => switchTeamAndSeason(activeTeam, e.target.value)}>
          {seasons.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}
        </select>
      )}
    </div>
  );
}

// Tous les rôles possibles dans un club de foot, du bénévolat amateur jusqu'à la structure d'un
// club professionnel — un seul referentiel (les groupes), dont la liste plate (STAFF_ROLES) est
// dérivée automatiquement pour ne jamais désynchroniser les deux. Chaque rôle qui existait déjà
// avant cet ajout reste présent, formulé à l'identique, pour ne pas invalider les fiches déjà
// enregistrées.
const STAFF_FUNCTION_GROUPS = [
  { key: "direction", label: "Direction", roles: ["Président", "Vice-président", "Trésorier", "Secrétaire général", "Membre du bureau", "Directeur général", "Directeur sportif", "Directeur administratif et financier", "Directeur du centre de formation", "Directeur de la performance", "Dirigeant", "Responsable technique"] },
  { key: "coaching", label: "Coaching", roles: ["Entraîneur principal", "Entraîneur adjoint", "Entraîneur des gardiens", "Éducateur jeunes", "Coordinateur technique", "Responsable de la formation", "Responsable du football féminin"] },
  { key: "performance", label: "Performance & physique", roles: ["Préparateur physique", "Préparateur athlétique", "Préparateur des gardiens", "Préparateur mental", "Responsable performance"] },
  { key: "medical", label: "Médical", roles: ["Médecin du club", "Kinésithérapeute/Staff médical", "Ostéopathe", "Podologue", "Nutritionniste / Diététicien", "Infirmier"] },
  { key: "video", label: "Analyse & données", roles: ["Analyste vidéo", "Analyste de la performance", "Data scientist"] },
  { key: "recrutement", label: "Recrutement", roles: ["Recruteur / Scout", "Responsable recrutement"] },
  { key: "administratif", label: "Administratif & logistique", roles: ["Team manager / Intendant", "Responsable logistique", "Correspondant Footclubs / licences", "Secrétaire administratif"] },
  { key: "arbitrage", label: "Arbitrage", roles: ["Référent arbitrage", "Arbitre bénévole de club", "Arbitre officiel"] },
  { key: "communication", label: "Communication & business", roles: ["Responsable communication", "Attaché de presse", "Responsable marketing", "Responsable partenariats / sponsoring", "Responsable billetterie", "Community manager"] },
  { key: "securite", label: "Sécurité & discipline", roles: ["Responsable sécurité", "Responsable éthique et discipline"] },
  { key: "autre", label: "Autre", roles: ["Autre"] },
];
const STAFF_ROLES = STAFF_FUNCTION_GROUPS.flatMap((g) => g.roles);

function emptyStaffMember() {
  return { id: newId(), firstName: "", lastName: "", roles: [], teamIds: [], email: "", phone: "", diplomas: "", diplomaExpiry: "", honorabiliteVerifiee: false, honorabiliteDate: "", gender: "", notes: "" };
}

function staffFunctionGroup(role) {
  return STAFF_FUNCTION_GROUPS.find((g) => g.roles.includes(role)) || STAFF_FUNCTION_GROUPS[STAFF_FUNCTION_GROUPS.length - 1];
}
// Lit les rôles d'un membre du staff quel que soit le format enregistré — le nouveau tableau
// `roles`, ou l'ancien champ `role` (chaîne unique) pour les fiches créées avant l'ajout des
// rôles multiples. Rien à migrer dans le stockage : cette fonction absorbe la différence partout
// où les rôles sont lus.
function staffRoles(s) {
  if (Array.isArray(s.roles) && s.roles.length > 0) return s.roles;
  return s.role ? [s.role] : [];
}
// Vrai si l'un des rôles de la personne (un ou plusieurs) appartient au groupe donné.
function staffMemberInGroup(s, groupKey) {
  return staffRoles(s).some((r) => staffFunctionGroup(r).key === groupKey);
}
// Repère les diplômes déjà expirés ou expirant sous peu (60 jours), pour une alerte proactive —
// jusqu'ici la date n'était affichée que sur la fiche, sans jamais être mise en avant.
function isDiplomaExpiringSoon(dateStr, daysThreshold = 60) {
  if (!dateStr) return false;
  const diffDays = (new Date(dateStr) - new Date()) / (1000 * 60 * 60 * 24);
  return diffDays < daysThreshold;
}

