// Couche d'accès aux données pour le prototype de mise en relation d'arbitres — écrite en
// asynchrone dès maintenant, même si elle ne fait pour l'instant que lire/écrire le stockage
// local (le site n'a pas de serveur). Le jour où une vraie API existe pour faire circuler ça
// entre des clubs différents, seul l'INTÉRIEUR de ces fonctions change (un fetch() au lieu de
// localStorage) — les écrans qui les appellent, plus bas, n'ont rien à savoir de la différence.
async function getAllReferees() {
  try { return JSON.parse(localStorage.getItem("tf_club_referees") || "[]"); } catch (e) { return []; }
}
async function saveReferee(referee) {
  const all = await getAllReferees();
  const exists = all.some((r) => r.id === referee.id);
  const next = exists ? all.map((r) => (r.id === referee.id ? referee : r)) : [...all, referee];
  localStorage.setItem("tf_club_referees", JSON.stringify(next));
  return referee;
}
async function removeReferee(id) {
  const all = await getAllReferees();
  localStorage.setItem("tf_club_referees", JSON.stringify(all.filter((r) => r.id !== id)));
  return true;
}
async function getProposals() {
  try { return JSON.parse(localStorage.getItem("tf_referee_proposals") || "[]"); } catch (e) { return []; }
}
async function createProposal(proposal) {
  const all = await getProposals();
  localStorage.setItem("tf_referee_proposals", JSON.stringify([...all, proposal]));
  return proposal;
}
async function respondToProposal(proposalId, refereeId, refereeName) {
  const all = await getProposals();
  const next = all.map((p) => {
    if (p.id !== proposalId) return p;
    if (p.responses.some((r) => r.refereeId === refereeId)) return p; // déjà répondu, pas de doublon
    return { ...p, responses: [...p.responses, { refereeId, refereeName, respondedAt: Date.now() }] };
  });
  localStorage.setItem("tf_referee_proposals", JSON.stringify(next));
  return true;
}
async function setProposalStatus(proposalId, status) {
  const all = await getProposals();
  localStorage.setItem("tf_referee_proposals", JSON.stringify(all.map((p) => (p.id === proposalId ? { ...p, status } : p))));
  return true;
}
async function removeProposal(proposalId) {
  const all = await getProposals();
  localStorage.setItem("tf_referee_proposals", JSON.stringify(all.filter((p) => p.id !== proposalId)));
  return true;
}

