function ChecklistDeplacementScreen() {
  const [checklists, setChecklists] = useState([]);
  const [fixtures, setFixtures] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [pickedFixtureKey, setPickedFixtureKey] = useState("");
  const [openChecklistId, setOpenChecklistId] = useState(null);

  useEffect(() => {
    try { setChecklists(JSON.parse(localStorage.getItem("tf_travel_checklists") || "[]")); } catch (e) {}
    try {
      const comp = loadCompetitionsData();
      const all = comp.competitions.flatMap((c) => c.fixtures.map((f) => ({ key: `${c.id}_${f.id}`, label: `${formatDateFr(f.date)} — vs ${f.opponent}`, date: f.date })));
      setFixtures(all.filter((f) => f.date >= todayIso()).sort((a, b) => new Date(a.date) - new Date(b.date)));
    } catch (e) { setFixtures([]); }
    setLoaded(true);
  }, []);

  function persist(next) {
    setChecklists(next);
    try { localStorage.setItem("tf_travel_checklists", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function createChecklist() {
    if (!pickedFixtureKey) { alert("Choisis un match."); return; }
    if (checklists.some((c) => c.fixtureKey === pickedFixtureKey)) { alert("Une checklist existe déjà pour ce match."); return; }
    const fixture = fixtures.find((f) => f.key === pickedFixtureKey);
    const created = emptyTravelChecklist(pickedFixtureKey, fixture ? fixture.label : "Match");
    persist([...checklists, created]);
    setOpenChecklistId(created.id);
    setPickedFixtureKey("");
  }
  function toggleItem(checklistId, itemId) {
    persist(checklists.map((c) => (c.id === checklistId ? { ...c, items: c.items.map((i) => (i.id === itemId ? { ...i, checked: !i.checked } : i)) } : c)));
  }
  function addCustomItem(checklistId, label) {
    if (!label.trim()) { alert("Décris l'élément avant de l'ajouter."); return; }
    persist(checklists.map((c) => (c.id === checklistId ? { ...c, items: [...c.items, { id: newId(), label: label.trim(), checked: false }] } : c)));
  }
  function removeItem(checklistId, itemId) {
    persist(checklists.map((c) => (c.id === checklistId ? { ...c, items: c.items.filter((i) => i.id !== itemId) } : c)));
  }
  function removeChecklist(id) {
    if (!confirm("Supprimer cette checklist ?")) return;
    persist(checklists.filter((c) => c.id !== id));
    if (openChecklistId === id) setOpenChecklistId(null);
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  if (openChecklistId) {
    const cl = checklists.find((c) => c.id === openChecklistId);
    if (!cl) { setOpenChecklistId(null); return null; }
    const doneCount = cl.items.filter((i) => i.checked).length;
    return (
      <div>
        <button className="btn btn-ghost btn-small" onClick={() => setOpenChecklistId(null)} style={{ marginBottom: 14 }}>‹ Retour</button>
        <div className="panel-heading" style={{ marginTop: 0 }}>{cl.fixtureLabel} — {doneCount}/{cl.items.length}</div>
        <div className="scouting-list" style={{ marginBottom: 16 }}>
          {cl.items.map((item) => (
            <label key={item.id} className="scout-obs-row" style={{ cursor: "pointer" }}>
              <span style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <input type="checkbox" checked={item.checked} onChange={() => toggleItem(cl.id, item.id)} />
                <span style={item.checked ? { textDecoration: "line-through", opacity: 0.6 } : undefined}>{item.label}</span>
              </span>
              <button className="icon-btn" onClick={(e) => { e.preventDefault(); removeItem(cl.id, item.id); }} aria-label="Retirer"><X size={12} /></button>
            </label>
          ))}
        </div>
        <div className="scout-obs-add">
          <input type="text" placeholder="Ajouter un point (optionnel)" value={cl.customLabel} onChange={(e) => persist(checklists.map((c) => (c.id === cl.id ? { ...c, customLabel: e.target.value } : c)))} />
          <button className="btn btn-ghost btn-small" onClick={() => { addCustomItem(cl.id, cl.customLabel); persist(checklists.map((c) => (c.id === cl.id ? { ...c, customLabel: "" } : c))); }}>+ Ajouter</button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Checklist avant un déplacement — transport, trousse médicale, kit complet. Choisis le match concerné, coche au fur et à mesure.</p>
      <div className="scout-obs-add" style={{ marginBottom: 16 }}>
        <select value={pickedFixtureKey} onChange={(e) => setPickedFixtureKey(e.target.value)}>
          <option value="">Choisir un match à venir…</option>
          {fixtures.filter((f) => !checklists.some((c) => c.fixtureKey === f.key)).map((f) => <option key={f.key} value={f.key}>{f.label}</option>)}
        </select>
        <button className="btn btn-primary btn-small" onClick={createChecklist}>+ Créer la checklist</button>
      </div>
      {checklists.length === 0 && <div className="empty-state">Aucune checklist créée pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {checklists.map((cl) => {
          const doneCount = cl.items.filter((i) => i.checked).length;
          return (
            <div className="scouting-card" key={cl.id} onClick={() => setOpenChecklistId(cl.id)} style={{ cursor: "pointer" }}>
              <div className="scouting-info">
                <div className="scouting-name">{cl.fixtureLabel} <span className="scouting-club">{doneCount}/{cl.items.length}</span></div>
              </div>
              <button className="icon-btn" onClick={(e) => { e.stopPropagation(); removeChecklist(cl.id); }} aria-label="Supprimer"><X size={14} /></button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

