function ClubTournamentsScreen() {
  const [tournaments, setTournaments] = useState([]);
  const [registrations, setRegistrations] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [tab, setTab] = useState("liste");
  const [showTournamentForm, setShowTournamentForm] = useState(false);
  const [tournamentForm, setTournamentForm] = useState(emptyTournament());
  const [registeringId, setRegisteringId] = useState(null);
  const [regForm, setRegForm] = useState(emptyTournamentRegistration(""));
  const [manageTournamentId, setManageTournamentId] = useState(null);

  async function refresh() {
    const [t, r] = await Promise.all([getAllTournaments(), getAllRegistrations()]);
    setTournaments(t);
    setRegistrations(r);
    setLoaded(true);
  }
  useEffect(() => { refresh(); }, []);

  async function handleSaveTournament() {
    if (!tournamentForm.name.trim()) { alert("Donne un nom à ce tournoi/événement."); return; }
    await saveTournament(tournamentForm);
    await refresh();
    setShowTournamentForm(false);
    setTournamentForm(emptyTournament());
  }
  async function handleRemoveTournament(id) {
    if (!confirm("Supprimer ce tournoi et toutes ses inscriptions ?")) return;
    await removeTournament(id);
    await refresh();
  }
  async function handleRegister() {
    if (!regForm.teamName.trim()) { alert("Indique le nom de ton équipe."); return; }
    await registerForTournament(regForm);
    await refresh();
    setRegisteringId(null);
    setRegForm(emptyTournamentRegistration(""));
  }
  async function handleSetRegStatus(id, status) {
    await setRegistrationStatus(id, status);
    await refresh();
  }
  async function handleRemoveReg(id) {
    if (!confirm("Retirer cette inscription ?")) return;
    await removeRegistration(id);
    await refresh();
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  if (manageTournamentId) {
    const t = tournaments.find((x) => x.id === manageTournamentId);
    if (!t) { setManageTournamentId(null); return null; }
    const regsForT = registrations.filter((r) => r.tournamentId === t.id);
    return (
      <div>
        <button className="btn btn-ghost btn-small" onClick={() => setManageTournamentId(null)} style={{ marginBottom: 14 }}>‹ Retour</button>
        <div className="panel-heading" style={{ marginTop: 0 }}>{t.name} — inscriptions ({regsForT.length}{t.maxTeams ? `/${t.maxTeams}` : ""})</div>
        {regsForT.length === 0 && <div className="empty-state">Aucune inscription pour l'instant.</div>}
        <div className="scouting-list">
          {regsForT.map((r) => (
            <div className="scouting-card" key={r.id}>
              <div className="scouting-info">
                <div className="scouting-name">{r.teamName} <span className="scouting-club">{REGISTRATION_STATUSES[r.status]}</span></div>
                <div className="scouting-meta">Contact : {r.contactName}{r.contactInfo ? ` · ${r.contactInfo}` : ""}</div>
              </div>
              {r.status === "en_attente" && (
                <div style={{ display: "flex", gap: 6 }}>
                  <button className="btn btn-ghost btn-small" onClick={() => handleSetRegStatus(r.id, "confirmee")}>Confirmer</button>
                  <button className="btn btn-ghost btn-small" onClick={() => handleSetRegStatus(r.id, "refusee")}>Refuser</button>
                </div>
              )}
              <button className="icon-btn" onClick={() => handleRemoveReg(r.id)} aria-label="Supprimer"><X size={14} /></button>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Prototype pour tester l'intérêt d'une plateforme de matchs amicaux et tournois entre clubs — comme pour les arbitres, tout reste pour l'instant dans ton navigateur, pas encore une vraie mise en relation entre clubs différents (ça demanderait un vrai serveur).</p>

      <div className="tabs" style={{ marginBottom: 14 }}>
        <button className={`tab ${tab === "liste" ? "active" : ""}`} onClick={() => setTab("liste")}>Tournois disponibles ({tournaments.filter((t) => t.status === "ouvert").length})</button>
        <button className={`tab ${tab === "organises" ? "active" : ""}`} onClick={() => setTab("organises")}>Mes tournois organisés ({tournaments.length})</button>
      </div>

      {tab === "organises" && (
        <>
          {!showTournamentForm && <button className="btn btn-primary btn-large" onClick={() => setShowTournamentForm(true)} style={{ marginBottom: 16 }}>+ Organiser un tournoi/événement</button>}
          {showTournamentForm && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <label>Nom<input type="text" placeholder="ex. Tournoi de printemps U15" value={tournamentForm.name} onChange={(e) => setTournamentForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
              <label>Club organisateur<input type="text" value={tournamentForm.organizingClub} onChange={(e) => setTournamentForm((f) => ({ ...f, organizingClub: e.target.value }))} /></label>
              <div className="roster-physical-grid">
                <label>Date de début<input type="date" value={tournamentForm.startDate} onChange={(e) => setTournamentForm((f) => ({ ...f, startDate: e.target.value }))} /></label>
                <label>Date de fin<input type="date" value={tournamentForm.endDate} onChange={(e) => setTournamentForm((f) => ({ ...f, endDate: e.target.value }))} /></label>
              </div>
              <label>Lieu<input type="text" value={tournamentForm.location} onChange={(e) => setTournamentForm((f) => ({ ...f, location: e.target.value }))} /></label>
              <div className="roster-physical-grid">
                <label>Catégorie d'âge<input type="text" placeholder="ex. U15" value={tournamentForm.ageCategory} onChange={(e) => setTournamentForm((f) => ({ ...f, ageCategory: e.target.value }))} /></label>
                <label>Nombre d'équipes max<input type="number" min="2" value={tournamentForm.maxTeams} onChange={(e) => setTournamentForm((f) => ({ ...f, maxTeams: Number(e.target.value) }))} /></label>
              </div>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => setShowTournamentForm(false)}>Annuler</button>
                <button className="btn btn-primary" onClick={handleSaveTournament}>Créer</button>
              </div>
            </div>
          )}
          {tournaments.length === 0 && <div className="empty-state">Aucun tournoi organisé pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
          <div className="scouting-list">
            {tournaments.map((t) => {
              const count = registrations.filter((r) => r.tournamentId === t.id).length;
              return (
                <div className="scouting-card" key={t.id} onClick={() => setManageTournamentId(t.id)} style={{ cursor: "pointer" }}>
                  <div className="scouting-info">
                    <div className="scouting-name">{t.name} <span className="scouting-club">{TOURNAMENT_STATUSES[t.status]}</span></div>
                    <div className="scouting-meta">{formatDateFr(t.startDate)}{t.endDate ? ` → ${formatDateFr(t.endDate)}` : ""}{t.location ? ` · ${t.location}` : ""}</div>
                    <div className="scouting-meta">{count} inscription{count !== 1 ? "s" : ""}{t.maxTeams ? `/${t.maxTeams}` : ""}</div>
                  </div>
                  <button className="icon-btn" onClick={(e) => { e.stopPropagation(); handleRemoveTournament(t.id); }} aria-label="Supprimer"><X size={14} /></button>
                </div>
              );
            })}
          </div>
        </>
      )}

      {tab === "liste" && (
        <div className="scouting-list">
          {tournaments.filter((t) => t.status === "ouvert").length === 0 && <div className="empty-state">Aucun tournoi ouvert aux inscriptions pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
          {tournaments.filter((t) => t.status === "ouvert").map((t) => {
            const count = registrations.filter((r) => r.tournamentId === t.id).length;
            const full = t.maxTeams && count >= t.maxTeams;
            return (
              <div className="scouting-card" key={t.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
                <div className="scouting-info">
                  <div className="scouting-name">{t.name}</div>
                  <div className="scouting-meta">{formatDateFr(t.startDate)}{t.endDate ? ` → ${formatDateFr(t.endDate)}` : ""}{t.location ? ` · ${t.location}` : ""}{t.ageCategory ? ` · ${t.ageCategory}` : ""}</div>
                  <div className="scouting-meta">Organisé par {t.organizingClub || "non précisé"} · {count} inscription{count !== 1 ? "s" : ""}{t.maxTeams ? `/${t.maxTeams}` : ""}{full ? " · complet" : ""}</div>
                </div>
                {!full && (
                  registeringId === t.id ? (
                    <div style={{ marginTop: 8 }}>
                      <label>Nom de ton équipe<input type="text" value={regForm.teamName} onChange={(e) => setRegForm((f) => ({ ...f, tournamentId: t.id, teamName: e.target.value }))} autoFocus /></label>
                      <label>Contact<input type="text" placeholder="Ton nom" value={regForm.contactName} onChange={(e) => setRegForm((f) => ({ ...f, contactName: e.target.value }))} /></label>
                      <label>Téléphone ou email<input type="text" value={regForm.contactInfo} onChange={(e) => setRegForm((f) => ({ ...f, contactInfo: e.target.value }))} /></label>
                      <div className="form-actions">
                        <button className="btn btn-ghost" onClick={() => setRegisteringId(null)}>Annuler</button>
                        <button className="btn btn-primary" onClick={handleRegister}>S'inscrire</button>
                      </div>
                    </div>
                  ) : (
                    <button className="btn btn-ghost btn-small" style={{ marginTop: 8, alignSelf: "flex-start" }} onClick={() => { setRegisteringId(t.id); setRegForm(emptyTournamentRegistration(t.id)); }}>S'inscrire</button>
                  )
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ClubRefereesScreen() {
  const [referees, setReferees] = useState([]);
  const [proposals, setProposals] = useState([]);
  const [reports, setReports] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [subTab, setSubTab] = useState("repertoire");
  const [showRefForm, setShowRefForm] = useState(false);
  const [refForm, setRefForm] = useState(emptyReferee());
  const [showProposalForm, setShowProposalForm] = useState(false);
  const [proposalForm, setProposalForm] = useState(emptyMatchProposal());
  const [respondingProposalId, setRespondingProposalId] = useState(null);
  const [respondingRefId, setRespondingRefId] = useState("");

  async function refresh() {
    const [refs, props] = await Promise.all([getAllReferees(), getProposals()]);
    setReferees(refs);
    setProposals(props);
    try { setReports(JSON.parse(localStorage.getItem("tf_referee_reports") || "[]")); } catch (e) {}
    setLoaded(true);
  }
  useEffect(() => { refresh(); }, []);

  async function handleSaveReferee() {
    if (!refForm.name.trim()) { alert("Donne un nom à cet arbitre."); return; }
    await saveReferee(refForm);
    await refresh();
    setShowRefForm(false);
    setRefForm(emptyReferee());
  }
  async function handleRemoveReferee(id) {
    if (!confirm("Retirer cet arbitre du répertoire ?")) return;
    await removeReferee(id);
    await refresh();
  }
  async function handleCreateProposal() {
    if (!proposalForm.title.trim()) { alert("Donne un titre à cette proposition."); return; }
    if (!proposalForm.date) { alert("Choisis une date."); return; }
    await createProposal(proposalForm);
    await refresh();
    setShowProposalForm(false);
    setProposalForm(emptyMatchProposal());
  }
  async function handleRespond() {
    if (!respondingRefId) { alert("Choisis un arbitre."); return; }
    const ref = referees.find((r) => r.id === respondingRefId);
    if (!ref) return;
    await respondToProposal(respondingProposalId, ref.id, ref.name);
    await refresh();
    setRespondingProposalId(null);
    setRespondingRefId("");
  }
  async function handleSetStatus(id, status) {
    await setProposalStatus(id, status);
    await refresh();
  }
  async function handleRemoveProposal(id) {
    if (!confirm("Supprimer cette proposition ?")) return;
    await removeProposal(id);
    await refresh();
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Prototype pour tester l'intérêt d'une mise en relation d'arbitres entre clubs pour les amicaux/tournois hors désignation officielle. Utile pour te faire une idée du fonctionnement ou pour faire une démonstration à d'autres coachs — voir la remarque en bas de page sur ce que ça ne fait pas encore.</p>

      <div className="tabs" style={{ marginBottom: 14 }}>
        <button className={`tab ${subTab === "repertoire" ? "active" : ""}`} onClick={() => setSubTab("repertoire")}>Répertoire ({referees.length})</button>
        <button className={`tab ${subTab === "propositions" ? "active" : ""}`} onClick={() => setSubTab("propositions")}>Propositions de match ({proposals.length})</button>
      </div>

      {subTab === "repertoire" && (
        <>
          {!showRefForm && <button className="btn btn-primary btn-large" onClick={() => setShowRefForm(true)} style={{ marginBottom: 16 }}>+ Ajouter un arbitre</button>}
          {showRefForm && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <label>Nom<input type="text" value={refForm.name} onChange={(e) => setRefForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
              <label>Niveau
                <select value={refForm.level} onChange={(e) => setRefForm((f) => ({ ...f, level: e.target.value }))}>
                  {REFEREE_LEVELS.map((l) => <option key={l} value={l}>{l}</option>)}
                </select>
              </label>
              <label>Ville<input type="text" value={refForm.city} onChange={(e) => setRefForm((f) => ({ ...f, city: e.target.value }))} /></label>
              <label>Contact<input type="text" placeholder="Téléphone ou email" value={refForm.contact} onChange={(e) => setRefForm((f) => ({ ...f, contact: e.target.value }))} /></label>
              <label style={{ display: "block" }}>
                <input type="checkbox" checked={refForm.availableForExternal} onChange={(e) => setRefForm((f) => ({ ...f, availableForExternal: e.target.checked }))} style={{ marginRight: 6 }} />
                Disponible pour des propositions externes (amicaux, tournois)
              </label>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => setShowRefForm(false)}>Annuler</button>
                <button className="btn btn-primary" onClick={handleSaveReferee}>Enregistrer</button>
              </div>
            </div>
          )}
          {referees.length === 0 && <div className="empty-state">Aucun arbitre enregistré pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
          <div className="scouting-list">
            {referees.map((r) => {
              const linkedReports = reports.filter((rep) => rep.refereeId === r.id);
              const avgRating = linkedReports.length > 0 ? Math.round((linkedReports.reduce((s, rep) => s + Number(rep.rating || 0), 0) / linkedReports.length) * 10) / 10 : null;
              return (
                <div className="scouting-card" key={r.id}>
                  <div className="scouting-info">
                    <div className="scouting-name">{r.name} <span className="scouting-club">{r.level}</span></div>
                    <div className="scouting-meta">{r.city}{r.contact ? ` · ${r.contact}` : ""}</div>
                    <div className="scouting-meta">{r.availableForExternal ? "Disponible pour propositions externes" : "Non disponible en externe"}</div>
                    {linkedReports.length > 0 && <div className="scouting-meta">{linkedReports.length} compte-rendu{linkedReports.length > 1 ? "s" : ""} · note moyenne {avgRating}/5</div>}
                  </div>
                  <button className="icon-btn" onClick={() => handleRemoveReferee(r.id)} aria-label="Supprimer"><X size={14} /></button>
                </div>
              );
            })}
          </div>
        </>
      )}

      {subTab === "propositions" && (
        <>
          {!showProposalForm && <button className="btn btn-primary btn-large" onClick={() => setShowProposalForm(true)} style={{ marginBottom: 16 }}>+ Nouvelle proposition</button>}
          {showProposalForm && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <label>Titre<input type="text" placeholder="ex. Tournoi U15 du 12 octobre" value={proposalForm.title} onChange={(e) => setProposalForm((f) => ({ ...f, title: e.target.value }))} autoFocus /></label>
              <div className="roster-physical-grid">
                <label>Date<input type="date" value={proposalForm.date} onChange={(e) => setProposalForm((f) => ({ ...f, date: e.target.value }))} /></label>
                <label>Lieu<input type="text" value={proposalForm.location} onChange={(e) => setProposalForm((f) => ({ ...f, location: e.target.value }))} /></label>
              </div>
              <label>Niveau requis
                <select value={proposalForm.levelRequired} onChange={(e) => setProposalForm((f) => ({ ...f, levelRequired: e.target.value }))}>
                  {REFEREE_LEVELS.map((l) => <option key={l} value={l}>{l}</option>)}
                </select>
              </label>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => setShowProposalForm(false)}>Annuler</button>
                <button className="btn btn-primary" onClick={handleCreateProposal}>Créer</button>
              </div>
            </div>
          )}
          {proposals.length === 0 && <div className="empty-state">Aucune proposition pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
          <div className="scouting-list">
            {proposals.map((p) => (
              <div className="scouting-card" key={p.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
                <div className="scouting-info">
                  <div className="scouting-name">{p.title} <span className="scouting-club">{PROPOSAL_STATUSES[p.status]}</span></div>
                  <div className="scouting-meta">{formatDateFr(p.date)}{p.location ? ` · ${p.location}` : ""} · Niveau {p.levelRequired}</div>
                  <div className="scouting-meta">{p.responses.length} arbitre{p.responses.length !== 1 ? "s" : ""} intéressé{p.responses.length !== 1 ? "s" : ""}{p.responses.length > 0 ? ` : ${p.responses.map((r) => r.refereeName).join(", ")}` : ""}</div>
                </div>
                {p.status === "open" && (
                  <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8, alignItems: "center" }}>
                    {respondingProposalId === p.id ? (
                      <>
                        <select value={respondingRefId} onChange={(e) => setRespondingRefId(e.target.value)}>
                          <option value="">Choisir un arbitre…</option>
                          {referees.filter((r) => r.availableForExternal).map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button className="btn btn-ghost btn-small" onClick={handleRespond}>Confirmer l'intérêt</button>
                        <button className="btn btn-ghost btn-small" onClick={() => setRespondingProposalId(null)}>Annuler</button>
                      </>
                    ) : (
                      <button className="btn btn-ghost btn-small" onClick={() => setRespondingProposalId(p.id)}>Simuler une réponse d'arbitre</button>
                    )}
                    <button className="btn btn-ghost btn-small" onClick={() => handleSetStatus(p.id, "filled")}>Marquer pourvue</button>
                    <button className="btn btn-ghost btn-small" onClick={() => handleSetStatus(p.id, "cancelled")}>Annuler la proposition</button>
                  </div>
                )}
                <button className="icon-btn" style={{ alignSelf: "flex-end", marginTop: 6 }} onClick={() => handleRemoveProposal(p.id)} aria-label="Supprimer">
                  <X size={14} />
                </button>
              </div>
            ))}
          </div>
        </>
      )}

      <p className="hint" style={{ marginTop: 20 }}>Rappel : comme le Forum, ceci reste pour l'instant dans ton propre navigateur — utile pour se faire une idée ou faire une démonstration, mais pas encore une vraie mise en relation entre des clubs différents (ça demanderait un vrai serveur).</p>
    </div>
  );
}

function ClubStaffScreen({ teams }) {
  const [staff, setStaff] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyStaffMember());
  const [loaded, setLoaded] = useState(false);
  const [staffTab, setStaffTab] = useState("coaching");
  const [rolePickValue, setRolePickValue] = useState("");

  useEffect(() => {
    try { setStaff(JSON.parse(window.localStorage.getItem("tf_club_staff") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setStaff(next);
    try { window.localStorage.setItem("tf_club_staff", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function openNew() { setForm(emptyStaffMember()); setEditingId(null); setShowForm(true); setRolePickValue(""); }
  function openEdit(s) { setForm({ ...emptyStaffMember(), ...s, roles: staffRoles(s) }); setEditingId(s.id); setShowForm(true); setRolePickValue(""); }
  function save() {
    if (!form.firstName.trim() && !form.lastName.trim()) { alert("Renseigne au moins un nom."); return; }
    if (form.roles.length === 0) { alert("Choisis au moins un rôle."); return; }
    if (editingId) persist(staff.map((s) => (s.id === editingId ? form : s)));
    else persist([...staff, form]);
    setShowForm(false);
  }
  function remove(id) {
    const person = staff.find((s) => s.id === id);
    let trainingCount = 0, meetingCount = 0, childProtectionCount = 0;
    try {
      trainingCount = JSON.parse(localStorage.getItem("tf_club_trainings") || "[]").filter((t) => t.staffId === id).length;
    } catch (e) {}
    try {
      meetingCount = JSON.parse(localStorage.getItem("tf_club_meetings") || "[]").filter((m) => (m.attendeeStaffIds || []).includes(id)).length;
    } catch (e) {}
    try {
      childProtectionCount = JSON.parse(localStorage.getItem("tf_child_protection_trainings") || "[]").filter((t) => t.staffId === id).length;
    } catch (e) {}

    let message = `Supprimer la fiche de ${person ? `${person.firstName} ${person.lastName}` : "ce membre"} du staff ?`;
    const details = [];
    if (trainingCount > 0) details.push(`${trainingCount} formation${trainingCount > 1 ? "s" : ""} suivie${trainingCount > 1 ? "s" : ""}`);
    if (meetingCount > 0) details.push(`présent${meetingCount > 1 ? "s" : ""} à ${meetingCount} réunion${meetingCount > 1 ? "s" : ""}`);
    if (childProtectionCount > 0) details.push(`${childProtectionCount} formation${childProtectionCount > 1 ? "s" : ""} protection de l'enfance`);
    message += details.length > 0
      ? ` Cette personne apparaît dans ${details.join(", ")} — ces données resteront stockées mais ne mentionneront plus qui elles étaient.`
      : "";
    if (!confirm(message)) return;
    persist(staff.filter((s) => s.id !== id));
  }
  function toggleTeam(teamId) {
    setForm((f) => ({ ...f, teamIds: f.teamIds.includes(teamId) ? f.teamIds.filter((x) => x !== teamId) : [...f.teamIds, teamId] }));
  }
  function addRole() {
    if (!rolePickValue) { alert("Choisis d'abord un rôle dans la liste."); return; }
    setForm((f) => (f.roles.includes(rolePickValue) ? f : { ...f, roles: [...f.roles, rolePickValue] }));
    setRolePickValue("");
  }
  function removeRole(role) {
    setForm((f) => ({ ...f, roles: f.roles.filter((r) => r !== role) }));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const expiring = staff.filter((s) => isDiplomaExpiringSoon(s.diplomaExpiry));
  const notVerified = staff.filter((s) => !s.honorabiliteVerifiee);

  return (
    <div>
      <p className="radar-note">Répertoire du staff du club — chaque membre peut être rattaché à une ou plusieurs équipes. Sert de base aux autres fonctionnalités club (formations, créneaux, comptes-rendus...).</p>

      {expiring.length > 0 && (
        <div className="empty-state" style={{ borderColor: "var(--crimson)", marginBottom: 14 }}>
          {expiring.length} diplôme{expiring.length > 1 ? "s" : ""} expiré{expiring.length > 1 ? "s" : ""} ou à renouveler sous 60 jours — {expiring.map((s) => `${s.firstName} ${s.lastName}`).join(", ")}.
        </div>
      )}
      {notVerified.length > 0 && (
        <div className="empty-state" style={{ borderColor: "var(--crimson)", marginBottom: 14 }}>
          {notVerified.length} membre{notVerified.length > 1 ? "s" : ""} du staff sans contrôle d'honorabilité enregistré — {notVerified.map((s) => `${s.firstName} ${s.lastName}`).join(", ")}.
        </div>
      )}

      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Ajouter un membre du staff</button>}

      {showForm && (
        <div className="new-match-card">
          <div className="roster-physical-grid">
            <label>Prénom<input type="text" value={form.firstName} onChange={(e) => setForm((f) => ({ ...f, firstName: e.target.value }))} /></label>
            <label>Nom<input type="text" value={form.lastName} onChange={(e) => setForm((f) => ({ ...f, lastName: e.target.value }))} /></label>
          </div>
          <label>Rôle(s)
            <div style={{ display: "flex", gap: 8 }}>
              <select value={rolePickValue} onChange={(e) => setRolePickValue(e.target.value)} style={{ flex: 1 }}>
                <option value="">Choisir un rôle à ajouter…</option>
                {STAFF_FUNCTION_GROUPS.map((g) => (
                  <optgroup key={g.key} label={g.label}>
                    {g.roles.filter((r) => !form.roles.includes(r)).map((r) => <option key={r} value={r}>{r}</option>)}
                  </optgroup>
                ))}
              </select>
              <button type="button" className="btn btn-ghost btn-small" onClick={addRole}>+ Ajouter</button>
            </div>
          </label>
          {form.roles.length > 0 && (
            <div className="qcm-options" style={{ marginTop: 6 }}>
              {form.roles.map((r) => (
                <button key={r} type="button" className="qcm-option selected" onClick={() => removeRole(r)}>{r} ✕</button>
              ))}
            </div>
          )}
          <div className="radar-range-label">Équipe(s) encadrée(s)</div>
          <div className="qcm-options">
            {teams.map((t) => (
              <button key={t.id} className={`qcm-option ${form.teamIds.includes(t.id) ? "selected" : ""}`} onClick={() => toggleTeam(t.id)}>{t.name}</button>
            ))}
          </div>
          <div className="roster-physical-grid">
            <label>Email<input type="email" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></label>
            <label>Téléphone<input type="text" value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></label>
          </div>
          <div className="roster-physical-grid">
            <label>Diplômes<input type="text" placeholder="ex. BMF, DEF" value={form.diplomas} onChange={(e) => setForm((f) => ({ ...f, diplomas: e.target.value }))} /></label>
            <label>Expiration/renouvellement<input type="date" value={form.diplomaExpiry} onChange={(e) => setForm((f) => ({ ...f, diplomaExpiry: e.target.value }))} /></label>
          </div>
          <label style={{ display: "block", marginTop: 8 }}>
            <input type="checkbox" checked={form.honorabiliteVerifiee} onChange={(e) => setForm((f) => ({ ...f, honorabiliteVerifiee: e.target.checked, honorabiliteDate: e.target.checked ? (f.honorabiliteDate || todayIso()) : f.honorabiliteDate }))} style={{ marginRight: 6 }} />
            Contrôle d'honorabilité effectué (protection des mineurs)
          </label>
          {form.honorabiliteVerifiee && (
            <label>Date de vérification<input type="date" value={form.honorabiliteDate} onChange={(e) => setForm((f) => ({ ...f, honorabiliteDate: e.target.value }))} /></label>
          )}
          <label>Genre (optionnel — sert uniquement aux statistiques de mixité de l'encadrement)
            <select value={form.gender} onChange={(e) => setForm((f) => ({ ...f, gender: e.target.value }))}>
              <option value="">Non précisé</option>
              <option value="F">Femme</option>
              <option value="M">Homme</option>
            </select>
          </label>
          <label>Notes<textarea rows={2} value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}

      <div className="tabs" style={{ marginTop: 16 }}>
        {STAFF_FUNCTION_GROUPS.map((g) => (
          <button key={g.key} className={`tab ${staffTab === g.key ? "active" : ""}`} onClick={() => setStaffTab(g.key)}>
            {g.label} <span className="scouting-club">({staff.filter((s) => staffMemberInGroup(s, g.key)).length})</span>
          </button>
        ))}
      </div>

      <div className="roster-grid" style={{ marginTop: 12 }}>
        {staff.length === 0 && <div className="empty-state">Aucun membre du staff enregistré pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
        {staff.length > 0 && staff.filter((s) => staffMemberInGroup(s, staffTab)).length === 0 && (
          <div className="empty-state">Personne en « {STAFF_FUNCTION_GROUPS.find((g) => g.key === staffTab)?.label} » pour l'instant.</div>
        )}
        {staff.filter((s) => staffMemberInGroup(s, staffTab)).map((s) => (
          <div className="roster-card" key={s.id} onClick={() => openEdit(s)} style={{ cursor: "pointer" }}>
            <div className="roster-card-info">
              <div className="roster-card-name">{s.firstName} {s.lastName}</div>
              <div className="roster-card-position">{staffRoles(s).join(", ")}</div>
              <div className="roster-card-usage">
                {s.teamIds.map((tid) => teams.find((t) => t.id === tid)).filter(Boolean).map((t) => t.name).join(", ") || "Aucune équipe rattachée"}
              </div>
              {s.diplomas && (
                <div className="roster-card-meta" style={isDiplomaExpiringSoon(s.diplomaExpiry) ? { color: "var(--crimson)" } : undefined}>
                  {s.diplomas}{s.diplomaExpiry ? ` — renouvellement le ${formatDateFr(s.diplomaExpiry)}` : ""}
                </div>
              )}
              <div className="roster-card-meta" style={!s.honorabiliteVerifiee ? { color: "var(--crimson)" } : undefined}>
                {s.honorabiliteVerifiee ? `Honorabilité vérifiée le ${formatDateFr(s.honorabiliteDate)}` : "Contrôle d'honorabilité non renseigné"}
              </div>
            </div>
            <div className="roster-card-actions">
              <button className="icon-btn" onClick={(e) => { e.stopPropagation(); remove(s.id); }} aria-label="Supprimer"><X size={14} /></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function emptySportingProject() {
  return { vision: "", horizonYears: 3, objectives: [] };
}
function emptyProjectObjective(year) {
  return { id: newId(), year: year || new Date().getFullYear(), title: "", description: "", status: "À venir" };
}
const PROJECT_OBJECTIVE_STATUSES = ["À venir", "En cours", "Atteint", "Reporté"];

function SportingProjectScreen() {
  const [data, setData] = useState(emptySportingProject());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setData({ ...emptySportingProject(), ...JSON.parse(window.localStorage.getItem("tf_club_sporting_project") || "{}") }); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setData(next);
    try { window.localStorage.setItem("tf_club_sporting_project", JSON.stringify(next)); } catch (e) {}
  }
  function addObjective() {
    persist({ ...data, objectives: [...data.objectives, emptyProjectObjective(new Date().getFullYear())] });
  }
  function updateObjective(id, field, value) {
    persist({ ...data, objectives: data.objectives.map((o) => (o.id === id ? { ...o, [field]: value } : o)) });
  }
  function removeObjective(id) {
    if (!confirm("Supprimer cet objectif ?")) return;
    persist({ ...data, objectives: data.objectives.filter((o) => o.id !== id) });
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">La direction générale du club sur plusieurs saisons — sert de fil conducteur aux projets de jeu de chaque équipe, sans les remplacer.</p>
      <div className="new-match-card">
        <label>Vision générale<textarea rows={3} placeholder="ex. Devenir une référence régionale de formation, avec un jeu offensif et une identité claire du gardien à l'attaquant." value={data.vision} onChange={(e) => persist({ ...data, vision: e.target.value })} /></label>
        <label>Horizon (années)<input type="number" min="1" max="10" value={data.horizonYears} onChange={(e) => persist({ ...data, horizonYears: Number(e.target.value) })} /></label>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Objectifs par échéance</div>
      <div className="scouting-list">
        {data.objectives.sort((a, b) => a.year - b.year).map((o) => (
          <div className="scouting-card" key={o.id} style={{ flexWrap: "wrap" }}>
            <div className="scouting-info">
              <div className="roster-physical-grid">
                <label>Année<input type="number" value={o.year} onChange={(e) => updateObjective(o.id, "year", Number(e.target.value))} /></label>
                <label>Statut
                  <select value={o.status} onChange={(e) => updateObjective(o.id, "status", e.target.value)}>
                    {PROJECT_OBJECTIVE_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
                  </select>
                </label>
              </div>
              <label>Titre<input type="text" value={o.title} onChange={(e) => updateObjective(o.id, "title", e.target.value)} /></label>
              <label>Description<textarea rows={2} value={o.description} onChange={(e) => updateObjective(o.id, "description", e.target.value)} /></label>
            </div>
            <button className="icon-btn" onClick={() => removeObjective(o.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
        {data.objectives.length === 0 && <div className="empty-state">Aucun objectif renseigné pour l'instant. Utilise le bouton ci-dessous pour en ajouter un.</div>}
      </div>
      <button className="btn btn-ghost btn-small" onClick={addObjective} style={{ marginTop: 10 }}>+ Ajouter un objectif</button>
    </div>
  );
}

function emptyClubGameIdentity() {
  return { visionGlobale: "", declinaisons: [] };
}
function emptyDeclinaison(category) {
  return { id: newId(), category: category || "", adaptation: "" };
}

function ClubGameIdentityScreen({ teams }) {
  const [data, setData] = useState(emptyClubGameIdentity());
  const [newCategory, setNewCategory] = useState("");
  const [loaded, setLoaded] = useState(false);
  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];

  useEffect(() => {
    try { setData({ ...emptyClubGameIdentity(), ...JSON.parse(window.localStorage.getItem("tf_club_identity") || "{}") }); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setData(next);
    try { window.localStorage.setItem("tf_club_identity", JSON.stringify(next)); } catch (e) {}
  }
  function addDeclinaison(category) {
    if (!category) { alert("Choisis ou saisis une catégorie."); return; }
    if (data.declinaisons.some((d) => d.category === category)) { alert("Cette catégorie a déjà une déclinaison."); return; }
    persist({ ...data, declinaisons: [...data.declinaisons, emptyDeclinaison(category)] });
    setNewCategory("");
  }
  function updateDeclinaison(id, value) {
    persist({ ...data, declinaisons: data.declinaisons.map((d) => (d.id === id ? { ...d, adaptation: value } : d)) });
  }
  function removeDeclinaison(id) {
    if (!confirm("Supprimer cette déclinaison ?")) return;
    persist({ ...data, declinaisons: data.declinaisons.filter((d) => d.id !== id) });
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Une philosophie de jeu commune au club, déclinée par catégorie d'âge — chaque équipe garde son propre Projet de jeu détaillé, celui-ci n'est qu'un fil conducteur partagé.</p>
      <div className="new-match-card">
        <label>Identité de jeu globale du club<textarea rows={3} placeholder="ex. Un club qui joue vers l'avant, privilégie la construction courte et la prise d'initiative individuelle, adaptée au niveau de chaque catégorie." value={data.visionGlobale} onChange={(e) => persist({ ...data, visionGlobale: e.target.value })} /></label>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Déclinaisons par catégorie</div>
      <div className="scouting-list">
        {data.declinaisons.map((d) => (
          <div className="scouting-card" key={d.id}>
            <div className="scouting-info">
              <div className="scouting-name">{d.category}</div>
              <textarea rows={2} placeholder="Comment cette identité s'adapte à cette catégorie…" value={d.adaptation} onChange={(e) => updateDeclinaison(d.id, e.target.value)} />
            </div>
            <button className="icon-btn" onClick={() => removeDeclinaison(d.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
        {data.declinaisons.length === 0 && <div className="empty-state">Aucune déclinaison renseignée pour l'instant.</div>}
      </div>
      <div className="home-actions-row" style={{ marginTop: 10, flexWrap: "wrap" }}>
        {knownCategories.filter((c) => !data.declinaisons.some((d) => d.category === c)).map((c) => (
          <button key={c} className="btn btn-ghost btn-small" onClick={() => addDeclinaison(c)}>+ {c}</button>
        ))}
        <input type="text" placeholder="Autre catégorie…" value={newCategory} onChange={(e) => setNewCategory(e.target.value)} style={{ width: 160 }} />
        <button className="btn btn-ghost btn-small" onClick={() => addDeclinaison(newCategory.trim())}>+ Ajouter</button>
      </div>
    </div>
  );
}

const PEDAGOGY_THEMES = [
  { key: "technique", label: "Technique" },
  { key: "tactique", label: "Tactique" },
  { key: "physique", label: "Physique" },
  { key: "mental", label: "Mental" },
];
function emptyPedagogyEntry(category) {
  return {
    id: newId(), category: category || "",
    technique: { description: "", items: [] }, tactique: { description: "", items: [] },
    physique: { description: "", items: [] }, mental: { description: "", items: [] },
  };
}
function emptyPedagogyItem() {
  return { id: newId(), text: "", covered: false, coveredAt: null };
}
// Rétrocompatibilité : les entrées créées avant l'ajout du suivi cochable stockent chaque thème
// comme une simple chaîne de texte. Ces trois fonctions lisent indifféremment l'ancien format
// (chaîne) ou le nouveau (objet {description, items}), pour que rien de déjà enregistré ne se
// retrouve cassé ou faussement vide à l'affichage.
function themeDescription(entry, key) {
  const v = entry[key];
  if (typeof v === "string") return v;
  return (v && v.description) || "";
}
function themeItems(entry, key) {
  const v = entry[key];
  if (typeof v === "string") return [];
  return (v && v.items) || [];
}
function themeHasContent(entry, key) {
  return !!themeDescription(entry, key).trim() || themeItems(entry, key).length > 0;
}

