function PedagogyReferenceScreen({ teams }) {
  const [entries, setEntries] = useState([]);
  const [newCategory, setNewCategory] = useState("");
  const [loaded, setLoaded] = useState(false);
  const [newItemText, setNewItemText] = useState({});
  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];

  useEffect(() => {
    try { setEntries(JSON.parse(window.localStorage.getItem("tf_club_pedagogy") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setEntries(next);
    try { window.localStorage.setItem("tf_club_pedagogy", JSON.stringify(next)); } catch (e) {}
  }
  function addEntry(category) {
    if (!category) { alert("Choisis ou saisis une catégorie."); return; }
    if (entries.some((e) => e.category === category)) { alert("Cette catégorie a déjà une entrée."); return; }
    persist([...entries, emptyPedagogyEntry(category)]);
    setNewCategory("");
  }
  function updateDescription(id, themeKey, value) {
    persist(entries.map((e) => (e.id === id ? { ...e, [themeKey]: { description: value, items: themeItems(e, themeKey) } } : e)));
  }
  function addPriorityItem(id, themeKey, text) {
    if (!text.trim()) return;
    persist(entries.map((e) => (e.id === id ? { ...e, [themeKey]: { description: themeDescription(e, themeKey), items: [...themeItems(e, themeKey), { ...emptyPedagogyItem(), text: text.trim() }] } } : e)));
  }
  function togglePriorityItem(id, themeKey, itemId) {
    persist(entries.map((e) => {
      if (e.id !== id) return e;
      const items = themeItems(e, themeKey).map((it) => (it.id === itemId ? { ...it, covered: !it.covered, coveredAt: !it.covered ? todayIso() : null } : it));
      return { ...e, [themeKey]: { description: themeDescription(e, themeKey), items } };
    }));
  }
  function removePriorityItem(id, themeKey, itemId) {
    persist(entries.map((e) => (e.id === id ? { ...e, [themeKey]: { description: themeDescription(e, themeKey), items: themeItems(e, themeKey).filter((it) => it.id !== itemId) } } : e)));
  }
  function removeEntry(id) {
    if (!confirm("Supprimer ce référentiel ?")) return;
    persist(entries.filter((e) => e.id !== id));
  }
  function populatePedagogyStarters() {
    const existingCategories = new Set(entries.map((e) => e.category));
    const toAdd = STARTER_PEDAGOGY_ENTRIES.filter((e) => !existingCategories.has(e.category)).map((e) => ({ id: newId(), ...e }));
    if (toAdd.length === 0) { alert("Les 17 catégories de départ sont déjà toutes présentes."); return; }
    persist([...entries, ...toAdd]);
    alert(`${toAdd.length} catégorie${toAdd.length > 1 ? "s" : ""} ajoutée${toAdd.length > 1 ? "s" : ""} — à ajuster ensuite à la réalité de ton club.`);
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Ce qui doit être travaillé en priorité à chaque catégorie d'âge, par thème — la cohérence de formation du club dans le temps.</p>
      {entries.length === 0 && <button className="btn btn-ghost btn-small" onClick={populatePedagogyStarters} style={{ marginBottom: 14 }}>Importer les 17 catégories de départ (Baby-foot à Seniors)</button>}
      {entries.map((entry) => {
        const totalItems = PEDAGOGY_THEMES.reduce((s, t) => s + themeItems(entry, t.key).length, 0);
        const coveredItems = PEDAGOGY_THEMES.reduce((s, t) => s + themeItems(entry, t.key).filter((it) => it.covered).length, 0);
        return (
        <div key={entry.id} style={{ marginBottom: 20 }}>
          <div className="range-filter-header">
            <div className="panel-heading" style={{ marginBottom: 0 }}>{entry.category}</div>
            <button className="icon-btn" onClick={() => removeEntry(entry.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
          {totalItems > 0 && <p className="hint" style={{ marginTop: 0 }}>Couverture réelle cette saison : {coveredItems}/{totalItems} priorité{totalItems !== 1 ? "s" : ""} travaillée{coveredItems !== 1 ? "s" : ""}.</p>}
          <div className="roster-physical-grid">
            {PEDAGOGY_THEMES.map((t) => {
              const items = themeItems(entry, t.key);
              const itemKey = `${entry.id}_${t.key}`;
              return (
                <div key={t.key}>
                  <label>{t.label}<textarea rows={2} value={themeDescription(entry, t.key)} onChange={(e) => updateDescription(entry.id, t.key, e.target.value)} /></label>
                  {items.length > 0 && (
                    <div style={{ marginTop: 6, marginBottom: 6 }}>
                      {items.map((it) => (
                        <label key={it.id} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, marginBottom: 4, cursor: "pointer" }}>
                          <input type="checkbox" checked={it.covered} onChange={() => togglePriorityItem(entry.id, t.key, it.id)} />
                          <span style={{ flex: 1, textDecoration: it.covered ? "line-through" : "none", opacity: it.covered ? 0.65 : 1 }}>{it.text}</span>
                          <button type="button" className="icon-btn" onClick={() => removePriorityItem(entry.id, t.key, it.id)} aria-label="Retirer cette priorité" style={{ width: 18, height: 18 }}><X size={10} /></button>
                        </label>
                      ))}
                    </div>
                  )}
                  <div style={{ display: "flex", gap: 4 }}>
                    <input type="text" placeholder="+ priorité à cocher…" value={newItemText[itemKey] || ""} onChange={(e) => setNewItemText((f) => ({ ...f, [itemKey]: e.target.value }))} onKeyDown={(e) => { if (e.key === "Enter") { addPriorityItem(entry.id, t.key, newItemText[itemKey] || ""); setNewItemText((f) => ({ ...f, [itemKey]: "" })); } }} style={{ fontSize: 12, flex: 1 }} />
                    <button type="button" className="btn btn-ghost btn-small" onClick={() => { addPriorityItem(entry.id, t.key, newItemText[itemKey] || ""); setNewItemText((f) => ({ ...f, [itemKey]: "" })); }}>+</button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
        );
      })}
      {entries.length === 0 && <div className="empty-state">Aucun référentiel renseigné pour l'instant.</div>}
      <div className="home-actions-row" style={{ marginTop: 10, flexWrap: "wrap" }}>
        {knownCategories.filter((c) => !entries.some((e) => e.category === c)).map((c) => (
          <button key={c} className="btn btn-ghost btn-small" onClick={() => addEntry(c)}>+ {c}</button>
        ))}
        <input type="text" placeholder="Autre catégorie…" value={newCategory} onChange={(e) => setNewCategory(e.target.value)} style={{ width: 160 }} />
        <button className="btn btn-ghost btn-small" onClick={() => addEntry(newCategory.trim())}>+ Ajouter</button>
      </div>
    </div>
  );
}

function emptyPasserelle() {
  return { id: newId(), fromCategory: "", toCategory: "", criteria: "", notes: "" };
}

function PasserellesScreen({ teams }) {
  const [rules, setRules] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];

  useEffect(() => {
    try { setRules(JSON.parse(window.localStorage.getItem("tf_club_passerelles") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setRules(next);
    try { window.localStorage.setItem("tf_club_passerelles", JSON.stringify(next)); } catch (e) {}
  }
  function addRule() {
    persist([...rules, emptyPasserelle()]);
  }
  function updateRule(id, field, value) {
    persist(rules.map((r) => (r.id === id ? { ...r, [field]: value } : r)));
  }
  function removeRule(id) {
    if (!confirm("Supprimer cette règle ?")) return;
    persist(rules.filter((r) => r.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Les critères qui justifient de faire monter un joueur d'une catégorie à l'autre — utile pour objectiver la décision et l'expliquer aux familles.</p>
      <div className="scouting-list">
        {rules.map((r) => (
          <div className="scouting-card" key={r.id} style={{ flexWrap: "wrap" }}>
            <div className="scouting-info">
              <div className="roster-physical-grid">
                <label>De la catégorie
                  <input type="text" list="passerelle-categories" placeholder="ex. U13" value={r.fromCategory} onChange={(e) => updateRule(r.id, "fromCategory", e.target.value)} />
                </label>
                <label>Vers la catégorie
                  <input type="text" list="passerelle-categories" placeholder="ex. U15" value={r.toCategory} onChange={(e) => updateRule(r.id, "toCategory", e.target.value)} />
                </label>
              </div>
              <datalist id="passerelle-categories">{knownCategories.map((c) => <option key={c} value={c} />)}</datalist>
              <label>Critères<textarea rows={2} placeholder="ex. Niveau technique et physique au-dessus de la moyenne de sa catégorie, maturité comportementale validée par le staff." value={r.criteria} onChange={(e) => updateRule(r.id, "criteria", e.target.value)} /></label>
              <label>Notes<input type="text" value={r.notes} onChange={(e) => updateRule(r.id, "notes", e.target.value)} /></label>
            </div>
            <button className="icon-btn" onClick={() => removeRule(r.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
        {rules.length === 0 && <div className="empty-state">Aucune règle de passerelle renseignée pour l'instant.</div>}
      </div>
      <button className="btn btn-ghost btn-small" onClick={addRule} style={{ marginTop: 10 }}>+ Ajouter une règle</button>
    </div>
  );
}

function ClubOverviewTable({ teams }) {
  const [rows, setRows] = useState(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const seasonId = getActiveSeasonId();
      const results = await Promise.all(teams.map(async (t) => {
        const roster = (() => { try { return JSON.parse(readScopedKeyFor("tf_roster", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
        const injuries = (() => { try { return JSON.parse(readScopedKeyFor("tf_medical_injuries", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
        const activeInjuries = injuries.filter((i) => i.status === "en cours").length;
        const matchSummary = await readTeamMatchesSummary(t.id, seasonId);
        return { team: t, roster: roster.length, activeInjuries, ...matchSummary };
      }));
      if (!cancelled) setRows(results);
    })();
    return () => { cancelled = true; };
  }, [teams]);

  if (!rows) return <div className="empty-state">Chargement…</div>;

  return (
    <div className="table-scroll">
      <table className="stat-table">
        <thead><tr><th>Équipe</th><th>Effectif</th><th>Matchs</th><th>V-N-D</th><th>Cartons</th><th>Blessures actives</th></tr></thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.team.id}>
              <td>{r.team.name}</td>
              <td>{r.roster}</td>
              <td>{r.played}</td>
              <td>{r.wins}-{r.draws}-{r.losses}</td>
              <td>{r.cartons}</td>
              <td>{r.activeInjuries}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function ClubMedicalOverviewScreen({ teams }) {
  const [rows, setRows] = useState(null);

  useEffect(() => {
    const seasonId = getActiveSeasonId();
    const results = teams.map((t) => {
      const injuries = (() => { try { return JSON.parse(readScopedKeyFor("tf_medical_injuries", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
      const byCategory = {};
      injuries.forEach((i) => { byCategory[i.category] = (byCategory[i.category] || 0) + 1; });
      const topCategory = Object.entries(byCategory).sort((a, b) => b[1] - a[1])[0];
      return {
        team: t,
        total: injuries.length,
        active: injuries.filter((i) => i.status === "en cours").length,
        topCategory: topCategory ? `${topCategory[0]} (${topCategory[1]})` : "—",
      };
    });
    setRows(results);
  }, [teams]);

  if (!rows) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Vue croisée des blessures par équipe — utile pour repérer si une catégorie d'âge est particulièrement touchée et ajuster les charges d'entraînement au niveau du club.</p>
      <div className="table-scroll">
        <table className="stat-table">
          <thead><tr><th>Équipe</th><th>Blessures (saison)</th><th>En cours</th><th>Catégorie la plus fréquente</th></tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.team.id}><td>{r.team.name}</td><td>{r.total}</td><td>{r.active}</td><td>{r.topCategory}</td></tr>
            ))}
          </tbody>
        </table>
      </div>
      {rows.every((r) => r.total === 0) && <div className="empty-state" style={{ marginTop: 12 }}>Aucune blessure enregistrée dans aucune équipe pour l'instant.</div>}
    </div>
  );
}

function RessourcesPartageesScreen({ teams }) {
  const [tab, setTab] = useState("exercices");
  return (
    <div className="stats-screen">
      <div className="stats-screen-header">
        <div className="eyebrow">Pôle sportif</div>
        <h1>Ressources partagées</h1>
        <p className="subtitle">Bibliothèque d'exercices, vidéothèque, scouting mutualisé et terrains — les ressources communes entre équipes.</p>
      </div>
      <div className="tabs" style={{ marginBottom: 14, flexWrap: "wrap" }}>
        <button className={`tab ${tab === "exercices" ? "active" : ""}`} onClick={() => setTab("exercices")}>Bibliothèque d'exercices</button>
        <button className={`tab ${tab === "videotheque" ? "active" : ""}`} onClick={() => setTab("videotheque")}>Vidéothèque club</button>
        <button className={`tab ${tab === "scouting" ? "active" : ""}`} onClick={() => setTab("scouting")}>Scouting mutualisé</button>
        <button className={`tab ${tab === "creneaux" ? "active" : ""}`} onClick={() => setTab("creneaux")}>Terrains et créneaux</button>
      </div>
      {tab === "exercices" && <ClubExerciseLibraryScreen teams={teams} />}
      {tab === "videotheque" && <ClubVideothequeScreen teams={teams} />}
      {tab === "scouting" && <ClubScoutingScreen teams={teams} />}
      {tab === "creneaux" && <ClubFacilitiesScreen teams={teams} />}
    </div>
  );
}

function ClubExerciseLibraryScreen({ teams }) {
  const [exercises, setExercises] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyExerciseForm());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setExercises(JSON.parse(window.localStorage.getItem("tf_club_exercise_library") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setExercises(next);
    try { window.localStorage.setItem("tf_club_exercise_library", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function openNew() { setForm(emptyExerciseForm()); setEditingId(null); setShowForm(true); }
  function openEdit(ex) { setForm(ex); setEditingId(ex.id); setShowForm(true); }
  function addExercise() {
    if (!form.name.trim()) { alert("Donne un nom à cet exercice."); return; }
    persist(editingId ? exercises.map((ex) => (ex.id === editingId ? form : ex)) : [...exercises, { ...form, id: newId() }]);
    setForm(emptyExerciseForm());
    setEditingId(null);
    setShowForm(false);
  }
  function removeExercise(id) {
    if (!confirm("Retirer cet exercice de la bibliothèque du club ?")) return;
    persist(exercises.filter((ex) => ex.id !== id));
  }
  function copyToActiveTeam(ex) {
    try {
      const current = JSON.parse(window.localStorage.getItem("tf_exercices") || "[]");
      window.localStorage.setItem("tf_exercices", JSON.stringify([...current, { ...ex, id: newId(), gameplanSection: "", gameplanChoice: "" }]));
      alert(`"${ex.name}" copié dans la banque d'exercices de l'équipe active — retrouve-le dans Séance → Banque générale.`);
    } catch (e) {
      alert("La copie a échoué.");
    }
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Exercices partagés entre toutes les équipes du club. "Copier vers mon équipe" duplique l'exercice dans la banque de l'équipe actuellement active, pour l'utiliser dans une séance.</p>
      {!showForm && <button className="btn btn-primary btn-small" onClick={openNew} style={{ marginBottom: 14 }}>+ Ajouter un exercice au club</button>}
      {showForm && (
        <div className="new-match-card">
          <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></label>
          <label>Objectif<input type="text" value={form.objectif} onChange={(e) => setForm((f) => ({ ...f, objectif: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>Durée (min)<input type="number" min="1" value={form.duree} onChange={(e) => setForm((f) => ({ ...f, duree: Number(e.target.value) }))} /></label>
            <label>Nombre de joueurs<input type="text" value={form.nbJoueurs} onChange={(e) => setForm((f) => ({ ...f, nbJoueurs: e.target.value }))} /></label>
          </div>
          <label>Matériel<input type="text" value={form.materiel} onChange={(e) => setForm((f) => ({ ...f, materiel: e.target.value }))} /></label>
          <label>Description<textarea rows={3} value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); setForm(emptyExerciseForm()); }}>Annuler</button>
            <button className="btn btn-primary" onClick={addExercise}>{editingId ? "Enregistrer" : "Ajouter"}</button>
          </div>
        </div>
      )}
      <div style={{ marginTop: 16 }}>
        {exercises.length === 0 && <div className="empty-state">Aucun exercice partagé pour l'instant — ajoutes-en ici, ou depuis Séance → Banque générale d'une équipe avec "Partager au club".</div>}
        <PaginatedGrid
          items={exercises}
          renderItem={(ex) => (
            <ExerciseCard
              key={ex.id}
              ex={ex}
              actions={<>
                <button className="btn btn-ghost btn-small" onClick={() => copyToActiveTeam(ex)}>Copier vers mon équipe</button>
                <button className="btn btn-ghost btn-small" onClick={() => openEdit(ex)}>Modifier</button>
                <button className="icon-btn" onClick={() => removeExercise(ex.id)} aria-label="Retirer"><X size={14} /></button>
              </>}
            />
          )}
        />
      </div>
    </div>
  );
}

function ClubVideothequeScreen({ teams }) {
  const [clips, setClips] = useState([]);
  const [clipUrls, setClipUrls] = useState({});
  const [loaded, setLoaded] = useState(false);
  const [staff, setStaff] = useState([]);
  const [assigneeFilter, setAssigneeFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");

  useEffect(() => {
    getAllClubClips().then((all) => {
      setClips(all.sort((a, b) => b.createdAt - a.createdAt));
      const urls = {};
      all.forEach((c) => { urls[c.id] = URL.createObjectURL(c.blob); });
      setClipUrls(urls);
      setLoaded(true);
    }).catch(() => setLoaded(true));
    try { setStaff(JSON.parse(window.localStorage.getItem("tf_club_staff") || "[]")); } catch (e) {}
  }, []);

  function remove(id) {
    if (!confirm("Retirer ce clip de la vidéothèque du club ?")) return;
    deleteClubClip(id).then(() => setClips((prev) => prev.filter((c) => c.id !== id)));
  }
  function setAssignee(id, staffId) {
    setClips((prev) => prev.map((c) => (c.id === id ? { ...c, assignedTo: staffId } : c)));
    updateClipField(openClubClipsDB, id, "assignedTo", staffId);
  }
  function setStatus(id, status) {
    setClips((prev) => prev.map((c) => (c.id === id ? { ...c, status } : c)));
    updateClipField(openClubClipsDB, id, "status", status);
  }
  function setNote(id, note) {
    setClips((prev) => prev.map((c) => (c.id === id ? { ...c, note } : c)));
    updateClipField(openClubClipsDB, id, "note", note);
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const filtered = clips.filter((c) => (!assigneeFilter || c.assignedTo === assigneeFilter) && (!statusFilter || (c.status || "a_tagger") === statusFilter));

  return (
    <div>
      <p className="radar-note">Clips partagés entre toutes les équipes du club — envoyés depuis Vidéothèque de chaque équipe, bouton "Envoyer vers la vidéothèque club". Assigne, suis le statut et laisse une note par clip si plusieurs personnes s'en partagent le travail.</p>

      <div className="roster-physical-grid" style={{ marginBottom: 14 }}>
        <label>Filtrer par assigné
          <select value={assigneeFilter} onChange={(e) => setAssigneeFilter(e.target.value)}>
            <option value="">Tout le monde</option>
            {staff.map((s) => <option key={s.id} value={s.id}>{s.firstName} {s.lastName}</option>)}
          </select>
        </label>
        <label>Filtrer par statut
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option value="">Tous les statuts</option>
            {CLIP_STATUSES.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
          </select>
        </label>
      </div>

      {filtered.length === 0 && <div className="empty-state">Aucun clip {assigneeFilter || statusFilter ? "ne correspond à ce filtre" : "partagé pour l'instant"}.</div>}
      <div className="clip-grid">
        {filtered.map((c) => {
          const assignedStaff = staff.find((s) => s.id === c.assignedTo);
          const status = c.status || "a_tagger";
          return (
            <div className="clip-card" key={c.id}>
              <video src={clipUrls[c.id]} controls />
              <div className="clip-card-info">
                <div className="clip-card-title">{c.player ? `n°${c.player}` : (c.club || (c.team === "us" ? "Équipe" : "Adversaire"))}</div>
                <div className="clip-card-meta">{c.matchName} · {teams.find((t) => t.id === c.sourceTeamId) ? teams.find((t) => t.id === c.sourceTeamId).name : "équipe inconnue"}</div>
                <div className="roster-physical-grid" style={{ marginTop: 6 }}>
                  <select value={c.assignedTo || ""} onChange={(e) => setAssignee(c.id, e.target.value)}>
                    <option value="">Non assigné</option>
                    {staff.map((s) => <option key={s.id} value={s.id}>{s.firstName} {s.lastName}</option>)}
                  </select>
                  <select value={status} onChange={(e) => setStatus(c.id, e.target.value)}>
                    {CLIP_STATUSES.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
                  </select>
                </div>
                <input type="text" placeholder="Note (optionnel)" value={c.note || ""} onChange={(e) => setNote(c.id, e.target.value)} style={{ marginTop: 6, width: "100%", boxSizing: "border-box" }} />
                {assignedStaff && <div className="clip-card-meta" style={{ marginTop: 4 }}>Assigné à {assignedStaff.firstName} {assignedStaff.lastName}</div>}
              </div>
              <button className="icon-btn" style={{ position: "absolute", top: 8, right: 8 }} onClick={() => remove(c.id)} aria-label="Retirer">✕</button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ClubScoutingScreen({ teams }) {
  const [players, setPlayers] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setPlayers(JSON.parse(window.localStorage.getItem("tf_club_scouting") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setPlayers(next);
    try { window.localStorage.setItem("tf_club_scouting", JSON.stringify(next)); } catch (e) {}
  }
  function remove(id) {
    if (!confirm("Retirer ce joueur du scouting mutualisé ?")) return;
    persist(players.filter((p) => p.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Joueurs repérés par une équipe et jugés intéressants pour le club dans son ensemble — un jeune repéré par un éducateur remonte ici pour être visible des autres catégories. Envoyé depuis Scouting de chaque équipe, bouton "Partager au club".</p>
      {players.length === 0 && <div className="empty-state">Aucun joueur partagé pour l'instant.</div>}
      <div className="scouting-list">
        {players.map((p) => {
          const sourceTeam = teams.find((t) => t.id === p.sourceTeamId);
          return (
            <div className="scouting-card" key={p.id}>
              <div className="scouting-info">
                <div className="scouting-name">{p.name || "Joueur non identifié"} <span className="scouting-club">{p.club}</span></div>
                <div className="scouting-meta">
                  {p.position}{p.birthDate ? ` · ${computeAge(p.birthDate)} ans` : ""}{p.contractStatus ? ` · ${p.contractStatus}` : ""}
                  {sourceTeam ? ` · repéré par ${sourceTeam.name}` : ""}
                </div>
                {p.notes && <div className="scouting-meta">{p.notes}</div>}
              </div>
              <button className="icon-btn" onClick={() => remove(p.id)} aria-label="Retirer"><X size={14} /></button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ClubPlayerJourneyScreen({ teams }) {
  const [sourceTeamId, setSourceTeamId] = useState("");
  const [sourceRoster, setSourceRoster] = useState([]);
  const [selectedPlayerId, setSelectedPlayerId] = useState("");
  const [targetTeamId, setTargetTeamId] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (!sourceTeamId) { setSourceRoster([]); return; }
    try { setSourceRoster(JSON.parse(readScopedKeyFor("tf_roster", sourceTeamId, getActiveSeasonId()) || "[]")); } catch (e) { setSourceRoster([]); }
    setSelectedPlayerId("");
  }, [sourceTeamId]);

  function transferPlayer(mode) {
    if (!sourceTeamId || !selectedPlayerId || !targetTeamId) { alert("Choisis une équipe source, un joueur, et une équipe cible."); return; }
    if (sourceTeamId === targetTeamId) { alert("L'équipe cible doit être différente de l'équipe source."); return; }
    setBusy(true);
    const seasonId = getActiveSeasonId();

    const sourceRosterFull = JSON.parse(readScopedKeyFor("tf_roster", sourceTeamId, seasonId) || "[]");
    const player = sourceRosterFull.find((p) => p.id === selectedPlayerId);
    if (!player) { alert("Joueur introuvable."); setBusy(false); return; }
    const targetRoster = JSON.parse(readScopedKeyFor("tf_roster", targetTeamId, seasonId) || "[]");
    if (targetRoster.some((p) => p.id === player.id)) { alert("Ce joueur est déjà présent dans l'équipe cible."); setBusy(false); return; }

    const targetTeamName = teams.find((t) => t.id === targetTeamId).name;
    const sourceTeamName = teams.find((t) => t.id === sourceTeamId).name;
    const isDual = mode === "dual";
    const copiedPlayer = isDual
      ? { ...player, linkedTeamRef: { teamId: sourceTeamId, teamName: sourceTeamName } }
      : player;
    writeScopedKeyFor("tf_roster", targetTeamId, seasonId, JSON.stringify([...targetRoster, copiedPlayer]));

    const sourceDevPlans = JSON.parse(readScopedKeyFor("tf_development_plans", sourceTeamId, seasonId) || "{}");
    if (sourceDevPlans[player.id]) {
      const targetDevPlans = JSON.parse(readScopedKeyFor("tf_development_plans", targetTeamId, seasonId) || "{}");
      targetDevPlans[player.id] = sourceDevPlans[player.id];
      writeScopedKeyFor("tf_development_plans", targetTeamId, seasonId, JSON.stringify(targetDevPlans));
    }

    const sourceHealthProfiles = JSON.parse(readScopedKeyFor("tf_medical_health_profiles", sourceTeamId, seasonId) || "{}");
    if (sourceHealthProfiles[player.id]) {
      const targetHealthProfiles = JSON.parse(readScopedKeyFor("tf_medical_health_profiles", targetTeamId, seasonId) || "{}");
      targetHealthProfiles[player.id] = sourceHealthProfiles[player.id];
      writeScopedKeyFor("tf_medical_health_profiles", targetTeamId, seasonId, JSON.stringify(targetHealthProfiles));
    }

    const sourceInjuries = JSON.parse(readScopedKeyFor("tf_medical_injuries", sourceTeamId, seasonId) || "[]");
    const playerInjuries = sourceInjuries.filter((i) => i.playerId === player.id);
    if (playerInjuries.length > 0) {
      const targetInjuries = JSON.parse(readScopedKeyFor("tf_medical_injuries", targetTeamId, seasonId) || "[]");
      writeScopedKeyFor("tf_medical_injuries", targetTeamId, seasonId, JSON.stringify([...targetInjuries, ...playerInjuries]));
    }

    if (isDual) {
      // Marque aussi la fiche d'origine comme liée à la nouvelle, dans les deux sens.
      const updatedSourceRoster = sourceRosterFull.map((p) => (p.id === player.id ? { ...p, linkedTeamRef: { teamId: targetTeamId, teamName: targetTeamName } } : p));
      writeScopedKeyFor("tf_roster", sourceTeamId, seasonId, JSON.stringify(updatedSourceRoster));
      setSourceRoster(updatedSourceRoster);
      alert(`${playerFullName(player)} est maintenant actif dans ${sourceTeamName} et ${targetTeamName}. Les deux fiches sont indépendantes une fois copiées — une modification future dans l'une ne se répercute pas automatiquement dans l'autre, mais chaque fiche indique où retrouver l'autre.`);
    } else if (mode === "move") {
      writeScopedKeyFor("tf_roster", sourceTeamId, seasonId, JSON.stringify(sourceRosterFull.filter((p) => p.id !== player.id)));
      setSourceRoster(sourceRosterFull.filter((p) => p.id !== player.id));
      alert("Transfert effectué.");
    } else {
      alert(`${playerFullName(player)} copié vers ${targetTeamName}, resté également présent dans ${sourceTeamName}.`);
    }
    setSelectedPlayerId("");
    setTargetTeamId("");
    setBusy(false);
  }

  return (
    <div>
      <p className="radar-note">Transfère un joueur d'une équipe à l'autre en conservant son historique : tests physiques (rattachés à sa fiche), objectifs de développement, fiche santé et blessures. Le suivi Hooper/RPE au jour le jour reste avec l'équipe d'origine, plus spécifique au contexte d'entraînement.</p>
      <div className="roster-physical-grid">
        <label>Équipe source
          <select value={sourceTeamId} onChange={(e) => setSourceTeamId(e.target.value)}>
            <option value="">Choisir…</option>
            {teams.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
        </label>
        <label>Joueur
          <select value={selectedPlayerId} onChange={(e) => setSelectedPlayerId(e.target.value)} disabled={!sourceTeamId}>
            <option value="">Choisir…</option>
            {sourceRoster.map((p) => <option key={p.id} value={p.id}>{playerFullName(p)}{p.linkedTeamRef ? ` (lié à ${p.linkedTeamRef.teamName})` : ""}</option>)}
          </select>
        </label>
        <label>Équipe cible
          <select value={targetTeamId} onChange={(e) => setTargetTeamId(e.target.value)}>
            <option value="">Choisir…</option>
            {teams.filter((t) => t.id !== sourceTeamId).map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
        </label>
      </div>
      <div className="home-actions-row" style={{ marginTop: 12 }}>
        <button className="btn btn-primary" onClick={() => transferPlayer("move")} disabled={busy}>Déplacer (retirer de la source)</button>
        <button className="btn btn-ghost" onClick={() => transferPlayer("dual")} disabled={busy}>Garder actif dans les deux équipes</button>
      </div>
      <p className="hint">"Garder actif dans les deux" copie la fiche et ses données associées, sans synchronisation ultérieure — chaque équipe voit ensuite sa propre copie, avec un renvoi vers l'autre pour rappel.</p>
    </div>
  );
}

function ClubLoanPoolScreen({ teams }) {
  const [pool, setPool] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setPool(JSON.parse(window.localStorage.getItem("tf_club_loan_pool") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function remove(id) {
    if (!confirm("Supprimer ce joueur du pool de renfort ?")) return;
    const next = pool.filter((e) => e.id !== id);
    setPool(next);
    try { window.localStorage.setItem("tf_club_loan_pool", JSON.stringify(next)); } catch (e) {}
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Joueurs proposés en renfort par leur équipe d'origine — disponibles pour dépanner une autre équipe en cas d'effectif court. Ajoutés depuis Effectifs → Nous, bouton "Proposer en renfort".</p>
      {pool.length === 0 && <div className="empty-state">Aucun joueur proposé en renfort pour l'instant.</div>}
      <div className="scouting-list">
        {pool.map((e) => (
          <div className="scouting-card" key={e.id}>
            <div className="scouting-info">
              <div className="scouting-name">{e.playerName}</div>
              <div className="scouting-meta">{e.position} · équipe d'origine : {e.teamName}</div>
            </div>
            <button className="icon-btn" onClick={() => remove(e.id)} aria-label="Retirer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function extractCategoryLevel(category) {
  const m = (category || "").match(/U\s*(\d+)/i);
  if (m) return Number(m[1]);
  if (/senior/i.test(category || "")) return 99;
  return null;
}

const OVERCLASS_REVIEW_STATUSES = ["À examiner", "Confirmé", "Pas encore prêt"];

function ClubOverclassificationScreen({ teams }) {
  const [rows, setRows] = useState(null);
  const [reviews, setReviews] = useState({});

  useEffect(() => {
    try { setReviews(JSON.parse(localStorage.getItem("tf_overclass_reviews") || "{}")); } catch (e) {}
    const seasonId = getActiveSeasonId();
    const teamsWithLevel = teams.map((t) => ({ ...t, level: extractCategoryLevel(t.category) })).filter((t) => t.level != null);
    const results = [];
    const TESTS = [{ key: "vma", label: "VMA", higherIsBetter: true }, { key: "sprint10m", label: "Sprint 10m", higherIsBetter: false }, { key: "detente", label: "Détente", higherIsBetter: true }];

    teamsWithLevel.forEach((team) => {
      const nextLevelTeam = teamsWithLevel.filter((t) => t.level > team.level).sort((a, b) => a.level - b.level)[0];
      if (!nextLevelTeam) return;
      const roster = (() => { try { return JSON.parse(readScopedKeyFor("tf_roster", team.id, seasonId) || "[]"); } catch (e) { return []; } })();
      const nextRoster = (() => { try { return JSON.parse(readScopedKeyFor("tf_roster", nextLevelTeam.id, seasonId) || "[]"); } catch (e) { return []; } })();
      if (nextRoster.length === 0) return;

      TESTS.forEach((test) => {
        const nextValues = nextRoster.map((p) => parseFloat(getLatestTestValue(p, test.key))).filter((v) => !isNaN(v));
        if (nextValues.length === 0) return;
        const nextAvg = nextValues.reduce((s, v) => s + v, 0) / nextValues.length;
        roster.forEach((p) => {
          const v = parseFloat(getLatestTestValue(p, test.key));
          if (isNaN(v)) return;
          const better = test.higherIsBetter ? v >= nextAvg : v <= nextAvg;
          if (better) {
            results.push({ player: p, fromTeam: team, toTeam: nextLevelTeam, test: test.label, value: v, benchmark: Math.round(nextAvg * 10) / 10 });
          }
        });
      });
    });
    setRows(results);
  }, [teams]);

  if (!rows) return <div className="empty-state">Chargement…</div>;

  function setReview(playerId, field, value) {
    const next = { ...reviews, [playerId]: { ...(reviews[playerId] || { status: "À examiner", note: "" }), [field]: value } };
    setReviews(next);
    try { localStorage.setItem("tf_overclass_reviews", JSON.stringify(next)); } catch (e) {}
  }

  return (
    <div>
      <p className="radar-note">Compare les derniers tests physiques de chaque joueur à la moyenne de la catégorie immédiatement supérieure (détecté via le nom de catégorie, ex. "U15" → "U17"). Un indice à confirmer par ton œil d'entraîneur, pas un verdict — d'où le statut ci-dessous, pour noter ton propre avis technique et tactique par-dessus le chiffre.</p>
      {rows.length === 0 && <div className="empty-state">Aucun surclassement potentiel détecté pour l'instant (ou pas assez de catégories nommées "U…" pour comparer).</div>}
      <div className="scouting-list">
        {rows.map((r, i) => {
          const review = reviews[r.player.id] || { status: "À examiner", note: "" };
          return (
            <div className="scouting-card" key={i} style={{ flexDirection: "column", alignItems: "stretch" }}>
              <div style={{ display: "flex" }}>
                <div className="scouting-grade grade-a" style={{ fontSize: 10 }}>{r.test}</div>
                <div className="scouting-info">
                  <div className="scouting-name">{playerFullName(r.player)} <span className="scouting-club">{r.fromTeam.name}</span></div>
                  <div className="scouting-meta">{r.value} vs moyenne {r.benchmark} en {r.toTeam.name}</div>
                </div>
              </div>
              <div className="roster-physical-grid" style={{ marginTop: 8 }}>
                <select value={review.status} onChange={(e) => setReview(r.player.id, "status", e.target.value)}>
                  {OVERCLASS_REVIEW_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
                </select>
                <input type="text" placeholder="Ton avis technique/tactique (optionnel)" value={review.note} onChange={(e) => setReview(r.player.id, "note", e.target.value)} />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ClubAgePyramidScreen({ teams }) {
  const [chartData, setChartData] = useState(null);

  useEffect(() => {
    const seasonId = getActiveSeasonId();
    const byAge = {};
    teams.forEach((t) => {
      const roster = (() => { try { return JSON.parse(readScopedKeyFor("tf_roster", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
      roster.forEach((p) => {
        if (!p.birthDate) return;
        const age = computeAge(p.birthDate);
        if (age == null) return;
        byAge[age] = (byAge[age] || 0) + 1;
      });
    });
    const ages = Object.keys(byAge).map(Number).sort((a, b) => a - b);
    setChartData(ages.map((age) => ({ age: `${age} ans`, joueurs: byAge[age] })));
  }, [teams]);

  if (!chartData) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Répartition des joueurs par âge, toutes équipes confondues — basé sur la date de naissance renseignée dans chaque fiche joueur.</p>
      {chartData.length === 0 && <div className="empty-state">Aucune date de naissance renseignée dans aucune équipe pour l'instant.</div>}
      {chartData.length > 0 && (
        <div className="chart-wrap" style={{ height: 300 }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData} margin={{ top: 10, right: 20, left: -10, bottom: 0 }}>
              <CartesianGrid stroke="#26362C" strokeDasharray="3 3" />
              <XAxis dataKey="age" tick={{ fill: "#8FA599", fontSize: 11 }} />
              <YAxis allowDecimals={false} tick={{ fill: "#8FA599", fontSize: 11 }} />
              <Tooltip contentStyle={{ background: "#182A21", border: "1px solid #26362C", borderRadius: 6, color: "#EEF3EC" }} />
              <Line type="monotone" dataKey="joueurs" stroke="#E3B23C" strokeWidth={2} dot={{ r: 4 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}

const CLUB_TEAM_COLORS = ["#E3B23C", "#D6483F", "#4CAF7D", "#5B8FD6", "#B98FE0", "#FF8C42"];

function AcademyScreen() {
  const [data, setData] = useState(null);
  const [tab, setTab] = useState("overview");
  const [teams, setTeams] = useState([]);

  useEffect(() => {
    let loadedTeams = [];
    try { loadedTeams = JSON.parse(localStorage.getItem("tf_teams") || "[]"); } catch (e) {}
    setTeams(loadedTeams);
    const seasonId = getActiveSeasonId();
    const result = loadedTeams.map((t) => {
      const roster = (() => { try { return JSON.parse(readScopedKeyFor("tf_roster", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
      const injuries = (() => { try { return JSON.parse(readScopedKeyFor("tf_medical_injuries", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
      const devPlans = (() => { try { return JSON.parse(readScopedKeyFor("tf_development_plans", t.id, seasonId) || "{}"); } catch (e) { return {}; } })();
      return { team: t, roster, injuries, devPlans };
    });
    setData(result);
  }, []);

  if (!data) return <div className="stats-screen"><div className="empty-state">Chargement…</div></div>;

  const totalPlayers = data.reduce((s, d) => s + d.roster.length, 0);
  const allActiveInjuries = data.flatMap((d) =>
    d.injuries.filter((i) => i.status === "en cours").map((i) => ({ ...i, teamName: d.team.name, player: d.roster.find((p) => p.id === i.playerId) }))
  );
  const allPlayers = data.flatMap((d) => d.roster.map((p) => ({ ...p, teamName: d.team.name, teamCategory: d.team.category })));

  return (
    <div className="stats-screen" style={{ maxWidth: 900, margin: "0 auto" }}>
      <div className="stats-screen-header">
        <div className="eyebrow">Administratif</div>
        <h1>Vue académie</h1>
      </div>
      <p className="radar-note">Vue transversale sur toutes tes équipes — {teams.length} équipe{teams.length !== 1 ? "s" : ""}, {totalPlayers} joueur{totalPlayers !== 1 ? "s" : ""} au total. Utile pour un centre de formation avec plusieurs catégories d'âge, plutôt que de naviguer équipe par équipe.</p>

      <div className="tabs" style={{ marginBottom: 14 }}>
        <button className={`tab ${tab === "overview" ? "active" : ""}`} onClick={() => setTab("overview")}>Vue d'ensemble</button>
        <button className={`tab ${tab === "blessures" ? "active" : ""}`} onClick={() => setTab("blessures")}>Blessures ({allActiveInjuries.length})</button>
        <button className={`tab ${tab === "effectif" ? "active" : ""}`} onClick={() => setTab("effectif")}>Effectif complet ({totalPlayers})</button>
      </div>

      {tab === "overview" && (
        <div className="roster-grid">
          {data.length === 0 && <div className="empty-state">Aucune équipe créée pour l'instant.</div>}
          {data.map(({ team, roster, injuries, devPlans }) => {
            const activeInj = injuries.filter((i) => i.status === "en cours").length;
            const devCount = Object.keys(devPlans).filter((pid) => (devPlans[pid] || []).length > 0).length;
            return (
              <div className="roster-card" key={team.id}>
                <div className="roster-card-info">
                  <div className="roster-card-name">{team.name}</div>
                  <div className="roster-card-position">{team.category || "Catégorie non précisée"}</div>
                  <div className="roster-card-usage">{roster.length} joueur{roster.length !== 1 ? "s" : ""}{devCount > 0 ? ` · ${devCount} en développement individuel` : ""}</div>
                  {activeInj > 0 && <div className="roster-card-meta" style={{ color: "var(--crimson)" }}>{activeInj} blessure{activeInj > 1 ? "s" : ""} en cours</div>}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {tab === "blessures" && (
        <div className="scouting-list">
          {allActiveInjuries.length === 0 && <div className="empty-state">Aucune blessure en cours dans l'académie.</div>}
          {allActiveInjuries.map((inj) => {
            const stage = RTP_STAGES.find((s) => s.key === (inj.rtpStage || "arret_complet"));
            return (
              <div className="scouting-card" key={inj.id}>
                <div className="scouting-info">
                  <div className="scouting-name">{inj.player ? playerFullName(inj.player) : "Joueur non identifié"} <span className="scouting-club">{inj.teamName}</span></div>
                  <div className="scouting-meta">{inj.type} · {inj.category} · depuis le {formatDateFr(inj.dateDebut)}</div>
                  <div className="scouting-meta">{stage ? stage.label : "Arrêt complet"}</div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {tab === "effectif" && (
        <div className="scouting-list">
          {allPlayers.length === 0 && <div className="empty-state">Aucun joueur dans l'académie.</div>}
          {allPlayers.map((p) => (
            <div className="scouting-card" key={`${p.teamName}-${p.id}`}>
              <div className="scouting-info">
                <div className="scouting-name">{playerFullName(p)} <span className="scouting-club">{p.teamName}</span></div>
                <div className="scouting-meta">{p.position}{p.birthDate ? ` · ${computeAge(p.birthDate)} ans` : ""}{p.teamCategory ? ` · ${p.teamCategory}` : ""}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function RapportSaisonScreen({ setSection }) {
  const [loaded, setLoaded] = useState(false);
  const [teamName, setTeamName] = useState("");
  const [roster, setRoster] = useState([]);
  const [seasonRecord, setSeasonRecord] = useState({ played: 0, wins: 0, draws: 0, losses: 0, goalsFor: 0, goalsAgainst: 0, cartonsJaunes: 0, cartonsRouges: 0 });
  const [injuries, setInjuries] = useState([]);
  const [devPlans, setDevPlans] = useState({});
  const [staff, setStaff] = useState([]);

  useEffect(() => {
    try { setTeamName(JSON.parse(localStorage.getItem("tf_club_info") || "{}").name || ""); } catch (e) {}
    try { setRoster(JSON.parse(localStorage.getItem("tf_roster") || "[]")); } catch (e) {}
    try { setInjuries(JSON.parse(localStorage.getItem("tf_medical_injuries") || "[]")); } catch (e) {}
    try { setDevPlans(JSON.parse(localStorage.getItem("tf_development_plans") || "{}")); } catch (e) {}
    try { setStaff(JSON.parse(localStorage.getItem("tf_club_staff") || "[]")); } catch (e) {}
    try {
      const index = JSON.parse(localStorage.getItem(MATCHES_INDEX_KEY) || "[]");
      const full = index.map((m) => readMatchFromCache(m.id)).filter((m) => m && m.closed);
      let wins = 0, draws = 0, losses = 0, goalsFor = 0, goalsAgainst = 0, cartonsJaunes = 0, cartonsRouges = 0;
      full.forEach((m) => {
        const gf = m.tags.filter((t) => t.eventKey === "but" && t.team === "us").length;
        const ga = m.tags.filter((t) => t.eventKey === "but" && t.team === "opp").length;
        goalsFor += gf; goalsAgainst += ga;
        if (gf > ga) wins++; else if (gf < ga) losses++; else draws++;
        cartonsJaunes += m.tags.filter((t) => t.eventKey === "carton_jaune" && t.team === "us").length;
        cartonsRouges += m.tags.filter((t) => t.eventKey === "carton_rouge" && t.team === "us").length;
      });
      setSeasonRecord({ played: full.length, wins, draws, losses, goalsFor, goalsAgainst, cartonsJaunes, cartonsRouges });
    } catch (e) {}
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const activeInjuries = injuries.filter((i) => i.status === "en cours").length;
  const healedInjuries = injuries.filter((i) => i.status === "guéri" && i.dateDebut && i.dateFinReelle);
  const avgInjuryDays = healedInjuries.length > 0
    ? Math.round(healedInjuries.reduce((s, i) => s + Math.max(0, (new Date(i.dateFinReelle) - new Date(i.dateDebut)) / 86400000), 0) / healedInjuries.length)
    : null;
  const injuryTypeCounts = {};
  injuries.forEach((i) => { if (i.category) injuryTypeCounts[i.category] = (injuryTypeCounts[i.category] || 0) + 1; });
  const topInjuryCategory = Object.entries(injuryTypeCounts).sort((a, b) => b[1] - a[1])[0];

  const playersWithObjectives = Object.keys(devPlans).filter((pid) => (devPlans[pid] || []).length > 0).length;
  const allObjectives = Object.values(devPlans).flat();
  const objectivesAtteints = allObjectives.filter((o) => o.status === "Atteint").length;

  return (
    <div className="match-report" style={{ maxWidth: 800, margin: "0 auto" }}>
      <div className="stats-screen-header no-print">
        <div className="eyebrow">Administratif</div>
        <h1>Rapport de saison</h1>
      </div>
      <button className="btn btn-ghost btn-small no-print" onClick={() => window.print()} style={{ marginBottom: 12 }}><Download size={13} /> Exporter en PDF</button>
      <div className="home-actions-row no-print" style={{ marginBottom: 12 }}>
        <button className="btn btn-ghost btn-small" onClick={() => setSection("tableau-dirigeant")}>Voir le tableau de bord dirigeant</button>
        <button className="btn btn-ghost btn-small" onClick={() => setSection("pilotage-coaching")}>Voir le carnet de transmission</button>
      </div>

      <div className="match-report-header">
        <div className="match-report-title">Rapport de fin de saison{teamName ? ` — ${teamName}` : ""}</div>
        <div className="match-report-meta">Généré le {formatDateFr(todayIso())}</div>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Bilan sportif</div>
      <div className="new-match-card">
        <p style={{ margin: 0 }}>{seasonRecord.played} match{seasonRecord.played !== 1 ? "s" : ""} joué{seasonRecord.played !== 1 ? "s" : ""} — {seasonRecord.wins}V {seasonRecord.draws}N {seasonRecord.losses}D</p>
        <p style={{ margin: "6px 0 0" }}>{seasonRecord.goalsFor} but{seasonRecord.goalsFor !== 1 ? "s" : ""} marqué{seasonRecord.goalsFor !== 1 ? "s" : ""}, {seasonRecord.goalsAgainst} encaissé{seasonRecord.goalsAgainst !== 1 ? "s" : ""} (différence {seasonRecord.goalsFor - seasonRecord.goalsAgainst >= 0 ? "+" : ""}{seasonRecord.goalsFor - seasonRecord.goalsAgainst})</p>
        <p style={{ margin: "6px 0 0" }}>Discipline : {seasonRecord.cartonsJaunes} carton{seasonRecord.cartonsJaunes !== 1 ? "s" : ""} jaune{seasonRecord.cartonsJaunes !== 1 ? "s" : ""}, {seasonRecord.cartonsRouges} carton{seasonRecord.cartonsRouges !== 1 ? "s" : ""} rouge{seasonRecord.cartonsRouges !== 1 ? "s" : ""}</p>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Effectif et staff</div>
      <div className="new-match-card">
        <p style={{ margin: 0 }}>{roster.length} joueur{roster.length !== 1 ? "s" : ""} dans l'effectif</p>
        <p style={{ margin: "6px 0 0" }}>{staff.length} membre{staff.length !== 1 ? "s" : ""} du staff</p>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Bilan médical</div>
      <div className="new-match-card">
        {injuries.length === 0 && <p style={{ margin: 0 }}>Aucune blessure enregistrée cette saison.</p>}
        {injuries.length > 0 && (
          <>
            <p style={{ margin: 0 }}>{injuries.length} blessure{injuries.length !== 1 ? "s" : ""} enregistrée{injuries.length !== 1 ? "s" : ""} sur la saison, dont {activeInjuries} encore en cours</p>
            {avgInjuryDays != null && <p style={{ margin: "6px 0 0" }}>Durée moyenne d'indisponibilité (blessures closes) : {avgInjuryDays} jour{avgInjuryDays !== 1 ? "s" : ""}</p>}
            {topInjuryCategory && <p style={{ margin: "6px 0 0" }}>Catégorie la plus fréquente : {topInjuryCategory[0]} ({topInjuryCategory[1]})</p>}
          </>
        )}
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Développement individuel</div>
      <div className="new-match-card">
        {playersWithObjectives === 0 && <p style={{ margin: 0 }}>Aucun objectif de développement enregistré cette saison.</p>}
        {playersWithObjectives > 0 && (
          <p style={{ margin: 0 }}>{playersWithObjectives} joueur{playersWithObjectives !== 1 ? "s" : ""} avec au moins un objectif suivi, {objectivesAtteints}/{allObjectives.length} objectif{allObjectives.length !== 1 ? "s" : ""} marqué{allObjectives.length !== 1 ? "s" : ""} atteint{objectivesAtteints !== 1 ? "s" : ""}</p>
        )}
      </div>

      <p className="hint no-print" style={{ marginTop: 20 }}>Ce rapport se construit à partir des données déjà enregistrées dans l'app (matchs tagués et clôturés, blessures, objectifs de développement) — rien à ressaisir.</p>
    </div>
  );
}

function ClubCrossCalendarScreen({ teams }) {
  const [viewDate, setViewDate] = useState(new Date());
  const [eventsByTeam, setEventsByTeam] = useState(null);

  useEffect(() => {
    const seasonId = getActiveSeasonId();
    const clubEvents = (() => { try { return JSON.parse(window.localStorage.getItem("tf_club_events") || "[]"); } catch (e) { return []; } })();
    const result = teams.map((t) => {
      const comp = (() => { try { return { ...emptyCompetitionsData(), ...JSON.parse(readScopedKeyFor("tf_competitions", t.id, seasonId) || "{}") }; } catch (e) { return emptyCompetitionsData(); } })();
      const sessions = (() => { try { return JSON.parse(readScopedKeyFor("tf_sessions", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
      return { team: t, events: buildAccueilEvents(comp, sessions, clubEvents) };
    });
    setEventsByTeam(result);
  }, [teams]);

  if (!eventsByTeam) return <div className="empty-state">Chargement…</div>;

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const firstOfMonth = new Date(year, month, 1);
  const startWeekday = (firstOfMonth.getDay() + 6) % 7;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < startWeekday; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);
  const dateStr = (d) => `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  const monthLabel = viewDate.toLocaleDateString("fr-FR", { month: "long", year: "numeric" });

  return (
    <div className="stats-screen">
      <div className="stats-screen-header">
        <div className="eyebrow">Planning</div>
        <h1>Calendrier croisé</h1>
      </div>
      <p className="radar-note">Les événements (matchs et séances) de toutes tes équipes, superposés — utile pour repérer un conflit de créneau ou de terrain.</p>
      <div className="calendar-legend" style={{ marginBottom: 10 }}>
        {teams.map((t, i) => (
          <span key={t.id} className="calendar-legend-item"><i className="dot" style={{ background: CLUB_TEAM_COLORS[i % CLUB_TEAM_COLORS.length] }} />{t.name}</span>
        ))}
      </div>
      <div className="calendar-nav">
        <button className="icon-btn" onClick={() => setViewDate(new Date(year, month - 1, 1))} aria-label="Mois précédent">‹</button>
        <span className="calendar-month-label">{monthLabel}</span>
        <button className="icon-btn" onClick={() => setViewDate(new Date(year, month + 1, 1))} aria-label="Mois suivant">›</button>
      </div>
      <div className="calendar-grid">
        {["Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim"].map((d) => <div key={d} className="calendar-dow">{d}</div>)}
        {cells.map((d, i) => {
          if (d == null) return <div key={i} className="calendar-day empty" />;
          const ds = dateStr(d);
          const isToday = ds === todayIso();
          const dayEntries = [];
          eventsByTeam.forEach((et, teamIdx) => {
            et.events.filter((ev) => ev.date === ds).forEach((ev) => dayEntries.push({ ...ev, teamIdx, teamName: et.team.name }));
          });
          return (
            <div key={i} className={`calendar-day ${isToday ? "today" : ""}`} title={dayEntries.map((e) => `${e.teamName} — ${e.title}`).join("\n")}>
              <div className="calendar-day-num">{d}</div>
              <div className="calendar-day-dots">
                {dayEntries.map((e, j) => <span key={j} className="calendar-dot" style={{ background: CLUB_TEAM_COLORS[e.teamIdx % CLUB_TEAM_COLORS.length] }} />)}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function emptyFacility(name) { return { id: newId(), name: name || "" }; }
function emptySlotBooking() { return { id: newId(), facilityId: "", teamId: "", dayOfWeek: "Lundi", startTime: "18:00", endTime: "19:30", label: "" }; }
const WEEK_DAYS_FR = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"];

function ClubFacilitiesScreen({ teams }) {
  const [locations, setLocations] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [showBookingForm, setShowBookingForm] = useState(false);
  const [bookingForm, setBookingForm] = useState(emptySlotBooking());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    let locs = [];
    try { locs = JSON.parse(window.localStorage.getItem("tf_club_locations") || "[]"); } catch (e) {}
    // Migration douce : si d'anciens terrains existent dans tf_club_facilities mais qu'aucun lieu général n'est encore défini, on les reprend.
    try {
      const old = JSON.parse(window.localStorage.getItem("tf_club_facilities") || "{}");
      if (locs.length === 0 && old.facilities && old.facilities.length > 0) {
        locs = old.facilities.map((f) => ({ id: f.id, name: f.name }));
        window.localStorage.setItem("tf_club_locations", JSON.stringify(locs));
      }
      setBookings(old.bookings || []);
    } catch (e) {}
    setLocations(locs);
    setLoaded(true);
  }, []);

  function persistBookings(next) {
    setBookings(next);
    try {
      const old = (() => { try { return JSON.parse(window.localStorage.getItem("tf_club_facilities") || "{}"); } catch (e) { return {}; } })();
      window.localStorage.setItem("tf_club_facilities", JSON.stringify({ ...old, bookings: next }));
    } catch (e) {}
  }
  function addBooking() {
    if (!bookingForm.facilityId || !bookingForm.teamId) { alert("Choisis un lieu et une équipe."); return; }
    persistBookings([...bookings, { ...bookingForm, id: newId() }]);
    setBookingForm(emptySlotBooking());
    setShowBookingForm(false);
  }
  function removeBooking(id) {
    if (!confirm("Supprimer ce créneau ?")) return;
    persistBookings(bookings.filter((b) => b.id !== id));
  }
  function timeOverlap(a, b) {
    return a.dayOfWeek === b.dayOfWeek && a.facilityId === b.facilityId && a.startTime < b.endTime && b.startTime < a.endTime;
  }
  const conflicts = bookings.filter((b) => bookings.some((other) => other.id !== b.id && timeOverlap(b, other)));

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Créneaux récurrents réservés par chaque équipe sur les lieux du club, semaine type — les chevauchements sont signalés automatiquement. Pour ajouter ou retirer un terrain/une salle, direction Administratif → Club, onglet Club → Informations.</p>

      {locations.length === 0 && <div className="empty-state">Aucun lieu défini pour l'instant — ajoutes-en depuis Administratif → Club, onglet Club → Informations.</div>}

      {conflicts.length > 0 && (
        <div className="empty-state" style={{ borderColor: "var(--crimson)", marginBottom: 14 }}>
          {conflicts.length} créneau{conflicts.length > 1 ? "x" : ""} en conflit détecté{conflicts.length > 1 ? "s" : ""} — deux équipes réservent le même lieu au même moment.
        </div>
      )}

      <div className="panel-heading" style={{ marginTop: 16 }}>Créneaux réservés</div>
      {!showBookingForm && locations.length > 0 && <button className="btn btn-primary btn-small" onClick={() => setShowBookingForm(true)} style={{ marginBottom: 14 }}>+ Réserver un créneau</button>}
      {showBookingForm && (
        <div className="new-match-card">
          <div className="roster-physical-grid">
            <label>Lieu
              <select value={bookingForm.facilityId} onChange={(e) => setBookingForm((f) => ({ ...f, facilityId: e.target.value }))}>
                <option value="">Choisir…</option>
                {locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
              </select>
            </label>
            <label>Équipe
              <select value={bookingForm.teamId} onChange={(e) => setBookingForm((f) => ({ ...f, teamId: e.target.value }))}>
                <option value="">Choisir…</option>
                {teams.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
            </label>
          </div>
          <div className="roster-physical-grid">
            <label>Jour
              <select value={bookingForm.dayOfWeek} onChange={(e) => setBookingForm((f) => ({ ...f, dayOfWeek: e.target.value }))}>
                {WEEK_DAYS_FR.map((d) => <option key={d} value={d}>{d}</option>)}
              </select>
            </label>
            <label>Début<input type="time" value={bookingForm.startTime} onChange={(e) => setBookingForm((f) => ({ ...f, startTime: e.target.value }))} /></label>
            <label>Fin<input type="time" value={bookingForm.endTime} onChange={(e) => setBookingForm((f) => ({ ...f, endTime: e.target.value }))} /></label>
          </div>
          <label>Libellé (optionnel)<input type="text" placeholder="ex. Entraînement" value={bookingForm.label} onChange={(e) => setBookingForm((f) => ({ ...f, label: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowBookingForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={addBooking}>Réserver</button>
          </div>
        </div>
      )}

      <div className="scouting-list" style={{ marginTop: 10 }}>
        {WEEK_DAYS_FR.map((day) => {
          const dayBookings = bookings.filter((b) => b.dayOfWeek === day).sort((a, b) => a.startTime.localeCompare(b.startTime));
          if (dayBookings.length === 0) return null;
          return (
            <div key={day} style={{ marginBottom: 14 }}>
              <div className="hint" style={{ marginTop: 0 }}>{day}</div>
              {dayBookings.map((b) => {
                const facility = locations.find((l) => l.id === b.facilityId);
                const team = teams.find((t) => t.id === b.teamId);
                const isConflict = conflicts.some((c) => c.id === b.id);
                return (
                  <div className="scouting-card" key={b.id} style={isConflict ? { borderColor: "var(--crimson)" } : undefined}>
                    <div className="scouting-info">
                      <div className="scouting-name">{b.startTime}–{b.endTime} · {facility ? facility.name : "?"}</div>
                      <div className="scouting-meta">{team ? team.name : "?"}{b.label ? ` · ${b.label}` : ""}</div>
                    </div>
                    <button className="icon-btn" onClick={() => removeBooking(b.id)} aria-label="Supprimer"><X size={14} /></button>
                  </div>
                );
              })}
            </div>
          );
        })}
        {bookings.length === 0 && <div className="empty-state">Aucun créneau réservé pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
      </div>
    </div>
  );
}

function emptyEquipmentItem() { return { id: newId(), name: "", quantity: 1, location: "", notes: "" }; }

function InventaireMaterielTab() {
  const [items, setItems] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyEquipmentItem());
  const [loaded, setLoaded] = useState(false);
  const [locationFilter, setLocationFilter] = useState("");

  useEffect(() => {
    try { setItems(JSON.parse(window.localStorage.getItem("tf_club_equipment") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setItems(next);
    try { window.localStorage.setItem("tf_club_equipment", JSON.stringify(next)); } catch (e) {}
  }
  function addItem() {
    if (!form.name.trim()) { alert("Donne un nom à cet article."); return; }
    persist([...items, form]);
    setForm(emptyEquipmentItem());
    setShowForm(false);
  }
  function updateItem(id, field, value) {
    persist(items.map((it) => (it.id === id ? { ...it, [field]: value } : it)));
  }
  function removeItem(id) {
    if (!confirm("Supprimer cet article de l'inventaire ?")) return;
    persist(items.filter((it) => it.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const distinctLocations = [...new Set(items.map((it) => it.location).filter(Boolean))].sort((a, b) => a.localeCompare(b));
  const filtered = locationFilter ? items.filter((it) => it.location === locationFilter) : items;

  return (
    <div>
      <p className="radar-note">Matériel partagé entre les équipes du club (ballons, plots, chasubles...).</p>
      {distinctLocations.length > 1 && (
        <label style={{ display: "inline-block", marginBottom: 14 }}>
          Lieu
          <select value={locationFilter} onChange={(e) => setLocationFilter(e.target.value)} style={{ display: "block", marginTop: 4 }}>
            <option value="">Tous les lieux</option>
            {distinctLocations.map((l) => <option key={l} value={l}>{l}</option>)}
          </select>
        </label>
      )}
      {!showForm && <button className="btn btn-primary btn-small" onClick={() => setShowForm(true)} style={{ marginBottom: 14, display: "block" }}>+ Ajouter un article</button>}
      {showForm && (
        <div className="new-match-card">
          <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>Quantité<input type="number" min="0" value={form.quantity} onChange={(e) => setForm((f) => ({ ...f, quantity: Number(e.target.value) }))} /></label>
            <label>Emplacement<input type="text" value={form.location} onChange={(e) => setForm((f) => ({ ...f, location: e.target.value }))} /></label>
          </div>
          <label>Notes<input type="text" value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={addItem}>Ajouter</button>
          </div>
        </div>
      )}
      <div className="table-scroll" style={{ marginTop: 14 }}>
        <table className="stat-table">
          <thead><tr><th>Article</th><th>Quantité</th><th>Emplacement</th><th>Notes</th><th></th></tr></thead>
          <tbody>
            {filtered.map((it) => (
              <tr key={it.id}>
                <td>{it.name}</td>
                <td><input type="number" min="0" value={it.quantity} onChange={(e) => updateItem(it.id, "quantity", Number(e.target.value))} style={{ width: 60 }} /></td>
                <td><input type="text" value={it.location} onChange={(e) => updateItem(it.id, "location", e.target.value)} /></td>
                <td><input type="text" value={it.notes} onChange={(e) => updateItem(it.id, "notes", e.target.value)} /></td>
                <td><button className="icon-btn" onClick={() => removeItem(it.id)} aria-label="Supprimer"><X size={12} /></button></td>
              </tr>
            ))}
            {filtered.length === 0 && <tr><td colSpan={5} className="empty-state">{locationFilter ? "Aucun article à ce lieu." : "Aucun article enregistré."}</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function emptyTrainingRecord() { return { id: newId(), staffId: "", name: "", date: todayIso(), status: "Planifiée", notes: "" }; }
const TRAINING_STATUSES = ["Planifiée", "En cours", "Validée", "Annulée"];

function ClubTrainingScreen({ staff }) {
  const [records, setRecords] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyTrainingRecord());
  const [loaded, setLoaded] = useState(false);
  const [view, setView] = useState("suivi");

  useEffect(() => {
    try { setRecords(JSON.parse(window.localStorage.getItem("tf_club_trainings") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setRecords(next);
    try { window.localStorage.setItem("tf_club_trainings", JSON.stringify(next)); } catch (e) {}
  }
  function addRecord() {
    if (!form.staffId || !form.name.trim()) { alert("Choisis un membre du staff et donne un nom à la formation."); return; }
    persist([...records, form]);
    setForm(emptyTrainingRecord());
    setShowForm(false);
  }
  function updateStatus(id, status) {
    persist(records.map((r) => (r.id === id ? { ...r, status } : r)));
  }
  function removeRecord(id) {
    if (!confirm("Supprimer cette formation ?")) return;
    persist(records.filter((r) => r.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <div className="tabs">
        <button className={`tab ${view === "suivi" ? "active" : ""}`} onClick={() => setView("suivi")}>Suivi des formations</button>
        <button className={`tab ${view === "projet" ? "active" : ""}`} onClick={() => setView("projet")}>Projet pluriannuel</button>
      </div>
      {view === "projet" ? (
        <ClubTrainingProjectScreen staff={staff} />
      ) : (
        <>
      <p className="radar-note">Formations et stages suivis par le staff, en plus des diplômes déjà renseignés sur chaque fiche.</p>
      {!showForm && <button className="btn btn-primary btn-small" onClick={() => setShowForm(true)} style={{ marginBottom: 14 }}>+ Ajouter une formation</button>}
      {showForm && (
        <div className="new-match-card">
          <label>Membre du staff
            <select value={form.staffId} onChange={(e) => setForm((f) => ({ ...f, staffId: e.target.value }))}>
              <option value="">Choisir…</option>
              {staff.map((s) => <option key={s.id} value={s.id}>{s.firstName} {s.lastName}</option>)}
            </select>
          </label>
          <label>Nom de la formation<input type="text" placeholder="ex. Recyclage BMF" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>Date<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
            <label>Statut
              <select value={form.status} onChange={(e) => setForm((f) => ({ ...f, status: e.target.value }))}>
                {TRAINING_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </label>
          </div>
          <label>Notes<input type="text" value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={addRecord}>Ajouter</button>
          </div>
        </div>
      )}
      <div className="scouting-list" style={{ marginTop: 10 }}>
        {records.map((r) => {
          const s = staff.find((x) => x.id === r.staffId);
          return (
            <div className="scouting-card" key={r.id}>
              <div className="scouting-info">
                <div className="scouting-name">{r.name} <span className="scouting-club">{s ? `${s.firstName} ${s.lastName}` : "?"}</span></div>
                <div className="scouting-meta">{formatDateFr(r.date)}{r.notes ? ` · ${r.notes}` : ""}</div>
              </div>
              <select value={r.status} onChange={(e) => updateStatus(r.id, e.target.value)}>
                {TRAINING_STATUSES.map((s2) => <option key={s2} value={s2}>{s2}</option>)}
              </select>
              <button className="icon-btn" onClick={() => removeRecord(r.id)} aria-label="Supprimer"><X size={14} /></button>
            </div>
          );
        })}
        {records.length === 0 && <div className="empty-state">Aucune formation enregistrée pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      </div>
      </>
      )}
    </div>
  );
}

function emptyTrainingProject() { return { vision: "", horizonYears: 4, milestones: [] }; }
function emptyTrainingMilestone(year) { return { id: newId(), year: year || new Date().getFullYear(), staffId: "", trainingName: "", notes: "" }; }

function ClubTrainingProjectScreen({ staff }) {
  const [data, setData] = useState(emptyTrainingProject());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setData({ ...emptyTrainingProject(), ...JSON.parse(window.localStorage.getItem("tf_club_training_project") || "{}") }); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setData(next);
    try { window.localStorage.setItem("tf_club_training_project", JSON.stringify(next)); } catch (e) {}
  }
  function addMilestone() {
    persist({ ...data, milestones: [...data.milestones, emptyTrainingMilestone(new Date().getFullYear())] });
  }
  function updateMilestone(id, field, value) {
    persist({ ...data, milestones: data.milestones.map((m) => (m.id === id ? { ...m, [field]: value } : m)) });
  }
  function removeMilestone(id) {
    if (!confirm("Supprimer cette projection ?")) return;
    persist({ ...data, milestones: data.milestones.filter((m) => m.id !== id) });
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Projections de formations à passer par le staff sur plusieurs saisons — distinct du suivi ci-dessus qui enregistre les formations déjà réalisées ou en cours.</p>
      <div className="new-match-card">
        <label>Vision de la politique de formation du club<textarea rows={3} placeholder="ex. Amener chaque éducateur au diplôme correspondant au niveau de sa catégorie d'ici 4 ans." value={data.vision} onChange={(e) => persist({ ...data, vision: e.target.value })} /></label>
        <label>Horizon (années)<input type="number" min="1" max="10" value={data.horizonYears} onChange={(e) => persist({ ...data, horizonYears: Number(e.target.value) })} /></label>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Projections par échéance</div>
      <div className="scouting-list">
        {data.milestones.sort((a, b) => a.year - b.year).map((m) => (
          <div className="scouting-card" key={m.id} style={{ flexWrap: "wrap" }}>
            <div className="scouting-info">
              <div className="roster-physical-grid">
                <label>Année<input type="number" value={m.year} onChange={(e) => updateMilestone(m.id, "year", Number(e.target.value))} /></label>
                <label>Membre du staff
                  <select value={m.staffId} onChange={(e) => updateMilestone(m.id, "staffId", e.target.value)}>
                    <option value="">Choisir…</option>
                    {staff.map((s) => <option key={s.id} value={s.id}>{s.firstName} {s.lastName}</option>)}
                  </select>
                </label>
              </div>
              <label>Formation visée<input type="text" placeholder="ex. BEF" value={m.trainingName} onChange={(e) => updateMilestone(m.id, "trainingName", e.target.value)} /></label>
              <label>Notes<input type="text" value={m.notes} onChange={(e) => updateMilestone(m.id, "notes", e.target.value)} /></label>
            </div>
            <button className="icon-btn" onClick={() => removeMilestone(m.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
        {data.milestones.length === 0 && <div className="empty-state">Aucune projection renseignée pour l'instant.</div>}
      </div>
      <button className="btn btn-ghost btn-small" onClick={addMilestone} style={{ marginTop: 10 }}>+ Ajouter une projection</button>
    </div>
  );
}

function ClubEducatorWorkloadScreen({ staff, teams }) {
  const [facilitiesData, setFacilitiesData] = useState({ facilities: [], bookings: [] });
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setFacilitiesData({ facilities: [], bookings: [], ...JSON.parse(window.localStorage.getItem("tf_club_facilities") || "{}") }); } catch (e) {}
    setLoaded(true);
  }, []);

  function durationHours(b) {
    const [sh, sm] = b.startTime.split(":").map(Number);
    const [eh, em] = b.endTime.split(":").map(Number);
    return Math.max(0, (eh * 60 + em - (sh * 60 + sm)) / 60);
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const rows = staff.map((s) => {
    const teamBookings = facilitiesData.bookings.filter((b) => s.teamIds.includes(b.teamId));
    const totalHours = teamBookings.reduce((sum, b) => sum + durationHours(b), 0);
    return { staff: s, slots: teamBookings.length, hours: Math.round(totalHours * 10) / 10 };
  });

  return (
    <div>
      <p className="radar-note">Charge hebdomadaire de chaque éducateur, calculée à partir des créneaux réservés par les équipes qu'il encadre (onglet "Terrains et créneaux"). Un éducateur sur plusieurs équipes cumule leurs créneaux.</p>
      <div className="table-scroll">
        <table className="stat-table">
          <thead><tr><th>Éducateur</th><th>Équipe(s)</th><th>Créneaux/semaine</th><th>Heures/semaine</th></tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.staff.id}>
                <td>{r.staff.firstName} {r.staff.lastName}</td>
                <td>{r.staff.teamIds.map((tid) => teams.find((t) => t.id === tid)).filter(Boolean).map((t) => t.name).join(", ") || "—"}</td>
                <td>{r.slots}</td>
                <td>{r.hours}h</td>
              </tr>
            ))}
            {rows.length === 0 && <tr><td colSpan={4} className="empty-state">Aucun membre du staff enregistré.</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function VolumeLicenciesTab({ teams }) {
  const [rows, setRows] = useState(null);

  useEffect(() => {
    const seasonId = getActiveSeasonId();
    const results = teams.map((t) => {
      const roster = (() => { try { return JSON.parse(readScopedKeyFor("tf_roster", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
      const healthProfiles = (() => { try { return JSON.parse(readScopedKeyFor("tf_medical_health_profiles", t.id, seasonId) || "{}"); } catch (e) { return {}; } })();
      let withImageAuth = 0, withTerritoryAuth = 0, withAdhesionDate = 0;
      roster.forEach((p) => {
        const hp = healthProfiles[p.id];
        if (hp) {
          if (hp.autorisationImage === "Oui") withImageAuth++;
          if (hp.autorisationSortieTerritoire === "Oui") withTerritoryAuth++;
          if (hp.dateAdhesion) withAdhesionDate++;
        }
      });
      return { team: t, total: roster.length, withImageAuth, withTerritoryAuth, withAdhesionDate };
    });
    setRows(results);
  }, [teams]);

  if (!rows) return <div className="empty-state">Chargement…</div>;
  const grandTotal = rows.reduce((s, r) => s + r.total, 0);

  return (
    <div>
      <p className="radar-note">Volume de licenciés par équipe et suivi des autorisations administratives individuelles (renseignées dans la fiche santé de chaque joueur) — les dates de licence elles-mêmes arrivant toutes au 30 juin, ce suivi se concentre sur ce qui varie réellement d'un joueur à l'autre.</p>
      <div className="dashboard-card" style={{ marginBottom: 16, maxWidth: 260 }}>
        <div className="dashboard-card-title">Total licenciés (club)</div>
        <div className="dashboard-card-main">{grandTotal}</div>
      </div>
      <div className="table-scroll">
        <table className="stat-table">
          <thead><tr><th>Équipe</th><th>Effectif</th><th>Autorisation image renseignée</th><th>Autorisation sortie territoire</th><th>Date d'adhésion renseignée</th></tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.team.id}>
                <td>{r.team.name}</td>
                <td>{r.total}</td>
                <td>{r.withImageAuth}/{r.total}</td>
                <td>{r.withTerritoryAuth}/{r.total}</td>
                <td>{r.withAdhesionDate}/{r.total}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

