function emptyClubEvent() {
  return {
    id: newId(), name: "", date: todayIso(), endDate: "", startTime: "", endTime: "", description: "",
    targetCategories: [], targetTeamIds: [], includePlayers: true, includeStaff: true, locationId: "",
    type: "", recurrence: { enabled: false, frequency: "weekly", until: "" },
  };
}
// Construit la liste des dates d'occurrence pour un événement (une seule si pas de récurrence).
// Garde-fou à 104 occurrences (~2 ans en hebdo) pour éviter une boucle infinie sur une date mal saisie.
function buildEventOccurrenceDates(form) {
  if (!form.recurrence || !form.recurrence.enabled || !form.recurrence.until) return [form.date];
  const dates = [];
  let current = new Date(form.date);
  const until = new Date(form.recurrence.until);
  if (isNaN(current.getTime()) || isNaN(until.getTime()) || until < current) return [form.date];
  let guard = 0;
  while (current <= until && guard < 104) {
    dates.push(current.toISOString().slice(0, 10));
    if (form.recurrence.frequency === "monthly") current.setMonth(current.getMonth() + 1);
    else current.setDate(current.getDate() + 7);
    guard++;
  }
  return dates.length > 0 ? dates : [form.date];
}

function ClubEventsScreen({ teams, categories }) {
  const [events, setEvents] = useState([]);
  const [locations, setLocations] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyClubEvent());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setEvents(JSON.parse(window.localStorage.getItem("tf_club_events") || "[]")); } catch (e) {}
    try { setLocations(JSON.parse(window.localStorage.getItem("tf_club_locations") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setEvents(next);
    try { window.localStorage.setItem("tf_club_events", JSON.stringify(next)); } catch (e) {}
  }
  function openNew() { setForm(emptyClubEvent()); setEditingId(null); setShowForm(true); }
  function openEdit(ev) { setForm(ev); setEditingId(ev.id); setShowForm(true); }
  function addEvent() {
    if (!form.name.trim()) { alert("Donne un nom à cet événement."); return; }
    if (form.type !== "seance" && form.targetCategories.length === 0 && form.targetTeamIds.length === 0) { alert("Choisis au moins une catégorie ou une équipe à convoquer."); return; }
    if (editingId) {
      persist(events.map((e) => (e.id === editingId ? { ...form, id: editingId } : e)).sort((a, b) => new Date(a.date) - new Date(b.date)));
      setForm(emptyClubEvent());
      setEditingId(null);
      setShowForm(false);
      return;
    }
    const dates = buildEventOccurrenceDates(form);
    if (form.type === "seance") {
      try {
        const existingSessions = JSON.parse(window.localStorage.getItem("tf_sessions") || "[]");
        const newSessions = dates.map((date) => ({ id: newId(), name: form.name, date, startTime: form.startTime, endTime: form.endTime, blocks: [], presence: {}, rating: { coachScore: "", comment: "" } }));
        window.localStorage.setItem("tf_sessions", JSON.stringify([...existingSessions, ...newSessions]));
        alert(newSessions.length > 1 ? `${newSessions.length} séances créées — retrouve-les dans l'onglet Séances pour y ajouter des exercices.` : "Séance créée — retrouve-la dans l'onglet Séances pour y ajouter des exercices.");
      } catch (e) { alert("La création de la séance a échoué."); return; }
      setForm(emptyClubEvent());
      setShowForm(false);
      return;
    }
    const seriesId = dates.length > 1 ? newId() : null;
    const newEvents = dates.map((date) => ({ ...form, id: newId(), date, seriesId }));
    persist([...events, ...newEvents].sort((a, b) => new Date(a.date) - new Date(b.date)));
    setForm(emptyClubEvent());
    setShowForm(false);
  }
  function removeEvent(id) {
    if (!confirm("Supprimer cet événement ?")) return;
    persist(events.filter((e) => e.id !== id));
  }
  function removeSeries(seriesId) {
    const count = events.filter((e) => e.seriesId === seriesId).length;
    if (!confirm(`Supprimer les ${count} occurrences de cette série ?`)) return;
    persist(events.filter((e) => e.seriesId !== seriesId));
  }
  function toggleCategory(c) {
    setForm((f) => ({ ...f, targetCategories: f.targetCategories.includes(c) ? f.targetCategories.filter((x) => x !== c) : [...f.targetCategories, c] }));
  }
  function toggleTeam(id) {
    setForm((f) => ({ ...f, targetTeamIds: f.targetTeamIds.includes(id) ? f.targetTeamIds.filter((x) => x !== id) : [...f.targetTeamIds, id] }));
  }
  function describeTargets(e) {
    const parts = [];
    if (e.targetCategories.length > 0) parts.push(`catégorie${e.targetCategories.length > 1 ? "s" : ""} ${e.targetCategories.join(", ")}`);
    if (e.targetTeamIds.length > 0) parts.push(e.targetTeamIds.map((id) => { const t = teams.find((x) => x.id === id); return t ? t.name : "?"; }).join(", "));
    const who = [];
    if (e.includePlayers) who.push("joueurs");
    if (e.includeStaff) who.push("staff");
    return `${parts.join(" · ")} — ${who.join(" et ")}`;
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div className="stats-screen">
      <div className="stats-screen-header">
        <div className="eyebrow">Planning</div>
        <h1>Événements</h1>
      </div>
      <p className="radar-note">Événements du club au-delà des matchs — stages, tournois internes, journées portes ouvertes. Convoque par catégorie et/ou équipe, joueurs et/ou staff, dans un lieu précis.</p>
      {!showForm && <button className="btn btn-primary btn-small" onClick={openNew} style={{ marginBottom: 14 }}>+ Nouvel événement</button>}
      {showForm && (
        <div className="new-match-card">
          <label>Nom<input type="text" placeholder="ex. Stage de printemps" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></label>
          <div className="radar-range-label">Type d'événement</div>
          <div className="qcm-options">
            {CLUB_EVENT_TYPES.map((t) => (
              <button key={t.key} className={`qcm-option ${form.type === t.key ? "selected" : ""}`} onClick={() => setForm((f) => ({ ...f, type: f.type === t.key ? "" : t.key }))}>{t.label}</button>
            ))}
          </div>
          <div className="roster-physical-grid">
            <label>{editingId ? "Date" : "Date de début"}<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
            {!editingId && <label>Date de fin (optionnel)<input type="date" value={form.endDate} onChange={(e) => setForm((f) => ({ ...f, endDate: e.target.value }))} /></label>}
          </div>
          <div className="roster-physical-grid">
            <label>Heure de début (optionnel)<input type="time" value={form.startTime} onChange={(e) => setForm((f) => ({ ...f, startTime: e.target.value }))} /></label>
            <label>Heure de fin (optionnel)<input type="time" value={form.endTime} onChange={(e) => setForm((f) => ({ ...f, endTime: e.target.value }))} /></label>
          </div>
          {!editingId && (
            <>
              <label style={{ display: "block" }}>
                <input type="checkbox" checked={form.recurrence.enabled} onChange={(e) => setForm((f) => ({ ...f, recurrence: { ...f.recurrence, enabled: e.target.checked } }))} style={{ marginRight: 6 }} />
                Se répète
              </label>
              {form.recurrence.enabled && (
                <div className="roster-physical-grid">
                  <label>Fréquence
                    <select value={form.recurrence.frequency} onChange={(e) => setForm((f) => ({ ...f, recurrence: { ...f.recurrence, frequency: e.target.value } }))}>
                      <option value="weekly">Toutes les semaines</option>
                      <option value="monthly">Tous les mois</option>
                    </select>
                  </label>
                  <label>Jusqu'au<input type="date" value={form.recurrence.until} onChange={(e) => setForm((f) => ({ ...f, recurrence: { ...f.recurrence, until: e.target.value } }))} /></label>
                </div>
              )}
            </>
          )}
          {editingId && form.seriesId && (
            <p className="radar-note" style={{ marginTop: 8 }}>Cet événement fait partie d'une série — la modification ne s'applique qu'à cette occurrence.</p>
          )}
          <label>Lieu
            <select value={form.locationId} onChange={(e) => setForm((f) => ({ ...f, locationId: e.target.value }))}>
              <option value="">Non renseigné</option>
              {locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
            </select>
          </label>

          {form.type === "seance" && !editingId && (
            <p className="radar-note" style={{ marginTop: 8 }}>Ce type crée une vraie séance dans l'onglet Séances (à compléter avec des exercices), pas un événement club — la convocation ci-dessous ne s'applique pas à elle.</p>
          )}
          <div className="radar-range-label">Convoquer les catégories</div>
          <div className="qcm-options">
            {categories.map((c) => (
              <button key={c} className={`qcm-option ${form.targetCategories.includes(c) ? "selected" : ""}`} onClick={() => toggleCategory(c)}>{c}</button>
            ))}
          </div>
          <div className="radar-range-label">Convoquer des équipes précises (en plus ou à la place d'une catégorie)</div>
          <div className="qcm-options">
            {teams.map((t) => (
              <button key={t.id} className={`qcm-option ${form.targetTeamIds.includes(t.id) ? "selected" : ""}`} onClick={() => toggleTeam(t.id)}>{t.name}</button>
            ))}
          </div>
          <label style={{ display: "block", marginTop: 8 }}>
            <input type="checkbox" checked={form.includePlayers} onChange={(e) => setForm((f) => ({ ...f, includePlayers: e.target.checked }))} style={{ marginRight: 6 }} />
            Joueurs concernés
          </label>
          <label style={{ display: "block" }}>
            <input type="checkbox" checked={form.includeStaff} onChange={(e) => setForm((f) => ({ ...f, includeStaff: e.target.checked }))} style={{ marginRight: 6 }} />
            Staff concerné
          </label>

          <label>Description<textarea rows={2} value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={addEvent}>{editingId ? "Enregistrer" : "Ajouter"}</button>
          </div>
        </div>
      )}
      <div className="scouting-list" style={{ marginTop: 10 }}>
        {events.map((e) => {
          const location = locations.find((l) => l.id === e.locationId);
          const typeInfo = e.type ? CLUB_EVENT_TYPES.find((t) => t.key === e.type) : null;
          return (
            <div className="scouting-card" key={e.id}>
              <div className="scouting-info">
                <div className="scouting-name">
                  {typeInfo && <span className="dot" style={{ background: EVENT_TYPE_INFO[e.type]?.color, width: 8, height: 8, borderRadius: "50%", display: "inline-block", marginRight: 6 }} />}
                  {e.name}{typeInfo ? ` · ${typeInfo.label}` : ""}
                </div>
                <div className="scouting-meta">{formatDateFr(e.date)}{e.endDate ? ` → ${formatDateFr(e.endDate)}` : ""}{e.startTime ? ` · ${e.startTime}${e.endTime ? `–${e.endTime}` : ""}` : ""}{location ? ` · ${location.name}` : ""}{e.seriesId ? " · se répète" : ""}</div>
                <div className="scouting-meta">{describeTargets(e)}</div>
                {e.description && <div className="scouting-meta">{e.description}</div>}
              </div>
              <div style={{ display: "flex", gap: 4 }}>
                <button className="btn btn-ghost btn-small" onClick={() => openEdit(e)}>Modifier</button>
                {e.seriesId && <button className="icon-btn" onClick={() => removeSeries(e.seriesId)} aria-label="Supprimer toute la série" title="Supprimer toute la série">🗑️×</button>}
                <button className="icon-btn" onClick={() => removeEvent(e.id)} aria-label="Supprimer"><X size={14} /></button>
              </div>
            </div>
          );
        })}
        {events.length === 0 && <div className="empty-state">Aucun événement enregistré pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
      </div>
    </div>
  );
}

