function BibliothequeGardienScreen({ exercises, persistExercises }) {
  function populateGoalkeeperStarters() {
    const existingNames = new Set(exercises.map((e) => e.name));
    const toAdd = STARTER_GOALKEEPER_EXERCISES.filter((ex) => !existingNames.has(ex.name)).map((ex) => ({ id: newId(), ...emptyExerciseForm(), ...ex, createdAt: Date.now() }));
    if (toAdd.length === 0) { alert("Les exercices gardien de départ sont déjà tous présents dans ta banque."); return; }
    persistExercises((prev) => [...prev, ...toAdd]);
    alert(`${toAdd.length} exercice${toAdd.length > 1 ? "s" : ""} gardien ajouté${toAdd.length > 1 ? "s" : ""} à ta banque.`);
  }
  const [domainFilter, setDomainFilter] = useState("technique");
  const [skillFilter, setSkillFilter] = useState("Tous");
  const [viewingExercise, setViewingExercise] = useState(null);

  const gkExercises = exercises.filter((e) => e.forGoalkeepers);
  const gkTechnique = gkExercises.filter((e) => { const c = e.category || "tactique"; return c !== "athletique" && c !== "mental"; });
  const gkPhysique = gkExercises.filter((e) => e.category === "athletique");
  const gkMental = gkExercises.filter((e) => e.category === "mental");
  const domainExercises = domainFilter === "technique" ? gkTechnique : domainFilter === "athletique" ? gkPhysique : gkMental;
  const filtered = skillFilter === "Tous" ? domainExercises : domainExercises.filter((e) => e.goalkeeperSkill === skillFilter);
  const bySkill = {};
  gkTechnique.forEach((e) => { const s = e.goalkeeperSkill || "Non classé"; (bySkill[s] || (bySkill[s] = [])).push(e); });

  if (viewingExercise) {
    return (
      <div>
        <button className="btn btn-ghost btn-small" onClick={() => setViewingExercise(null)} style={{ marginBottom: 14 }}>‹ Retour</button>
        <div className="panel-heading" style={{ marginTop: 0 }}>{viewingExercise.name}</div>
        <p className="hint" style={{ marginTop: 0 }}>{viewingExercise.goalkeeperSkill}</p>
        {viewingExercise.objectif && <p>{viewingExercise.objectif}</p>}
        {viewingExercise.description && <p>{viewingExercise.description}</p>}
        <ExerciseThumbnail diagram={viewingExercise.diagram} large />
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Les exercices marqués "spécifique gardien" dans la banque — {gkExercises.length} au total, tous domaines confondus.</p>
      {gkExercises.length === 0 && <button className="btn btn-ghost btn-small" onClick={populateGoalkeeperStarters} style={{ marginBottom: 14 }}>Importer la banque gardien de départ (30 exercices)</button>}
      <div className="tabs" style={{ marginBottom: 10 }}>
        <button className={`tab ${domainFilter === "technique" ? "active" : ""}`} onClick={() => { setDomainFilter("technique"); setSkillFilter("Tous"); }}>Technique ({gkTechnique.length})</button>
        <button className={`tab ${domainFilter === "athletique" ? "active" : ""}`} onClick={() => setDomainFilter("athletique")}>Préparation physique ({gkPhysique.length})</button>
        <button className={`tab ${domainFilter === "mental" ? "active" : ""}`} onClick={() => setDomainFilter("mental")}>Mental ({gkMental.length})</button>
      </div>
      {domainFilter === "technique" && (
        <div className="tabs" style={{ marginBottom: 14, flexWrap: "wrap" }}>
          <button className={`tab ${skillFilter === "Tous" ? "active" : ""}`} onClick={() => setSkillFilter("Tous")}>Tous ({gkTechnique.length})</button>
          {GOALKEEPER_SKILLS.map((s) => (
            <button key={s} className={`tab ${skillFilter === s ? "active" : ""}`} onClick={() => setSkillFilter(s)}>{s} ({(bySkill[s] || []).length})</button>
          ))}
        </div>
      )}
      {filtered.length === 0 && <div className="empty-state">Aucun exercice {domainFilter === "athletique" ? "de préparation physique gardien" : domainFilter === "mental" ? "mental gardien" : "gardien"} {skillFilter !== "Tous" ? "pour ce geste" : ""} pour l'instant — ajoutes-en depuis Création d'exercices en cochant "Exercice spécifique gardien"{domainFilter === "athletique" ? ' et en choisissant la catégorie "Athlétique"' : domainFilter === "mental" ? ' et en choisissant la catégorie "Mental"' : ""}.</div>}
      <div className="scouting-list">
        {filtered.map((ex) => (
          <div className="scouting-card" key={ex.id} onClick={() => setViewingExercise(ex)} style={{ cursor: "pointer" }}>
            <div className="scouting-info">
              <div className="scouting-name">{ex.name} <span className="scouting-club">{ex.goalkeeperSkill || (domainFilter === "athletique" ? "Physique" : domainFilter === "mental" ? "Mental" : "Non classé")}</span></div>
              {ex.objectif && <div className="scouting-meta">{ex.objectif}</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// Suivi statistique gardien, match par match — complète le radar déjà présent dans Statistiques
// (qui donne une photo agrégée) par une vraie tendance dans le temps, à partir des mêmes tags
// "gardien_*" déjà posés. Retrouve le numéro exact porté par CE gardien dans CHAQUE match via
// playerAssignments (le numéro peut varier d'un match à l'autre), pas un numéro fixe supposé.
function computeGoalkeeperMatchStats(playerId, allFullMatches) {
  return allFullMatches
    .map((m) => {
      const entry = Object.entries(m.playerAssignments || {}).find(([num, rid]) => rid === playerId);
      if (!entry) return null;
      const number = entry[0];
      const tags = (m.tags || []).filter((t) => t.team === "us" && String(t.player) === String(number) && t.eventKey.startsWith("gardien_"));
      const count = (key) => tags.filter((t) => t.eventKey === key).length;
      return {
        matchId: m.id, matchName: m.name, date: m.date,
        arretsOk: count("gardien_arret_ok"), arretsKo: count("gardien_arret_ko"),
        sortiesOk: count("gardien_sortie_ok"), sortiesKo: count("gardien_sortie_ko"),
        relancesOk: count("gardien_relance_ok"), relancesKo: count("gardien_relance_ko"),
        duelsOk: count("gardien_duel_ok"), duelsKo: count("gardien_duel_ko"),
      };
    })
    .filter(Boolean)
    .sort((a, b) => new Date(b.date) - new Date(a.date));
}
function pct(ok, ko) { const total = ok + ko; return total > 0 ? Math.round((ok / total) * 100) : null; }

function StatsGardienScreen({ roster }) {
  const [selectedId, setSelectedId] = useState("");
  const [allFullMatches, setAllFullMatches] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try {
      const index = JSON.parse(localStorage.getItem(MATCHES_INDEX_KEY) || "[]");
      setAllFullMatches(index.map((m) => readMatchFromCache(m.id)).filter((m) => m && m.closed));
    } catch (e) { setAllFullMatches([]); }
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const goalkeepers = roster.filter((p) => p.position === "Gardien");
  const stats = selectedId ? computeGoalkeeperMatchStats(selectedId, allFullMatches) : [];
  const totals = stats.reduce((acc, s) => ({
    arretsOk: acc.arretsOk + s.arretsOk, arretsKo: acc.arretsKo + s.arretsKo,
    relancesOk: acc.relancesOk + s.relancesOk, relancesKo: acc.relancesKo + s.relancesKo,
  }), { arretsOk: 0, arretsKo: 0, relancesOk: 0, relancesKo: 0 });

  return (
    <div>
      <p className="radar-note">Les statistiques gardien match par match, à partir des tags déjà posés en Studio/Observation — complète le radar de l'onglet Statistiques par une vraie tendance dans le temps.</p>
      <label style={{ display: "inline-block", marginBottom: 16 }}>
        Gardien
        <select value={selectedId} onChange={(e) => setSelectedId(e.target.value)} style={{ display: "block", marginTop: 4 }}>
          <option value="">Choisir…</option>
          {goalkeepers.map((p) => <option key={p.id} value={p.id}>{playerFullName(p)}</option>)}
        </select>
      </label>

      {!selectedId && <div className="empty-state">Choisis un gardien pour voir ses statistiques.</div>}
      {selectedId && stats.length === 0 && <div className="empty-state">Aucun match tagué retrouvé pour ce gardien.</div>}
      {selectedId && stats.length > 0 && (
        <>
          <div className="new-match-card" style={{ marginBottom: 16 }}>
            <p style={{ margin: 0 }}>Sur {stats.length} match{stats.length !== 1 ? "s" : ""} : {totals.arretsOk}/{totals.arretsOk + totals.arretsKo} arrêts ({pct(totals.arretsOk, totals.arretsKo)}%), {totals.relancesOk}/{totals.relancesOk + totals.relancesKo} relances ({pct(totals.relancesOk, totals.relancesKo)}%).</p>
          </div>
          <div className="scouting-list">
            {stats.map((s) => (
              <div className="scouting-card" key={s.matchId}>
                <div className="scouting-info">
                  <div className="scouting-name">{s.matchName} <span className="scouting-club">{formatDateFr(s.date)}</span></div>
                  <div className="scouting-meta">Arrêts : {s.arretsOk}/{s.arretsOk + s.arretsKo}{pct(s.arretsOk, s.arretsKo) != null ? ` (${pct(s.arretsOk, s.arretsKo)}%)` : ""} · Sorties : {s.sortiesOk}/{s.sortiesOk + s.sortiesKo} · Relances : {s.relancesOk}/{s.relancesOk + s.relancesKo} · Duels : {s.duelsOk}/{s.duelsOk + s.duelsKo}</div>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

const YOUTH_MOTOR_SKILLS = ["Conduite de balle", "Passe courte", "Contrôle orienté", "Frappe du pied faible", "Jonglerie", "1 contre 1", "Tir cadré", "Réception de balle aérienne"];
