// Vérification de l'application réelle du projet de formation — met en regard ce que le
// référentiel pédagogique du club dit qu'il faut prioriser à cette catégorie, et ce qui a
// vraiment été travaillé dans les séances récentes (via leurs blocs d'exercices). Pas un score
// automatique — les priorités du référentiel sont du texte libre, pas des poids chiffrés — mais
// une mise en regard pour juger soi-même de la cohérence.
const CATEGORY_KEY_TO_THEME_LABEL = { technique: "Technique", tactique: "Tactique", athletique: "Physique", mental: "Mental" };

function VerificationApplicationScreen() {
  const [selectedCategory, setSelectedCategory] = useState("");
  const [sessions, setSessions] = useState([]);
  const [exercises, setExercises] = useState([]);
  const [pedagogyEntries, setPedagogyEntries] = useState([]);
  const [teams, setTeams] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setSessions(JSON.parse(localStorage.getItem("tf_sessions") || "[]")); } catch (e) {}
    try { setExercises(JSON.parse(localStorage.getItem("tf_exercices") || "[]")); } catch (e) {}
    try { setPedagogyEntries(JSON.parse(localStorage.getItem("tf_club_pedagogy") || "[]")); } catch (e) {}
    try { setTeams(JSON.parse(localStorage.getItem("tf_teams") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];
  const pedagogyEntry = pedagogyEntries.find((e) => e.category === selectedCategory);

  const recentSessions = [...sessions].sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 10);
  const counts = { technique: 0, tactique: 0, athletique: 0, mental: 0 };
  let totalBlocks = 0;
  recentSessions.forEach((s) => {
    (s.blocks || []).forEach((b) => {
      const ex = exercises.find((e) => e.id === b.exerciseId);
      const cat = ex ? (ex.category || "tactique") : null;
      if (cat && counts[cat] != null) { counts[cat]++; totalBlocks++; }
    });
  });

  return (
    <div>
      <p className="radar-note">Ce que le référentiel dit prioritaire pour cette catégorie, comparé à ce qui a vraiment été travaillé dans tes 10 dernières séances (d'après les exercices utilisés) — à toi de juger si ça correspond.</p>
      <label style={{ display: "inline-block", marginBottom: 16 }}>
        Catégorie
        <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} style={{ display: "block", marginTop: 4 }}>
          <option value="">Choisir…</option>
          {knownCategories.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
      </label>

      {selectedCategory && (
        <>
          <div className="panel-heading" style={{ marginTop: 0 }}>Priorités déclarées</div>
          {!pedagogyEntry && <div className="empty-state">Rien renseigné pour {selectedCategory} dans le référentiel pédagogique.</div>}
          {pedagogyEntry && (
            <div className="new-match-card" style={{ marginBottom: 20 }}>
              {PEDAGOGY_THEMES.map((t) => themeDescription(pedagogyEntry, t.key) ? <p key={t.key} style={{ margin: "4px 0" }}><strong>{t.label} :</strong> {themeDescription(pedagogyEntry, t.key)}</p> : null)}
            </div>
          )}

          <div className="panel-heading">Ce qui a vraiment été travaillé (10 dernières séances)</div>
          {totalBlocks === 0 && <div className="empty-state">Aucun exercice retrouvé dans les séances récentes.</div>}
          {totalBlocks > 0 && (
            <div className="new-match-card">
              {Object.entries(CATEGORY_KEY_TO_THEME_LABEL).map(([key, label]) => (
                <p key={key} style={{ margin: "4px 0" }}>{label} : {counts[key]}/{totalBlocks} ({Math.round((counts[key] / totalBlocks) * 100)}%)</p>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

