function computeCollectiveAcwr(roster, rpeLog) {
  const withACWR = roster.map((p) => computeACWR(p.id, rpeLog, todayIso())).filter((v) => v != null);
  if (withACWR.length === 0) return { average: null, riskyCount: 0, total: roster.length };
  const average = Math.round((withACWR.reduce((s, v) => s + v, 0) / withACWR.length) * 100) / 100;
  const riskyCount = withACWR.filter((v) => acwrRiskZone(v).key === "risque_eleve" || acwrRiskZone(v).key === "risque_accru").length;
  return { average, riskyCount, total: roster.length };
}
function recommendIntensity(collective) {
  if (collective.average == null) return { key: "moderee", label: "Modérée", reason: "Pas assez de données de charge pour affiner — repli sur une intensité modérée par défaut." };
  if (collective.riskyCount >= collective.total / 2) return { key: "faible", label: "Faible", reason: `${collective.riskyCount}/${collective.total} joueurs en charge accrue ou élevée — mieux vaut lever le pied.` };
  if (collective.average < 0.8) return { key: "elevee", label: "Élevée", reason: "Le groupe est plutôt en sous-charge — l'intensité peut monter." };
  return { key: "moderee", label: "Modérée", reason: "Charge globale dans une zone équilibrée." };
}

