// Détecte les joueurs pour qui PLUSIEURS signaux se recoupent en même temps — pas un seul signal
// isolé (qui a déjà sa propre alerte ailleurs), mais la combinaison qu'aucun système pris seul ne
// peut voir : charge élevée ET wellness dégradé ET/OU absentéisme en hausse, ensemble.
function computeCrossSignalAlerts(roster, rpeLog, wellness, sessions) {
  const recentSessions = sessions.filter((s) => s.date < todayIso()).sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 5);
  return roster
    .map((p) => {
      const acwr = computeACWR(p.id, rpeLog, todayIso());
      const acwrRisky = acwr != null && (acwrRiskZone(acwr).key === "risque_eleve" || acwrRiskZone(acwr).key === "risque_accru");
      const latestWellness = wellness.filter((w) => w.playerId === p.id).sort((a, b) => new Date(b.date) - new Date(a.date))[0];
      const wellnessDegraded = !!(latestWellness && (latestWellness.fatigue >= 4 || latestWellness.stress >= 4 || latestWellness.sommeil <= 2));
      const absences = recentSessions.filter((s) => !(s.presence && s.presence[p.id])).length;
      const highAbsence = recentSessions.length >= 3 && absences >= Math.ceil(recentSessions.length / 2);
      const signalCount = [acwrRisky, wellnessDegraded, highAbsence].filter(Boolean).length;
      return { player: p, acwrRisky, wellnessDegraded, highAbsence, signalCount };
    })
    .filter((r) => r.signalCount >= 2);
}

