// Recommandation de fréquence — combine deux signaux déjà construits (ACWR, historique de
// blessures) plutôt que d'inventer un nouveau système. Transparent sur son raisonnement plutôt
// qu'un simple chiffre sorti de nulle part.
function recommendOsteoFrequency(playerId, rpeLog, injuries) {
  const acwr = computeACWR(playerId, rpeLog, todayIso());
  const zone = acwr != null ? acwrRiskZone(acwr).key : null;
  const injuryCount = injuries.filter((i) => i.playerId === playerId).length;
  if (zone === "risque_eleve" || injuryCount >= 3) return { frequency: "Toutes les 1 à 2 semaines", reason: `Charge en zone de risque élevé et/ou historique de ${injuryCount} blessure${injuryCount > 1 ? "s" : ""}.` };
  if (zone === "risque_accru" || injuryCount >= 1) return { frequency: "Toutes les 3 à 4 semaines", reason: `Charge en zone de risque accru et/ou au moins une blessure au dossier.` };
  return { frequency: "Suivi mensuel standard", reason: "Pas de signal de charge ou d'historique de blessure particulier." };
}

