// Réutilise l'historique de poids déjà construit dans les tests physiques plutôt que de le
// dupliquer — ajoute seulement ce qui manquait : une alerte de variation anormale entre deux relevés.
function detectAbnormalWeightVariation(player) {
  const history = getTestHistory(player, "poids").sort((a, b) => new Date(a.date) - new Date(b.date));
  if (history.length < 2) return null;
  const last = history[history.length - 1];
  const previous = history[history.length - 2];
  const prevVal = parseFloat(previous.value);
  const lastVal = parseFloat(last.value);
  if (!prevVal || !lastVal) return null;
  const percentVariation = ((lastVal - prevVal) / prevVal) * 100;
  if (Math.abs(percentVariation) >= 3) {
    return { percentVariation: Math.round(percentVariation * 10) / 10, lastDate: last.date, lastVal, prevVal };
  }
  return null;
}
