const OPPONENT_STYLES = ["Bloc bas", "Bloc médian", "Bloc haut"];

// Régression linéaire simple — un repère statistique basique, pas un modèle prédictif : sur peu de
// points et sans tenir compte de l'adversaire, de la tactique ou des blessures, ce n'est qu'une
// extrapolation naïve de la tendance. Présenté avec cette réserve explicite plutôt que comme une
// vraie prédiction, pour ne pas laisser croire à plus de rigueur qu'il n'y en a.
function linearRegression(points) {
  const n = points.length;
  if (n < 2) return null;
  const sumX = points.reduce((s, p) => s + p.x, 0);
  const sumY = points.reduce((s, p) => s + p.y, 0);
  const sumXY = points.reduce((s, p) => s + p.x * p.y, 0);
  const sumX2 = points.reduce((s, p) => s + p.x * p.x, 0);
  const denominator = n * sumX2 - sumX * sumX;
  if (denominator === 0) return null;
  const slope = (n * sumXY - sumX * sumY) / denominator;
  const intercept = (sumY - slope * sumX) / n;
  return { slope, intercept };
}

