function FormationJeunesArbitresTab() {
  const [referees, setReferees] = useState([]);
  const [mentorships, setMentorships] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [selectedId, setSelectedId] = useState("");
  const [form, setForm] = useState(null);

  useEffect(() => {
    getAllReferees().then(setReferees);
    try { setMentorships(JSON.parse(localStorage.getItem("tf_referee_mentorships") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) { setMentorships(next); try { localStorage.setItem("tf_referee_mentorships", JSON.stringify(next)); } catch (e) {} }
  function save() {
    if (!form.mentorName.trim() || !form.progressNote.trim()) { alert("Précise le mentor et une note de progression."); return; }
    persist([...mentorships, { ...form, refereeId: selectedId }]);
    setForm(null);
  }
  function remove(id) { if (!confirm("Supprimer ce mentorat ?")) return; persist(mentorships.filter((m) => m.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const jeunes = referees.filter((r) => r.level === "Jeunes uniquement");
  const entries = selectedId ? mentorships.filter((m) => m.refereeId === selectedId).sort((a, b) => new Date(b.date) - new Date(a.date)) : [];

  return (
    <div>
      <p className="radar-note">Le suivi de progression des jeunes arbitres du club (niveau "Jeunes uniquement" dans le répertoire), avec mentor associé.</p>
      <label style={{ display: "inline-block", marginBottom: 16 }}>
        Jeune arbitre
        <select value={selectedId} onChange={(e) => { setSelectedId(e.target.value); setForm(null); }} style={{ display: "block", marginTop: 4 }}>
          <option value="">Choisir…</option>
          {jeunes.map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}
        </select>
      </label>
      {jeunes.length === 0 && <div className="empty-state">Aucun arbitre "Jeunes uniquement" dans le répertoire pour l'instant.</div>}
      {selectedId && (
        <>
          {!form && <button className="btn btn-primary btn-small" onClick={() => setForm(emptyMentorshipEntry(selectedId))} style={{ marginBottom: 16, display: "block" }}>+ Nouvelle note de suivi</button>}
          {form && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <label>Mentor<input type="text" value={form.mentorName} onChange={(e) => setForm((f) => ({ ...f, mentorName: e.target.value }))} autoFocus /></label>
              <label>Progression<textarea rows={2} value={form.progressNote} onChange={(e) => setForm((f) => ({ ...f, progressNote: e.target.value }))} /></label>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => setForm(null)}>Annuler</button>
                <button className="btn btn-primary" onClick={save}>Enregistrer</button>
              </div>
            </div>
          )}
          {entries.length === 0 && <div className="empty-state">Aucune note de suivi pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
          <div className="scouting-list">
            {entries.map((m) => (
              <div className="scouting-card" key={m.id}>
                <div className="scouting-info">
                  <div className="scouting-name">{formatDateFr(m.date)} <span className="scouting-club">Mentor : {m.mentorName}</span></div>
                  <div className="scouting-meta">{m.progressNote}</div>
                </div>
                <button className="icon-btn" onClick={() => remove(m.id)} aria-label="Supprimer"><X size={14} /></button>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function CouvertureArbitraleTab() {
  const [referees, setReferees] = useState([]);
  const [fixtures, setFixtures] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    getAllReferees().then(setReferees);
    try {
      const comp = loadCompetitionsData();
      const upcoming = comp.competitions.flatMap((c) => c.fixtures.filter((f) => !fixtureIsPlayed(f)).map((f) => ({ key: `${c.id}_${f.id}`, label: `${formatDateFr(f.date)} — vs ${f.opponent}`, date: f.date })));
      setFixtures(upcoming.sort((a, b) => new Date(a.date) - new Date(b.date)));
    } catch (e) { setFixtures([]); }
    try { setAssignments(JSON.parse(localStorage.getItem("tf_referee_coverage") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) { setAssignments(next); try { localStorage.setItem("tf_referee_coverage", JSON.stringify(next)); } catch (e) {} }
  function setReferee(fixtureKey, fixtureLabel, refereeId) {
    const existing = assignments.find((a) => a.fixtureKey === fixtureKey);
    if (existing) persist(assignments.map((a) => (a.fixtureKey === fixtureKey ? { ...a, refereeId, covered: !!refereeId } : a)));
    else persist([...assignments, { ...emptyCoverageAssignment(fixtureKey, fixtureLabel), refereeId, covered: !!refereeId }]);
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const coveredCount = fixtures.filter((f) => assignments.find((a) => a.fixtureKey === f.key)?.covered).length;

  return (
    <div>
      <p className="radar-note">Matchs à venir vs arbitres disponibles — {coveredCount}/{fixtures.length} match{fixtures.length !== 1 ? "s" : ""} couvert{coveredCount !== 1 ? "s" : ""}.</p>
      {fixtures.length === 0 && <div className="empty-state">Aucun match à venir pour l'instant — les matchs programmés dans Compétitions apparaîtront ici automatiquement.</div>}
      <div className="scouting-list">
        {fixtures.map((f) => {
          const assignment = assignments.find((a) => a.fixtureKey === f.key);
          return (
            <div className="scouting-card" key={f.key}>
              <div className="scouting-info">
                <div className="scouting-name">{f.label} <span className="scouting-club">{assignment?.covered ? "Couvert" : "À pourvoir"}</span></div>
              </div>
              <select value={assignment?.refereeId || ""} onChange={(e) => setReferee(f.key, f.label, e.target.value)}>
                <option value="">Non assigné</option>
                {referees.map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}
              </select>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ValorisationArbitresTab() {
  const [referees, setReferees] = useState([]);
  const [recognitions, setRecognitions] = useState({});
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    getAllReferees().then(setReferees);
    try { setRecognitions(JSON.parse(localStorage.getItem("tf_referee_recognitions") || "{}")); } catch (e) {}
    setLoaded(true);
  }, []);

  function setSince(refereeId, since) {
    const next = { ...recognitions, [refereeId]: { ...(recognitions[refereeId] || {}), memberSince: since } };
    setRecognitions(next);
    try { localStorage.setItem("tf_referee_recognitions", JSON.stringify(next)); } catch (e) {}
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Reconnaître l'implication et l'ancienneté des arbitres du club.</p>
      {referees.length === 0 && <div className="empty-state">Aucun arbitre dans le répertoire pour l'instant.</div>}
      <div className="scouting-list">
        {referees.map((r) => {
          const since = recognitions[r.id]?.memberSince;
          const years = since ? Math.floor((new Date(todayIso()) - new Date(since)) / (365 * 86400000)) : null;
          return (
            <div className="scouting-card" key={r.id}>
              <div className="scouting-info">
                <div className="scouting-name">{r.name} <span className="scouting-club">{years != null ? `${years} an${years !== 1 ? "s" : ""} au club` : "Ancienneté non renseignée"}</span></div>
              </div>
              <input type="date" value={since || ""} onChange={(e) => setSince(r.id, e.target.value)} />
            </div>
          );
        })}
      </div>
    </div>
  );
}

