function AutoEvaluationTab() {
  const [assessments, setAssessments] = useState([]);
  const [fixtures, setFixtures] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(null);
  const FEELING_LABELS = { 1: "Très difficile", 2: "Difficile", 3: "Correct", 4: "Bien géré", 5: "Très bien géré" };

  useEffect(() => {
    try { setAssessments(JSON.parse(localStorage.getItem("tf_referee_self_assessments") || "[]")); } catch (e) {}
    try {
      const comp = loadCompetitionsData();
      const played = comp.competitions.flatMap((c) => c.fixtures.filter(fixtureIsPlayed).map((f) => ({ key: `${c.id}_${f.id}`, label: `${formatDateFr(f.date)} — vs ${f.opponent}` })));
      setFixtures(played);
    } catch (e) { setFixtures([]); }
    setLoaded(true);
  }, []);

  function persist(next) { setAssessments(next); try { localStorage.setItem("tf_referee_self_assessments", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptySelfAssessment("", "")); setEditingId(null); setShowForm(true); }
  function openEdit(a) { setForm(a); setEditingId(a.id); setShowForm(true); }
  function save() {
    if (!form.fixtureKey) { alert("Choisis le match concerné."); return; }
    persist(editingId ? assessments.map((a) => (a.id === editingId ? form : a)) : [...assessments, form]);
    setShowForm(false);
    setEditingId(null);
  }
  function remove(id) { if (!confirm("Supprimer cette auto-évaluation ?")) return; persist(assessments.filter((a) => a.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Ton propre ressenti après un match arbitré — pour toi, pas pour le club.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle auto-évaluation</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Match
            <select value={form.fixtureKey} onChange={(e) => { const f = fixtures.find((x) => x.key === e.target.value); setForm((v) => ({ ...v, fixtureKey: e.target.value, fixtureLabel: f ? f.label : "" })); }}>
              <option value="">Choisir…</option>
              {fixtures.map((f) => <option key={f.key} value={f.key}>{f.label}</option>)}
            </select>
          </label>
          <div className="radar-range-label">Ressenti</div>
          <div className="qcm-options">
            {[1, 2, 3, 4, 5].map((n) => <button key={n} type="button" className={`qcm-option ${form.feeling === n ? "selected" : ""}`} onClick={() => setForm((f) => ({ ...f, feeling: n }))}>{FEELING_LABELS[n]}</button>)}
          </div>
          <label>Difficultés rencontrées<textarea rows={2} value={form.difficulties} onChange={(e) => setForm((f) => ({ ...f, difficulties: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {assessments.length === 0 && <div className="empty-state">Aucune auto-évaluation pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {assessments.map((a) => (
          <div className="scouting-card" key={a.id}>
            <div className="scouting-info">
              <div className="scouting-name">{a.fixtureLabel} <span className="scouting-club">{FEELING_LABELS[a.feeling]}</span></div>
              {a.difficulties && <div className="scouting-meta">{a.difficulties}</div>}
            </div>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(a)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(a.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function DisponibilitesTab() {
  const [availabilities, setAvailabilities] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [form, setForm] = useState(emptyAvailability());

  useEffect(() => {
    try { setAvailabilities(JSON.parse(localStorage.getItem("tf_referee_availabilities") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) { setAvailabilities(next); try { localStorage.setItem("tf_referee_availabilities", JSON.stringify(next)); } catch (e) {} }
  function save() {
    if (!form.date) { alert("Choisis une date."); return; }
    persist([...availabilities, form]);
    setForm(emptyAvailability());
  }
  function remove(id) { if (!confirm("Supprimer cette disponibilité ?")) return; persist(availabilities.filter((a) => a.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Déclare tes disponibilités à l'avance, pour faciliter la planification du référent arbitrage.</p>
      <div className="new-match-card" style={{ marginBottom: 16 }}>
        <label>Date<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
        <label style={{ display: "block", marginTop: 8 }}>
          <input type="checkbox" checked={form.available} onChange={(e) => setForm((f) => ({ ...f, available: e.target.checked }))} style={{ marginRight: 6 }} />
          Disponible
        </label>
        <label>Note (optionnel)<input type="text" value={form.note} onChange={(e) => setForm((f) => ({ ...f, note: e.target.value }))} /></label>
        <button className="btn btn-primary btn-small" onClick={save} style={{ marginTop: 8 }}>Enregistrer</button>
      </div>
      {availabilities.length === 0 && <div className="empty-state">Aucune disponibilité déclarée pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {[...availabilities].sort((a, b) => new Date(a.date) - new Date(b.date)).map((a) => (
          <div className="scouting-card" key={a.id}>
            <div className="scouting-info">
              <div className="scouting-name">{formatDateFr(a.date)} <span className="scouting-club">{a.available ? "Disponible" : "Indisponible"}</span></div>
              {a.note && <div className="scouting-meta">{a.note}</div>}
            </div>
            <button className="icon-btn" onClick={() => remove(a.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

