function RetourExperienceTab() {
  const [feedbacks, setFeedbacks] = useState([]);
  const [fixtures, setFixtures] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(null);

  useEffect(() => {
    try { setFeedbacks(JSON.parse(localStorage.getItem("tf_referee_feedback") || "[]")); } catch (e) {}
    try {
      const comp = loadCompetitionsData();
      const played = comp.competitions.flatMap((c) => c.fixtures.filter(fixtureIsPlayed).map((f) => ({ key: `${c.id}_${f.id}`, label: `${formatDateFr(f.date)} — vs ${f.opponent}` })));
      setFixtures(played);
    } catch (e) { setFixtures([]); }
    setLoaded(true);
  }, []);

  function persist(next) { setFeedbacks(next); try { localStorage.setItem("tf_referee_feedback", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyFeedbackToReferee("", "")); setEditingId(null); setShowForm(true); }
  function openEdit(f) { setForm(f); setEditingId(f.id); setShowForm(true); }
  function save() {
    if (!form.fixtureKey || !form.content.trim()) { alert("Choisis le match et écris le retour."); return; }
    persist(editingId ? feedbacks.map((f) => (f.id === editingId ? form : f)) : [...feedbacks, form]);
    setShowForm(false);
    setEditingId(null);
  }
  function exportFeedback(f) {
    const blob = new Blob([`Retour d'expérience — ${f.fixtureLabel}\n${formatDateFr(f.date)}\n\n${f.content}`], { type: "text/plain" });
    triggerDownload(blob, `retour_arbitre_${f.fixtureKey}.txt`);
  }
  function remove(id) { if (!confirm("Supprimer ce retour d'expérience ?")) return; persist(feedbacks.filter((f) => f.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Un retour structuré transmis à l'arbitre après le match, au-delà du compte-rendu interne — exportable pour lui être envoyé.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouveau retour</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Match
            <select value={form.fixtureKey} onChange={(e) => { const f = fixtures.find((x) => x.key === e.target.value); setForm((v) => ({ ...v, fixtureKey: e.target.value, fixtureLabel: f ? f.label : "" })); }}>
              <option value="">Choisir…</option>
              {fixtures.map((f) => <option key={f.key} value={f.key}>{f.label}</option>)}
            </select>
          </label>
          <label>Retour<textarea rows={3} value={form.content} onChange={(e) => setForm((f) => ({ ...f, content: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {feedbacks.length === 0 && <div className="empty-state">Aucun retour pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
      <div className="scouting-list">
        {feedbacks.map((f) => (
          <div className="scouting-card" key={f.id}>
            <div className="scouting-info">
              <div className="scouting-name">{f.fixtureLabel} <span className="scouting-club">{formatDateFr(f.date)}</span></div>
              <div className="scouting-meta">{f.content}</div>
            </div>
            <button className="btn btn-ghost btn-small" onClick={() => exportFeedback(f)}>Exporter</button>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(f)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(f.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function InfosPratiquesTab() {
  const [info, setInfo] = useState({ adresse: "", accesTerrain: "", vestiaires: "", contactJour: "" });
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setInfo({ adresse: "", accesTerrain: "", vestiaires: "", contactJour: "", ...JSON.parse(localStorage.getItem("tf_referee_practical_info") || "{}") }); } catch (e) {}
    setLoaded(true);
  }, []);

  function update(field, value) {
    const next = { ...info, [field]: value };
    setInfo(next);
    try { localStorage.setItem("tf_referee_practical_info", JSON.stringify(next)); } catch (e) {}
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Les infos pratiques à transmettre à un arbitre officiel qui vient chez toi — accès terrain, vestiaires, contact du jour.</p>
      <div className="new-match-card">
        <label>Adresse<input type="text" value={info.adresse} onChange={(e) => update("adresse", e.target.value)} /></label>
        <label>Accès terrain<input type="text" value={info.accesTerrain} onChange={(e) => update("accesTerrain", e.target.value)} /></label>
        <label>Vestiaires<input type="text" value={info.vestiaires} onChange={(e) => update("vestiaires", e.target.value)} /></label>
        <label>Contact du jour<input type="text" value={info.contactJour} onChange={(e) => update("contactJour", e.target.value)} /></label>
      </div>
    </div>
  );
}

// --- Président ---
const DECISION_TYPES = ["Motion", "Vote", "Décision administrative", "Autre"];
function emptyDecision() { return { id: newId(), date: todayIso(), type: "Motion", title: "", description: "" }; }
function emptyStatutoryObligation() { return { id: newId(), title: "", dueDate: todayIso(), notes: "" }; }
function emptyInstitutionalContact() { return { id: newId(), name: "", organization: "", role: "", phone: "", email: "" }; }

