// Réutilise le registre des décisions déjà construit pour le président (tf_governance_decisions)
// plutôt que d'en dupliquer un nouveau — ajoute juste ce qui manquait : un statut d'exécution.
function ExecutionDecisionsTab() {
  const [decisions, setDecisions] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => { try { setDecisions(JSON.parse(localStorage.getItem("tf_governance_decisions") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function setExecutionStatus(id, status) {
    const next = decisions.map((d) => (d.id === id ? { ...d, executionStatus: status } : d));
    setDecisions(next);
    try { localStorage.setItem("tf_governance_decisions", JSON.stringify(next)); } catch (e) {}
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Les décisions du registre (Direction → Gouvernance), avec leur statut d'exécution.</p>
      {decisions.length === 0 && <div className="empty-state">Aucune décision enregistrée pour l'instant — à créer depuis Président / Gouvernance, onglet Gouvernance.</div>}
      <div className="scouting-list">
        {[...decisions].sort((a, b) => new Date(b.date) - new Date(a.date)).map((d) => (
          <div className="scouting-card" key={d.id}>
            <div className="scouting-info">
              <div className="scouting-name">{d.title} <span className="scouting-club">{formatDateFr(d.date)}</span></div>
            </div>
            <select value={d.executionStatus || "À faire"} onChange={(e) => setExecutionStatus(d.id, e.target.value)}>
              {EXECUTION_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
        ))}
      </div>
    </div>
  );
}

function ConsultationVoteTab() {
  const [polls, setPolls] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyPoll());
  const [voterName, setVoterName] = useState("");

  useEffect(() => { try { setPolls(JSON.parse(localStorage.getItem("tf_bureau_polls") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setPolls(next); try { localStorage.setItem("tf_bureau_polls", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyPoll()); setEditingId(null); setShowForm(true); }
  function openEdit(p) { setForm(p); setEditingId(p.id); setShowForm(true); }
  function save() {
    if (!form.question.trim()) { alert("Pose la question à voter."); return; }
    if (editingId) {
      const original = polls.find((p) => p.id === editingId);
      const questionChanged = original && original.question !== form.question;
      if (questionChanged && Object.keys(form.votes).length > 0) {
        if (!confirm(`La question a changé — les ${Object.keys(form.votes).length} vote(s) déjà enregistré(s) seront effacés et le vote relancé à zéro pour tout le monde. Continuer ?`)) return;
      }
      persist(polls.map((p) => (p.id === editingId ? { ...form, votes: questionChanged ? {} : form.votes } : p)));
    } else {
      persist([...polls, form]);
    }
    setShowForm(false);
    setEditingId(null);
    setForm(emptyPoll());
  }
  function castVote(pollId, option) {
    if (!voterName.trim()) { alert("Indique ton nom pour voter."); return; }
    persist(polls.map((p) => (p.id === pollId ? { ...p, votes: { ...p.votes, [voterName.trim()]: option } } : p)));
  }
  function remove(id) { if (!confirm("Supprimer ce vote ?")) return; persist(polls.filter((p) => p.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Un espace de consultation simplifié pour les décisions courantes du bureau.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle consultation</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Question<input type="text" value={form.question} onChange={(e) => setForm((f) => ({ ...f, question: e.target.value }))} autoFocus /></label>
          {editingId && Object.keys(form.votes).length > 0 && (
            <p className="hint">Changer le texte de la question effacera les {Object.keys(form.votes).length} vote(s) actuel(s) et relancera le vote à zéro.</p>
          )}
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {polls.length === 0 && <div className="empty-state">Aucune consultation pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {polls.map((p) => {
          const counts = p.options.map((o) => ({ option: o, count: Object.values(p.votes).filter((v) => v === o).length }));
          return (
            <div className="scouting-card" key={p.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
              <div className="scouting-info">
                <div className="scouting-name">{p.question}</div>
                <div className="scouting-meta">{counts.map((c) => `${c.option} : ${c.count}`).join(" · ")} ({Object.keys(p.votes).length} vote{Object.keys(p.votes).length !== 1 ? "s" : ""})</div>
              </div>
              <div style={{ display: "flex", gap: 6, marginTop: 8, flexWrap: "wrap" }}>
                <input type="text" placeholder="Ton nom" value={voterName} onChange={(e) => setVoterName(e.target.value)} style={{ maxWidth: 140 }} />
                {p.options.map((o) => <button key={o} className="btn btn-ghost btn-small" onClick={() => castVote(p.id, o)}>{o}</button>)}
                <button className="btn btn-ghost btn-small" onClick={() => openEdit(p)}>Modifier</button>
                <button className="icon-btn" onClick={() => remove(p.id)} aria-label="Supprimer">✕</button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

