function emptyStrategicObjective() { return { id: newId(), title: "", domain: "Sportif", milestone: "", targetDate: todayIso(), status: "En cours" }; }
const STRATEGIC_DOMAINS = ["Sportif", "Business", "Formation", "Infrastructure"];
const OBJECTIVE_STATUSES_DG = ["En cours", "Atteint", "Compromis"];
function emptyRisk() { return { id: newId(), title: "", category: "Financier", severity: "Modérée", mitigationNote: "" }; }
