const RISK_SEVERITIES = ["Faible", "Modérée", "Élevée"];

// --- Directeur sportif ---
function RecrutementConsolideScreen() {
  const [scouted, setScouted] = useState([]);
  const [overclassReviews, setOverclassReviews] = useState({});
  const [allPlayers, setAllPlayers] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setScouted(JSON.parse(localStorage.getItem("tf_scouting") || "[]")); } catch (e) {}
    try { setOverclassReviews(JSON.parse(localStorage.getItem("tf_overclass_reviews") || "{}")); } catch (e) {}
    try {
      const teams = JSON.parse(localStorage.getItem("tf_teams") || "[]");
      const seasonId = getActiveSeasonId();
      const players = teams.flatMap((t) => {
        try { return JSON.parse(readScopedKeyFor("tf_roster", t.id, seasonId) || "[]").map((p) => ({ ...p, teamName: t.name })); } catch (e) { return []; }
      });
      setAllPlayers(players);
    } catch (e) {}
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const confirmedInternal = Object.entries(overclassReviews)
    .filter(([playerId, r]) => r.status === "Confirmé")
    .map(([playerId, r]) => ({ player: allPlayers.find((p) => p.id === playerId), review: r }));

  return (
    <div>
      <p className="radar-note">Recrutement externe (scouting) et espoirs internes confirmés (surclassement), réunis en une vue — pour voir d'un coup d'œil où sont concentrées tes options par poste.</p>

      <div className="panel-heading" style={{ marginTop: 0 }}>Cibles externes ({scouted.length})</div>
      {scouted.length === 0 && <div className="empty-state">Aucun joueur suivi pour l'instant — ajoutes-en depuis Analyse et vidéo → Scouting.</div>}
      <div className="scouting-list" style={{ marginBottom: 20 }}>
        {scouted.map((p) => (
          <div className="scouting-card" key={p.id}>
            <div className="scouting-info">
              <div className="scouting-name">{p.name} <span className="scouting-club">{p.position}</span></div>
              <div className="scouting-meta">{p.club}</div>
            </div>
          </div>
        ))}
      </div>

      <div className="panel-heading">Espoirs internes confirmés ({confirmedInternal.length})</div>
      <p className="hint" style={{ marginTop: 0 }}>Les joueurs dont le surclassement a été confirmé par le coordinateur technique (Club → surclassement).</p>
      {confirmedInternal.length === 0 && <div className="empty-state">Aucun espoir interne confirmé pour l'instant.</div>}
      <div className="scouting-list">
        {confirmedInternal.map(({ player, review }, i) => (
          <div className="scouting-card" key={i}>
            <div className="scouting-info">
              <div className="scouting-name">{player ? playerFullName(player) : "Joueur (fiche supprimée depuis)"} <span className="scouting-club">{player?.teamName}</span></div>
              {review.note && <div className="scouting-meta">{review.note}</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function CoherenceToutesCategoriesScreen() {
  const [teams, setTeams] = useState([]);
  const [pedagogyEntries, setPedagogyEntries] = useState([]);
  const [teamData, setTeamData] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    let loadedTeams = [];
    try { loadedTeams = JSON.parse(localStorage.getItem("tf_teams") || "[]"); } catch (e) {}
    setTeams(loadedTeams);
    try { setPedagogyEntries(JSON.parse(localStorage.getItem("tf_club_pedagogy") || "[]")); } catch (e) {}
    const seasonId = getActiveSeasonId();
    const results = loadedTeams.map((t) => {
      let sessionCount = 0;
      try { sessionCount = JSON.parse(readScopedKeyFor("tf_sessions", t.id, seasonId) || "[]").length; } catch (e) {}
      return { team: t, sessionCount };
    });
    setTeamData(results);
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const categories = [...new Set(teams.map((t) => t.category).filter(Boolean))];

  return (
    <div>
      <p className="radar-note">Un résumé de la cohérence pédagogique sur toutes les catégories à la fois — le détail complet par catégorie (comparé aux séances réellement travaillées) reste dans Vestiaire → Application du projet formation.</p>
      {categories.length === 0 && <div className="empty-state">Aucune catégorie définie pour l'instant — renseigne une catégorie sur tes équipes dans Vestiaire → Effectifs.</div>}
      <div className="scouting-list">
        {categories.map((cat) => {
          const hasPedagogy = pedagogyEntries.some((e) => e.category === cat && PEDAGOGY_THEMES.some((t) => themeHasContent(e, t.key)));
          const teamsInCategory = teamData.filter((td) => td.team.category === cat);
          const totalSessions = teamsInCategory.reduce((s, td) => s + td.sessionCount, 0);
          return (
            <div className="scouting-card" key={cat}>
              <div className="scouting-info">
                <div className="scouting-name">{cat} <span className="scouting-club">{hasPedagogy ? "Référentiel renseigné" : "Référentiel vide"}</span></div>
                <div className="scouting-meta">{teamsInCategory.length} équipe{teamsInCategory.length !== 1 ? "s" : ""} · {totalSessions} séance{totalSessions !== 1 ? "s" : ""} au total</div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

