function MissionsPonctuellesTab() {
  const [missions, setMissions] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyMission());

  useEffect(() => { try { setMissions(JSON.parse(localStorage.getItem("tf_dirigeant_missions") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setMissions(next); try { localStorage.setItem("tf_dirigeant_missions", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyMission()); setEditingId(null); setShowForm(true); }
  function openEdit(m) { setForm(m); setEditingId(m.id); setShowForm(true); }
  function save() {
    if (!form.title.trim()) { alert("Donne un titre à cette mission."); return; }
    persist(editingId ? missions.map((m) => (m.id === editingId ? form : m)) : [...missions, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyMission());
  }
  function setStatus(id, status) { persist(missions.map((m) => (m.id === id ? { ...m, status } : m))); }
  function remove(id) { if (!confirm("Supprimer cette mission ?")) return; persist(missions.filter((m) => m.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Les missions ponctuelles confiées — buvette du week-end, organisation d'un événement, etc.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle mission</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Titre<input type="text" value={form.title} onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))} autoFocus /></label>
          <label>Échéance (optionnel)<input type="date" value={form.dueDate} onChange={(e) => setForm((f) => ({ ...f, dueDate: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {missions.length === 0 && <div className="empty-state">Aucune mission pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {missions.map((m) => (
          <div className="scouting-card" key={m.id}>
            <div className="scouting-info">
              <div className="scouting-name">{m.title} {m.dueDate && <span className="scouting-club">{formatDateFr(m.dueDate)}</span>}</div>
            </div>
            <select value={m.status} onChange={(e) => setStatus(m.id, e.target.value)}>
              {MISSION_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(m)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(m.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

