function CalendrierEditorialTab() {
  const [entries, setEntries] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyEditorialEntry());

  useEffect(() => { try { setEntries(JSON.parse(localStorage.getItem("tf_editorial_calendar") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setEntries(next); try { localStorage.setItem("tf_editorial_calendar", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyEditorialEntry()); setEditingId(null); setShowForm(true); }
  function openEdit(e) { setForm(e); setEditingId(e.id); setShowForm(true); }
  function save() {
    if (!form.title.trim()) { alert("Donne un titre à cette publication."); return; }
    persist(editingId ? entries.map((e) => (e.id === editingId ? form : e)) : [...entries, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyEditorialEntry());
  }
  function setStatus(id, status) { persist(entries.map((e) => (e.id === id ? { ...e, status } : e))); }
  function remove(id) { if (!confirm("Supprimer cette publication ?")) return; persist(entries.filter((e) => e.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Quoi publier, quand, sur quel canal.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle publication</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Titre<input type="text" value={form.title} onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))} autoFocus /></label>
          <div className="roster-physical-grid">
            <label>Canal
              <select value={form.channel} onChange={(e) => setForm((f) => ({ ...f, channel: e.target.value }))}>
                {COMM_CHANNELS.map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </label>
            <label>Date<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
          </div>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {entries.length === 0 && <div className="empty-state">Aucune publication planifiée pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {[...entries].sort((a, b) => new Date(a.date) - new Date(b.date)).map((e) => (
          <div className="scouting-card" key={e.id}>
            <div className="scouting-info">
              <div className="scouting-name">{e.title} <span className="scouting-club">{e.channel}</span></div>
              <div className="scouting-meta">{formatDateFr(e.date)}</div>
            </div>
            <select value={e.status} onChange={(ev) => setStatus(e.id, ev.target.value)}>
              {EDITORIAL_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(e)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(e.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

