// --- Attaché de presse ---
function emptyPressContact() { return { id: newId(), name: "", outlet: "", email: "", phone: "" }; }
function emptyPressSolicitation(contactId) { return { id: newId(), contactId, date: todayIso(), subject: "" }; }
function emptyInterviewRequest() { return { id: newId(), requester: "", date: todayIso(), status: "En attente", notes: "" }; }
const INTERVIEW_STATUSES = ["En attente", "Acceptée", "Déclinée", "Réalisée"];


function ContactsPresseTab() {
  const [contacts, setContacts] = useState([]);
  const [solicitations, setSolicitations] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyPressContact());
  const [openId, setOpenId] = useState(null);
  const [solicitationText, setSolicitationText] = useState("");

  useEffect(() => {
    try { setContacts(JSON.parse(localStorage.getItem("tf_press_contacts") || "[]")); } catch (e) {}
    try { setSolicitations(JSON.parse(localStorage.getItem("tf_press_solicitations") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);
  function persistContacts(next) { setContacts(next); try { localStorage.setItem("tf_press_contacts", JSON.stringify(next)); } catch (e) {} }
  function persistSolicitations(next) { setSolicitations(next); try { localStorage.setItem("tf_press_solicitations", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyPressContact()); setEditingId(null); setShowForm(true); }
  function openEdit(c) { setForm(c); setEditingId(c.id); setShowForm(true); }
  function save() {
    if (!form.name.trim()) { alert("Donne un nom à ce contact."); return; }
    persistContacts(editingId ? contacts.map((c) => (c.id === editingId ? form : c)) : [...contacts, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyPressContact());
  }
  function removeContact(id) {
    if (!confirm("Supprimer ce contact presse et tout son historique de sollicitations ?")) return;
    persistContacts(contacts.filter((c) => c.id !== id));
    persistSolicitations(solicitations.filter((s) => s.contactId !== id));
    if (openId === id) setOpenId(null);
  }
  function addSolicitation() {
    if (!solicitationText.trim()) { alert("Décris la sollicitation avant de l'ajouter."); return; }
    persistSolicitations([...solicitations, { ...emptyPressSolicitation(openId), subject: solicitationText.trim() }]);
    setSolicitationText("");
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  if (openId) {
    const contact = contacts.find((c) => c.id === openId);
    if (!contact) { setOpenId(null); return null; }
    const contactSolicitations = solicitations.filter((s) => s.contactId === openId).sort((a, b) => new Date(b.date) - new Date(a.date));
    return (
      <div>
        <button className="btn btn-ghost btn-small" onClick={() => setOpenId(null)} style={{ marginBottom: 14 }}>‹ Retour</button>
        <div className="panel-heading" style={{ marginTop: 0 }}>{contact.name}</div>
        <p className="hint" style={{ marginTop: 0 }}>{contact.outlet}</p>
        {!showForm && <button className="btn btn-ghost btn-small" onClick={() => openEdit(contact)} style={{ marginBottom: 16 }}>Modifier ce contact</button>}
        {showForm && (
          <div className="new-match-card" style={{ marginBottom: 16 }}>
            <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
            <label>Média<input type="text" value={form.outlet} onChange={(e) => setForm((f) => ({ ...f, outlet: e.target.value }))} /></label>
            <div className="roster-physical-grid">
              <label>Email<input type="text" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></label>
              <label>Téléphone<input type="text" value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></label>
            </div>
            <div className="form-actions">
              <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
              <button className="btn btn-primary" onClick={save}>Enregistrer</button>
            </div>
          </div>
        )}
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Nouvelle sollicitation<input type="text" value={solicitationText} onChange={(e) => setSolicitationText(e.target.value)} /></label>
          <button className="btn btn-primary btn-small" onClick={addSolicitation} style={{ marginTop: 8 }}>Ajouter</button>
        </div>
        {contactSolicitations.length === 0 && <div className="empty-state">Aucune sollicitation pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
        <div className="scouting-list">
          {contactSolicitations.map((s) => (
            <div className="scouting-card" key={s.id}>
              <div className="scouting-info"><div className="scouting-name">{s.subject} <span className="scouting-club">{formatDateFr(s.date)}</span></div></div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Journalistes locaux, médias spécialisés — avec historique des sollicitations.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouveau contact</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
          <label>Média<input type="text" value={form.outlet} onChange={(e) => setForm((f) => ({ ...f, outlet: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>Email<input type="text" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></label>
            <label>Téléphone<input type="text" value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></label>
          </div>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {contacts.length === 0 && <div className="empty-state">Aucun contact pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
      <div className="scouting-list">
        {contacts.map((c) => {
          const count = solicitations.filter((s) => s.contactId === c.id).length;
          return (
            <div className="scouting-card" key={c.id} onClick={() => setOpenId(c.id)} style={{ cursor: "pointer" }}>
              <div className="scouting-info">
                <div className="scouting-name">{c.name} <span className="scouting-club">{c.outlet}</span></div>
                <div className="scouting-meta">{count} sollicitation{count !== 1 ? "s" : ""}</div>
              </div>
              <button className="icon-btn" onClick={(e) => { e.stopPropagation(); removeContact(c.id); }} aria-label="Supprimer"><X size={14} /></button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function KitMediaTab() {
  const [kit, setKit] = useState({ logoLocation: "", officialPhotosLocation: "", talkingPoints: "" });
  const [loaded, setLoaded] = useState(false);

  useEffect(() => { try { setKit({ logoLocation: "", officialPhotosLocation: "", talkingPoints: "", ...JSON.parse(localStorage.getItem("tf_media_kit") || "{}") }); } catch (e) {} setLoaded(true); }, []);
  function update(field, value) {
    const next = { ...kit, [field]: value };
    setKit(next);
    try { localStorage.setItem("tf_media_kit", JSON.stringify(next)); } catch (e) {}
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Le kit média du club, prêt à l'envoi — logo, photos officielles, éléments de langage.</p>
      <div className="new-match-card">
        <label>Où trouver le logo<input type="text" value={kit.logoLocation} onChange={(e) => update("logoLocation", e.target.value)} /></label>
        <label>Où trouver les photos officielles<input type="text" value={kit.officialPhotosLocation} onChange={(e) => update("officialPhotosLocation", e.target.value)} /></label>
        <label>Éléments de langage<textarea rows={4} value={kit.talkingPoints} onChange={(e) => update("talkingPoints", e.target.value)} /></label>
      </div>
    </div>
  );
}

function DemandesInterviewTab() {
  const [requests, setRequests] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyInterviewRequest());

  useEffect(() => { try { setRequests(JSON.parse(localStorage.getItem("tf_interview_requests") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setRequests(next); try { localStorage.setItem("tf_interview_requests", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyInterviewRequest()); setEditingId(null); setShowForm(true); }
  function openEdit(r) { setForm(r); setEditingId(r.id); setShowForm(true); }
  function save() {
    if (!form.requester.trim()) { alert("Précise qui demande l'interview."); return; }
    persist(editingId ? requests.map((r) => (r.id === editingId ? form : r)) : [...requests, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyInterviewRequest());
  }
  function setStatus(id, status) { persist(requests.map((r) => (r.id === id ? { ...r, status } : r))); }
  function remove(id) { if (!confirm("Supprimer cette demande d'interview ?")) return; persist(requests.filter((r) => r.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Les demandes d'interview et leur traitement.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle demande</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Demandeur<input type="text" value={form.requester} onChange={(e) => setForm((f) => ({ ...f, requester: e.target.value }))} autoFocus /></label>
          <label>Notes<textarea rows={2} value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {requests.length === 0 && <div className="empty-state">Aucune demande pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {requests.map((r) => (
          <div className="scouting-card" key={r.id}>
            <div className="scouting-info">
              <div className="scouting-name">{r.requester} <span className="scouting-club">{formatDateFr(r.date)}</span></div>
              {r.notes && <div className="scouting-meta">{r.notes}</div>}
            </div>
            <select value={r.status} onChange={(e) => setStatus(r.id, e.target.value)}>
              {INTERVIEW_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(r)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(r.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

