// --- Regroupements de navigation (allègement du menu Vestiaire) ---
// Chaque wrapper ci-dessous ne fait qu'ajouter un premier niveau de sélection au-dessus
// d'écrans déjà existants et fonctionnels — aucun de ces écrans n'est modifié dans son
// fonctionnement interne, seule la façon d'y accéder change.
function FiliereJeunesScreen() {
  const [tab, setTab] = useState("suivi");
  const [aggregatedRoster, setAggregatedRoster] = useState([]);
  const [clubType, setClubType] = useState("mixte");

  useEffect(() => {
    try {
      const teams = JSON.parse(localStorage.getItem("tf_teams") || "[]");
      const seasonId = getActiveSeasonId();
      const all = teams.flatMap((t) => {
        try { return JSON.parse(readScopedKeyFor("tf_roster", t.id, seasonId) || "[]"); } catch (e) { return []; }
      });
      setAggregatedRoster(all);
    } catch (e) { setAggregatedRoster([]); }
    try { setClubType(JSON.parse(localStorage.getItem("tf_club_info") || "{}").type || "mixte"); } catch (e) {}
  }, []);

  const [femResources, setFemResources] = useState([]);
  useEffect(() => {
    try { setFemResources(JSON.parse(localStorage.getItem("tf_feminine_resources") || "[]")); } catch (e) {}
  }, []);
  function persistFemResources(next) { setFemResources(next); try { localStorage.setItem("tf_feminine_resources", JSON.stringify(next)); } catch (e) {} }

  return (
    <div>
      <div className="tabs" style={{ marginBottom: 14, flexWrap: "wrap" }}>
        <button className={`tab ${tab === "suivi" ? "active" : ""}`} onClick={() => setTab("suivi")}>Suivi jeunes</button>
        <button className={`tab ${tab === "application" ? "active" : ""}`} onClick={() => setTab("application")}>Application du projet</button>
        <button className={`tab ${tab === "anciens" ? "active" : ""}`} onClick={() => setTab("anciens")}>Anciens du club</button>
        {clubType === "mixte" && <button className={`tab ${tab === "feminin" ? "active" : ""}`} onClick={() => setTab("feminin")}>Football féminin</button>}
        {clubType === "feminin" && <button className={`tab ${tab === "ressources_pedago" ? "active" : ""}`} onClick={() => setTab("ressources_pedago")}>Ressources pédagogiques</button>}
      </div>
      {tab === "suivi" && <SuiviJeunesScreen roster={aggregatedRoster} />}
      {tab === "application" && <VerificationApplicationScreen />}
      {tab === "anciens" && <AnciensBilanScreen />}
      {tab === "feminin" && clubType === "mixte" && <FootballFemininScreen />}
      {tab === "ressources_pedago" && clubType === "feminin" && <ResourcesFeminineTab resources={femResources} persistResources={persistFemResources} />}
    </div>
  );
}

