// Même principe que le registre de signalements déjà construit pour Éthique et discipline :
// l'app n'a pas de gestion des comptes ni des accès, donc pas de vraie confidentialité possible
// techniquement. Le registre reste volontairement minimal ; le détail des faits va ailleurs.
function RegistreProtectionEnfanceTab() {
  const [entries, setEntries] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [category, setCategory] = useState("");
  const REGISTRE_STATUSES = ["Reçu", "En cours", "Transmis aux autorités", "Traité"];

  useEffect(() => { try { setEntries(JSON.parse(localStorage.getItem("tf_child_protection_log") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setEntries(next); try { localStorage.setItem("tf_child_protection_log", JSON.stringify(next)); } catch (e) {} }
  function save() {
    if (!category.trim()) { alert("Indique une catégorie très générale (pas de détail identifiant ici)."); return; }
    persist([...entries, { id: newId(), date: todayIso(), category: category.trim(), status: "Reçu" }]);
    setCategory("");
    setShowForm(false);
  }
  function setStatus(id, status) { persist(entries.map((e) => (e.id === id ? { ...e, status } : e))); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">L'app n'a pas de gestion des comptes ni des accès — n'importe qui utilisant le même appareil peut voir ce qui est enregistré ici. Garde le détail des faits ailleurs (dossier RH, papier sous clé), et utilise ce registre uniquement pour un suivi de statut très général.</p>
      {!showForm && <button className="btn btn-primary btn-small" onClick={() => setShowForm(true)} style={{ marginBottom: 16, display: "block" }}>+ Nouvelle entrée</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Catégorie très générale<input type="text" placeholder="ex. Comportement, sans plus de détail ici" value={category} onChange={(e) => setCategory(e.target.value)} autoFocus /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {entries.length === 0 && <div className="empty-state">Aucune entrée pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {[...entries].sort((a, b) => new Date(b.date) - new Date(a.date)).map((e) => (
          <div className="scouting-card" key={e.id}>
            <div className="scouting-info"><div className="scouting-name">{e.category} <span className="scouting-club">{formatDateFr(e.date)}</span></div></div>
            <select value={e.status} onChange={(ev) => setStatus(e.id, ev.target.value)}>
              {REGISTRE_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
        ))}
      </div>
    </div>
  );
}

function FormationProtectionEnfanceTab({ staff }) {
  const [trainings, setTrainings] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyChildProtectionTraining());

  useEffect(() => { try { setTrainings(JSON.parse(localStorage.getItem("tf_child_protection_trainings") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setTrainings(next); try { localStorage.setItem("tf_child_protection_trainings", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyChildProtectionTraining()); setEditingId(null); setShowForm(true); }
  function openEdit(t) { setForm(t); setEditingId(t.id); setShowForm(true); }
  function save() {
    if (!form.staffId) { alert("Choisis un membre du staff."); return; }
    if (!form.trainingName.trim()) { alert("Précise le nom de la formation."); return; }
    persist(editingId ? trainings.map((t) => (t.id === editingId ? form : t)) : [...trainings, form]);
    setForm(emptyChildProtectionTraining());
    setEditingId(null);
    setShowForm(false);
  }
  function remove(id) {
    if (!confirm("Supprimer cette formation ?")) return;
    persist(trainings.filter((t) => t.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Qui, dans le staff, a suivi une formation à la protection de l'enfance — et quand la renouveler.</p>
      {!showForm && <button className="btn btn-primary btn-small" onClick={openNew} style={{ marginBottom: 16, display: "block" }}>+ Nouvelle formation</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Membre du staff
            <select value={form.staffId} onChange={(e) => setForm((f) => ({ ...f, staffId: e.target.value }))}>
              <option value="">Choisir…</option>
              {staff.map((s) => <option key={s.id} value={s.id}>{s.firstName} {s.lastName}</option>)}
            </select>
          </label>
          <label>Formation suivie<input type="text" placeholder="ex. Sensibilisation protection de l'enfance FFF" value={form.trainingName} onChange={(e) => setForm((f) => ({ ...f, trainingName: e.target.value }))} /></label>
          <label>Date<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {trainings.length === 0 && <div className="empty-state">Aucune formation enregistrée pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {trainings.map((t) => {
          const person = staff.find((s) => s.id === t.staffId);
          return (
            <div className="scouting-card" key={t.id}>
              <div className="scouting-info">
                <div className="scouting-name">{person ? `${person.firstName} ${person.lastName}` : "Membre supprimé"} <span className="scouting-club">{t.trainingName}</span></div>
                <div className="scouting-meta">{formatDateFr(t.date)}</div>
              </div>
              <button className="btn btn-ghost btn-small" onClick={() => openEdit(t)}>Modifier</button>
              <button className="icon-btn" onClick={() => remove(t.id)} aria-label="Supprimer"><X size={14} /></button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// --- Délégué à la protection des données (RGPD) ---
function emptyProcessingActivity() { return { id: newId(), name: "", purpose: "", dataTypes: "", retention: "", legalBasis: "Intérêt légitime" }; }
const RGPD_LEGAL_BASES = ["Consentement", "Contrat", "Obligation légale", "Intérêt légitime"];
function emptyRightsRequest() { return { id: newId(), requesterName: "", requestType: "Accès", date: todayIso(), status: "Reçue", notes: "" }; }
const RGPD_REQUEST_TYPES = ["Accès", "Rectification", "Effacement", "Opposition", "Portabilité"];
const RGPD_REQUEST_STATUSES = ["Reçue", "En cours", "Traitée"];
function emptyDataBreach() { return { id: newId(), date: todayIso(), description: "", severity: "Faible", actionsTaken: "" }; }
const RGPD_BREACH_SEVERITIES = ["Faible", "Modérée", "Élevée"];

