// Même principe que l'assistant coach (Vestiaire → Assistant) : des réponses tirées des données
// déjà enregistrées dans l'app, pas d'un modèle de langage — côté administratif cette fois
// (finances, matériel, licences, RGPD, protection de l'enfance, décisions du bureau...).
// Index de navigation complet de l'onglet Administratif (les 4 pôles de Club, plus les 3 autres
// sections) — pour répondre aux questions "où trouver X", pas seulement aux questions chiffrées.
// Utile en particulier pour un bénévole qui découvre une section volumineuse.
const ADMIN_NAV_INDEX = [
  { keywords: ["informations du club", "nom du club", "type de club"], path: "Administratif → Club → Informations" },
  { keywords: ["cotisation"], path: "Administratif → Club → Cotisations" },
  { keywords: ["covoiturage"], path: "Administratif → Club → Covoiturage" },
  { keywords: ["bénévole", "créneaux bénévoles"], path: "Administratif → Club → Créneaux bénévoles" },
  { keywords: ["sauvegarde", "export", "import", "code d'accès", "pin"], path: "Administratif → Club → Sauvegarde" },
  { keywords: ["calendrier croisé"], path: "Administratif → Club → Calendrier croisé" },
  { keywords: ["événement du club", "organiser un événement"], path: "Administratif → Club → Événements" },
  { keywords: ["label", "certification"], path: "Administratif → Club → Labels" },
  { keywords: ["gouvernance", "bureau", "président", "délégation", "vote", "décision"], path: "Administratif → Club → Pôle administratif → Président / Gouvernance" },
  { keywords: ["trésorier", "budget", "dépense", "finances"], path: "Administratif → Club → Pôle administratif → Trésorier" },
  { keywords: ["secrétariat", "convocation", "courrier", "immatriculation"], path: "Administratif → Club → Pôle administratif → Secrétariat" },
  { keywords: ["licence"], path: "Administratif → Club → Pôle administratif → Responsable licences" },
  { keywords: ["matériel", "inventaire", "maintenance"], path: "Administratif → Club → Pôle administratif → Responsable matériel" },
  { keywords: ["logistique", "déplacement", "checklist"], path: "Administratif → Club → Pôle administratif → Logistique & événements" },
  { keywords: ["mission déléguée", "tâche déléguée", "dirigeant"], path: "Administratif → Club → Pôle administratif → Dirigeant" },
  { keywords: ["direction sportive", "projet sportif"], path: "Administratif → Club → Pôle sportif → Direction sportive" },
  { keywords: ["centre de formation", "filière jeunes", "formation jeunes"], path: "Administratif → Club → Pôle sportif → Directeur du centre de formation" },
  { keywords: ["diplôme", "formation éducateur", "responsable technique"], path: "Administratif → Club → Pôle sportif → Responsable technique" },
  { keywords: ["arbitre", "arbitrage"], path: "Administratif → Club → Pôle sportif → Responsable arbitrage" },
  { keywords: ["performance club"], path: "Administratif → Club → Pôle sportif → Responsable performance club" },
  { keywords: ["ressources partagées", "exercices partagés"], path: "Administratif → Club → Pôle sportif → Ressources partagées" },
  { keywords: ["multi-équipes", "surclassement", "prêt de joueur"], path: "Administratif → Club → Pôle sportif → Suivi joueurs multi-équipes" },
  { keywords: ["communication", "forum interne", "réseaux sociaux", "presse"], path: "Administratif → Club → Développement & image → Communication" },
  { keywords: ["sponsor", "billetterie", "marketing", "partenariat", "commercial"], path: "Administratif → Club → Développement & image → Commercial" },
  { keywords: ["sécurité", "éthique"], path: "Administratif → Club → Développement & image → Sécurité & éthique" },
  { keywords: ["protection de l'enfance", "protection enfant", "mineur"], path: "Administratif → Club → Développement & image → Protection de l'enfance" },
  { keywords: ["rgpd", "données personnelles", "délégué"], path: "Administratif → Club → Développement & image → Délégué à la protection des données" },
  { keywords: ["académie", "vue académie"], path: "Administratif → Vue académie" },
  { keywords: ["rapport de saison"], path: "Administratif → Rapport de saison" },
  { keywords: ["tableau de bord dirigeant"], path: "Administratif → Tableau de bord dirigeant" },
];
function findAdminNavPath(question) {
  const q = question.toLowerCase();
  const hit = ADMIN_NAV_INDEX.find((entry) => entry.keywords.some((k) => q.includes(k)));
  return hit ? hit.path : null;
}

function answerAdminAssistantQuestion(question, ctx) {
  const q = question.toLowerCase();

  // Question de navigation ("où trouver...", "où gérer...") : priorité au chemin plutôt qu'à la donnée,
  // même si le sujet correspond aussi à une réponse chiffrée plus bas.
  if (/où (?!en est|en sont)|comment accéder|comment trouver/.test(q)) {
    const path = findAdminNavPath(q);
    if (path) return `Tu trouveras ça dans : ${path}.`;
  }

  if (/cotisation|impayé|n'a pas payé|reste à payer/.test(q)) {
    const unpaid = ctx.dues.filter((d) => !d.paid);
    if (unpaid.length === 0) return "Aucune cotisation impayée pour l'instant.";
    const total = unpaid.reduce((s, d) => s + Number(d.amount || 0), 0);
    return `${unpaid.length} cotisation${unpaid.length > 1 ? "s" : ""} impayée${unpaid.length > 1 ? "s" : ""}, ${total}€ au total. Gère-les dans Administratif → Club → Cotisations.`;
  }

  if (/budget|dépense|trésorerie|finances/.test(q)) {
    const totalPrev = ctx.budgetLines.reduce((s, l) => s + Number(l.previsionnel || 0), 0);
    const totalReal = ctx.budgetLines.reduce((s, l) => s + Number(l.realise || 0), 0);
    const totalExpenses = ctx.expenses.reduce((s, e) => s + Number(e.amount || 0), 0);
    if (ctx.budgetLines.length === 0 && ctx.expenses.length === 0) return "Aucune donnée financière renseignée pour l'instant — à faire dans Administratif → Club → Pôle administratif → Trésorier.";
    return `Budget : ${totalPrev}€ prévus, ${totalReal}€ réalisés. Dépenses enregistrées : ${totalExpenses}€ au total. Détail dans Administratif → Club → Pôle administratif → Trésorier.`;
  }

  if (/échéance|expire bientôt|renouvellement|arrive bientôt/.test(q)) {
    const soon = ctx.allDeadlines.filter((d) => {
      const days = (new Date(d.dueDate) - new Date(todayIso())) / 86400000;
      return days >= 0 && days <= 30;
    });
    if (soon.length === 0) return "Aucune échéance administrative sous 30 jours, à priori.";
    return `${soon.length} échéance${soon.length > 1 ? "s" : ""} sous 30 jours : ${soon.map((d) => `${d.title} (${formatDateFr(d.dueDate)}, ${d.source})`).join(", ")}.`;
  }

  if (/matériel.*entretien|entretien.*matériel|maintenance/.test(q)) {
    const pending = ctx.maintenanceEntries.filter((e) => !e.done);
    if (pending.length === 0) return "Aucun entretien de matériel à prévoir pour l'instant.";
    return `${pending.length} entretien${pending.length > 1 ? "s" : ""} à prévoir. Détail dans Administratif → Club → Pôle administratif → Responsable matériel.`;
  }

  if (/licence/.test(q)) {
    const notValidated = ctx.roster.filter((p) => !ctx.licenseStatuses[p.id] || ctx.licenseStatuses[p.id].status !== "Validée");
    if (notValidated.length === 0) return "Toutes les licences sont validées, à priori.";
    return `${notValidated.length} licence${notValidated.length > 1 ? "s" : ""} non validée${notValidated.length > 1 ? "s" : ""} : ${notValidated.map((p) => playerFullName(p)).join(", ")}. Gère-les dans Administratif → Club → Pôle administratif → Responsable licences.`;
  }

  if (/dossier.*attente|attente.*décision/.test(q)) {
    if (ctx.pendingDossiers.length === 0) return "Aucun dossier en attente de décision pour l'instant.";
    return `${ctx.pendingDossiers.length} dossier${ctx.pendingDossiers.length > 1 ? "s" : ""} en attente : ${ctx.pendingDossiers.map((d) => `${d.title} (${d.status})`).join(", ")}. Détail dans Administratif → Club → Pôle administratif → Président / Gouvernance.`;
  }

  if (/mission|tâche déléguée|qui fait quoi/.test(q)) {
    const notDone = ctx.missions.filter((m) => m.status !== "Fait");
    if (notDone.length === 0) return "Aucune mission déléguée en cours pour l'instant.";
    return `${notDone.length} mission${notDone.length > 1 ? "s" : ""} en cours : ${notDone.map((m) => `${m.title} (${m.assignedTo || "non assignée"})`).join(", ")}. Détail dans Administratif → Club → Pôle administratif → Dirigeant.`;
  }

  if (/rgpd|donnée.*personnelle|violation.*donnée/.test(q)) {
    const pendingRequests = ctx.rgpdRequests.filter((r) => r.status !== "Traitée");
    let text = `${pendingRequests.length} demande${pendingRequests.length > 1 ? "s" : ""} RGPD en cours.`;
    if (ctx.rgpdBreaches.length > 0) text += ` ${ctx.rgpdBreaches.length} violation${ctx.rgpdBreaches.length > 1 ? "s" : ""} de données enregistrée${ctx.rgpdBreaches.length > 1 ? "s" : ""} au total.`;
    return text + " Gère ça dans Administratif → Club → Développement & image → Délégué à la protection des données.";
  }

  if (/protection.*enfance|formation.*protection|mineur/.test(q)) {
    const path = " Détail dans Administratif → Club → Développement & image → Protection de l'enfance.";
    if (ctx.childProtectionTrainings.length === 0) return "Aucune formation à la protection de l'enfance enregistrée pour l'instant." + path;
    const staffWithout = ctx.staff.filter((s) => !ctx.childProtectionTrainings.some((t) => t.staffId === s.id));
    if (staffWithout.length === 0) return `${ctx.childProtectionTrainings.length} formation${ctx.childProtectionTrainings.length > 1 ? "s" : ""} enregistrée${ctx.childProtectionTrainings.length > 1 ? "s" : ""} — tout le staff a au moins une formation à son actif.` + path;
    return `${ctx.childProtectionTrainings.length} formation${ctx.childProtectionTrainings.length > 1 ? "s" : ""} enregistrée${ctx.childProtectionTrainings.length > 1 ? "s" : ""}. Sans formation enregistrée : ${staffWithout.map((s) => `${s.firstName} ${s.lastName}`).join(", ")}.` + path;
  }

  if (/décision|bureau a décidé|dernière décision/.test(q)) {
    if (ctx.decisions.length === 0) return "Aucune décision de bureau enregistrée pour l'instant.";
    const last = [...ctx.decisions].sort((a, b) => new Date(b.date) - new Date(a.date))[0];
    return `Dernière décision : "${last.title}" (${last.type}) le ${formatDateFr(last.date)}. Historique complet dans Administratif → Club → Pôle administratif → Président / Gouvernance.`;
  }

  if (/incident.*sécurité|sécurité.*incident/.test(q)) {
    if (ctx.securityIncidents.length === 0) return "Aucun incident de sécurité enregistré pour l'instant.";
    const recent = [...ctx.securityIncidents].sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 3);
    return `${ctx.securityIncidents.length} incident${ctx.securityIncidents.length > 1 ? "s" : ""} au total. Les plus récents : ${recent.map((i) => `${i.type} (${formatDateFr(i.date)})`).join(", ")}. Détail dans Administratif → Club → Développement & image → Sécurité & éthique.`;
  }

  if (/staff|éducateur|membre/.test(q)) {
    if (ctx.staff.length === 0) return "Aucun membre du staff enregistré pour l'instant.";
    return `${ctx.staff.length} membre${ctx.staff.length > 1 ? "s" : ""} du staff enregistré${ctx.staff.length > 1 ? "s" : ""}.`;
  }

  const fallbackPath = findAdminNavPath(q);
  if (fallbackPath) return `Je n'ai pas de réponse chiffrée toute faite pour ça, mais tu trouveras ce sujet dans : ${fallbackPath}.`;

  return "Je ne sais pas encore répondre à ce type de question — j'ai reconnu aucun sujet précis (cotisations, budget, échéances, matériel, licences, dossiers en attente, missions déléguées, RGPD, protection de l'enfance, décisions du bureau, incidents de sécurité, staff). Essaie une des suggestions ci-dessous, ou reformule.";
}

function AdminAssistantScreen() {
  const [input, setInput] = useState("");
  const [history, setHistory] = useState([]);
  const [ctx, setCtx] = useState(null);

  useEffect(() => {
    let dues = [], budgetLines = [], expenses = [], maintenanceEntries = [], licenseStatuses = {}, pendingDossiers = [], missions = [], rgpdRequests = [], rgpdBreaches = [], childProtectionTrainings = [], decisions = [], securityIncidents = [], staff = [], roster = [];
    try { dues = JSON.parse(localStorage.getItem("tf_club_dues") || "[]"); } catch (e) {}
    try { budgetLines = JSON.parse(localStorage.getItem("tf_budget_lines") || "[]"); } catch (e) {}
    try { expenses = JSON.parse(localStorage.getItem("tf_club_expenses") || "[]"); } catch (e) {}
    try { maintenanceEntries = JSON.parse(localStorage.getItem("tf_equipment_maintenance") || "[]"); } catch (e) {}
    try { licenseStatuses = JSON.parse(localStorage.getItem("tf_license_statuses") || "{}"); } catch (e) {}
    try { pendingDossiers = JSON.parse(localStorage.getItem("tf_pending_dossiers") || "[]"); } catch (e) {}
    try { missions = JSON.parse(localStorage.getItem("tf_dirigeant_missions") || "[]"); } catch (e) {}
    try { rgpdRequests = JSON.parse(localStorage.getItem("tf_rgpd_rights_requests") || "[]"); } catch (e) {}
    try { rgpdBreaches = JSON.parse(localStorage.getItem("tf_rgpd_breaches") || "[]"); } catch (e) {}
    try { childProtectionTrainings = JSON.parse(localStorage.getItem("tf_child_protection_trainings") || "[]"); } catch (e) {}
    try { decisions = JSON.parse(localStorage.getItem("tf_governance_decisions") || "[]"); } catch (e) {}
    try { securityIncidents = JSON.parse(localStorage.getItem("tf_security_incidents") || "[]"); } catch (e) {}
    try { staff = JSON.parse(window.localStorage.getItem("tf_club_staff") || "[]"); } catch (e) {}
    try { roster = JSON.parse(localStorage.getItem("tf_roster") || "[]"); } catch (e) {}

    const allDeadlines = [];
    try { JSON.parse(localStorage.getItem("tf_statutory_obligations") || "[]").forEach((o) => allDeadlines.push({ title: o.title, dueDate: o.dueDate, source: "Gouvernance" })); } catch (e) {}
    try { JSON.parse(localStorage.getItem("tf_financial_deadlines") || "[]").forEach((d) => allDeadlines.push({ title: d.title, dueDate: d.dueDate, source: "Trésorerie" })); } catch (e) {}
    try { JSON.parse(localStorage.getItem("tf_federal_deadlines") || "[]").forEach((d) => allDeadlines.push({ title: d.title, dueDate: d.dueDate, source: "Licences" })); } catch (e) {}
    try { JSON.parse(localStorage.getItem("tf_insurance_policies") || "[]").forEach((p) => allDeadlines.push({ title: `Renouvellement — ${p.type}`, dueDate: p.renewalDate, source: "Assurances" })); } catch (e) {}

    try { setHistory(JSON.parse(localStorage.getItem("tf_admin_assistant_history") || "[]")); } catch (e) {}
    setCtx({ dues, budgetLines, expenses, maintenanceEntries, licenseStatuses, pendingDossiers, missions, rgpdRequests, rgpdBreaches, childProtectionTrainings, decisions, securityIncidents, staff, roster, allDeadlines });
  }, []);

  function persistHistory(next) {
    setHistory(next);
    try { localStorage.setItem("tf_admin_assistant_history", JSON.stringify(next)); } catch (e) {}
  }
  function ask(question) {
    if (!question.trim() || !ctx) return;
    const answer = answerAdminAssistantQuestion(question, ctx);
    persistHistory([...history, { id: newId(), question: question.trim(), answer, at: Date.now() }]);
    setInput("");
  }
  function clearHistory() {
    if (!confirm("Effacer tout l'historique de conversation avec l'assistant administratif ?")) return;
    persistHistory([]);
  }

  const SUGGESTIONS = ["Cotisations impayées ?", "Où en est le budget ?", "Échéances à venir ?", "Matériel à entretenir ?", "Licences en attente ?", "Dossiers en attente ?", "Missions déléguées en cours ?", "Demandes RGPD en cours ?", "Formations protection de l'enfance à jour ?", "Dernière décision du bureau ?", "Où gérer les sponsors ?", "Où déclarer un incident de sécurité ?", "Où trouver la filière jeunes ?"];

  return (
    <div className="stats-screen">
      <div className="stats-screen-header">
        <div className="eyebrow">Administratif</div>
        <h1>Assistant administratif</h1>
      </div>
      <p className="radar-note">Un assistant sur le même principe que celui du Vestiaire — les réponses viennent de tes données déjà enregistrées dans l'app (cotisations, budget, échéances, matériel, licences, RGPD, protection de l'enfance...), pas d'un modèle de langage.</p>
      <div className="new-match-card" style={{ marginBottom: 16 }}>
        <label>Pose une question<input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") ask(input); }} placeholder="ex. Cotisations impayées ?" /></label>
        <button className="btn btn-primary btn-small" onClick={() => ask(input)} style={{ marginTop: 8 }}>Demander</button>
      </div>
      <div className="qcm-options" style={{ marginBottom: 16 }}>
        {SUGGESTIONS.map((s) => <button key={s} className="qcm-option" onClick={() => ask(s)}>{s}</button>)}
      </div>
      {history.length > 0 && <button className="btn btn-ghost btn-small" onClick={clearHistory} style={{ marginBottom: 12 }}>Effacer l'historique</button>}
      <div className="scouting-list">
        {[...history].reverse().map((h) => (
          <div className="scouting-card" key={h.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
            <div className="scouting-name">{h.question}</div>
            <div className="scouting-meta" style={{ marginTop: 4 }}>{h.answer}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

