function ModelesCourriersTab() {
  const [templates, setTemplates] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyLetterTemplate());
  const [viewing, setViewing] = useState(null);

  useEffect(() => { try { setTemplates(JSON.parse(localStorage.getItem("tf_letter_templates") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setTemplates(next); try { localStorage.setItem("tf_letter_templates", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyLetterTemplate()); setEditingId(null); setShowForm(true); }
  function openEdit(t) { setForm(t); setEditingId(t.id); setShowForm(true); setViewing(null); }
  function save() {
    if (!form.title.trim()) { alert("Donne un titre à ce modèle."); return; }
    persist(editingId ? templates.map((t) => (t.id === editingId ? form : t)) : [...templates, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyLetterTemplate());
  }
  function remove(id) { if (!confirm("Supprimer ce modèle de courrier ?")) return; persist(templates.filter((t) => t.id !== id)); }
  function copyToClipboard(content) { try { navigator.clipboard.writeText(content); } catch (e) {} }
  function populateLetterStarters() {
    const existingTitles = new Set(templates.map((t) => t.title));
    const toAdd = STARTER_LETTER_TEMPLATES.filter((t) => !existingTitles.has(t.title)).map((t) => ({ id: newId(), ...t }));
    if (toAdd.length === 0) { alert("Les modèles de départ sont déjà tous présents."); return; }
    persist([...templates, ...toAdd]);
    alert(`${toAdd.length} modèle${toAdd.length > 1 ? "s" : ""} ajouté${toAdd.length > 1 ? "s" : ""}.`);
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  if (showForm) {
    return (
      <div className="new-match-card" style={{ marginBottom: 16 }}>
        <label>Titre<input type="text" placeholder="ex. Convocation assemblée générale" value={form.title} onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))} autoFocus /></label>
        <label>Contenu<textarea rows={6} value={form.content} onChange={(e) => setForm((f) => ({ ...f, content: e.target.value }))} /></label>
        <div className="form-actions">
          <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
          <button className="btn btn-primary" onClick={save}>Enregistrer</button>
        </div>
      </div>
    );
  }

  if (viewing) {
    return (
      <div>
        <button className="btn btn-ghost btn-small" onClick={() => setViewing(null)} style={{ marginBottom: 14 }}>‹ Retour</button>
        <div className="panel-heading" style={{ marginTop: 0 }}>{viewing.title}</div>
        <div style={{ whiteSpace: "pre-wrap" }} className="new-match-card">{viewing.content}</div>
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <button className="btn btn-primary btn-small" onClick={() => copyToClipboard(viewing.content)}>Copier</button>
          <button className="btn btn-ghost btn-small" onClick={() => openEdit(viewing)}>Modifier</button>
        </div>
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Des modèles de courriers et documents administratifs types.</p>
      {templates.length === 0 && <button className="btn btn-ghost btn-small" onClick={populateLetterStarters} style={{ marginBottom: 14 }}>Importer les modèles de départ (10)</button>}
      <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouveau modèle</button>
      {templates.length === 0 && <div className="empty-state">Aucun modèle pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
      <div className="scouting-list">
        {templates.map((t) => (
          <div className="scouting-card" key={t.id} onClick={() => setViewing(t)} style={{ cursor: "pointer" }}>
            <div className="scouting-info"><div className="scouting-name">{t.title}</div></div>
            <button className="icon-btn" onClick={(e) => { e.stopPropagation(); remove(t.id); }} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function SuiviCourrierTab() {
  const [entries, setEntries] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyMailLogEntry());

  useEffect(() => { try { setEntries(JSON.parse(localStorage.getItem("tf_mail_log") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setEntries(next); try { localStorage.setItem("tf_mail_log", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyMailLogEntry()); setEditingId(null); setShowForm(true); }
  function openEdit(e) { setForm(e); setEditingId(e.id); setShowForm(true); }
  function save() {
    if (!form.subject.trim()) { alert("Décris l'objet du courrier."); return; }
    persist(editingId ? entries.map((e) => (e.id === editingId ? form : e)) : [...entries, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyMailLogEntry());
  }
  function remove(id) { if (!confirm("Supprimer ce courrier ?")) return; persist(entries.filter((e) => e.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Le suivi du courrier entrant et sortant du club.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle entrée</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Sens
            <select value={form.direction} onChange={(e) => setForm((f) => ({ ...f, direction: e.target.value }))}>
              <option value="entrant">Entrant</option>
              <option value="sortant">Sortant</option>
            </select>
          </label>
          <label>Objet<input type="text" value={form.subject} onChange={(e) => setForm((f) => ({ ...f, subject: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>{form.direction === "entrant" ? "De" : "À"}<input type="text" value={form.from} onChange={(e) => setForm((f) => ({ ...f, from: e.target.value }))} /></label>
            <label>Date<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
          </div>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {entries.length === 0 && <div className="empty-state">Aucune entrée pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {[...entries].sort((a, b) => new Date(b.date) - new Date(a.date)).map((e) => (
          <div className="scouting-card" key={e.id}>
            <div className="scouting-info">
              <div className="scouting-name">{e.subject} <span className="scouting-club">{e.direction === "entrant" ? "Entrant" : "Sortant"}</span></div>
              <div className="scouting-meta">{e.from} · {formatDateFr(e.date)}</div>
            </div>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(e)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(e.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

// Agrège les échéances déjà éparpillées entre plusieurs écrans (Gouvernance, Trésorerie,
// Correspondant Footclubs) en une vue unique — plutôt que d'ouvrir un quatrième registre distinct.
function AgendaAdministratifTab() {
  const [items, setItems] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const all = [];
    try { JSON.parse(localStorage.getItem("tf_statutory_obligations") || "[]").forEach((o) => all.push({ title: o.title, dueDate: o.dueDate, source: "Gouvernance" })); } catch (e) {}
    try { JSON.parse(localStorage.getItem("tf_financial_deadlines") || "[]").forEach((d) => all.push({ title: d.title, dueDate: d.dueDate, source: "Trésorerie" })); } catch (e) {}
    try { JSON.parse(localStorage.getItem("tf_federal_deadlines") || "[]").forEach((d) => all.push({ title: d.title, dueDate: d.dueDate, source: "Licences" })); } catch (e) {}
    try { JSON.parse(localStorage.getItem("tf_insurance_policies") || "[]").forEach((p) => all.push({ title: `Renouvellement — ${p.type}`, dueDate: p.renewalDate, source: "Assurances" })); } catch (e) {}
    setItems(all.filter((i) => i.dueDate >= todayIso()).sort((a, b) => new Date(a.dueDate) - new Date(b.dueDate)));
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Toutes les échéances à venir déjà enregistrées ailleurs dans l'app (gouvernance, trésorerie, licences, assurances), réunies en une seule vue.</p>
      {items.length === 0 && <div className="empty-state">Aucune échéance à venir pour l'instant.</div>}
      <div className="scouting-list">
        {items.map((i, idx) => (
          <div className="scouting-card" key={idx}>
            <div className="scouting-info">
              <div className="scouting-name">{i.title} <span className="scouting-club">{formatDateFr(i.dueDate)}</span></div>
              <div className="scouting-meta">{i.source}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

