function AssurancesTab() {
  const [policies, setPolicies] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyInsurancePolicy());

  useEffect(() => { try { setPolicies(JSON.parse(localStorage.getItem("tf_insurance_policies") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setPolicies(next); try { localStorage.setItem("tf_insurance_policies", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyInsurancePolicy()); setEditingId(null); setShowForm(true); }
  function openEdit(p) { setForm(p); setEditingId(p.id); setShowForm(true); }
  function save() {
    if (!form.type.trim()) { alert("Précise le type d'assurance."); return; }
    persist(editingId ? policies.map((p) => (p.id === editingId ? form : p)) : [...policies, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyInsurancePolicy());
  }
  function remove(id) { if (!confirm("Supprimer cette assurance ?")) return; persist(policies.filter((p) => p.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;
  const renewalsSoon = policies.filter((p) => isInsuranceRenewalSoon(p.renewalDate));

  return (
    <div>
      <p className="radar-note">Les assurances du club — responsabilité civile, dommages, individuelle accident.</p>
      {renewalsSoon.length > 0 && (
        <div className="empty-state" style={{ borderColor: "var(--crimson)", marginBottom: 16 }}>
          {renewalsSoon.length} contrat{renewalsSoon.length > 1 ? "s" : ""} à renouveler sous 60 jours.
        </div>
      )}
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouveau contrat</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Type<input type="text" placeholder="ex. Responsabilité civile" value={form.type} onChange={(e) => setForm((f) => ({ ...f, type: e.target.value }))} autoFocus /></label>
          <div className="roster-physical-grid">
            <label>Assureur<input type="text" value={form.provider} onChange={(e) => setForm((f) => ({ ...f, provider: e.target.value }))} /></label>
            <label>Renouvellement<input type="date" value={form.renewalDate} onChange={(e) => setForm((f) => ({ ...f, renewalDate: e.target.value }))} /></label>
          </div>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {policies.length === 0 && <div className="empty-state">Aucun contrat pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
      <div className="scouting-list">
        {policies.map((p) => (
          <div className="scouting-card" key={p.id}>
            <div className="scouting-info">
              <div className="scouting-name">{p.type} <span className="scouting-club">{p.provider}</span></div>
              <div className="scouting-meta" style={isInsuranceRenewalSoon(p.renewalDate) ? { color: "var(--crimson)" } : undefined}>Renouvellement : {formatDateFr(p.renewalDate)}</div>
            </div>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(p)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(p.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function BudgetPluriannuelTab() {
  const [lines, setLines] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyMultiYearBudgetLine());

  useEffect(() => { try { setLines(JSON.parse(localStorage.getItem("tf_multiyear_budget") || "[]")); } catch (e) {} setLoaded(true); }, []);
  function persist(next) { setLines(next); try { localStorage.setItem("tf_multiyear_budget", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyMultiYearBudgetLine()); setEditingId(null); setShowForm(true); }
  function openEdit(l) { setForm(l); setEditingId(l.id); setShowForm(true); }
  function save() {
    if (!form.year) { alert("Précise l'année."); return; }
    persist(editingId ? lines.map((l) => (l.id === editingId ? form : l)) : [...lines, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyMultiYearBudgetLine());
  }
  function remove(id) { if (!confirm("Supprimer cette ligne budgétaire ?")) return; persist(lines.filter((l) => l.id !== id)); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;
  const years = [...new Set(lines.map((l) => l.year))].sort((a, b) => a - b);
  const byYear = years.map((y) => ({ year: y, total: lines.filter((l) => l.year === y).reduce((s, l) => s + Number(l.amount || 0), 0) }));

  return (
    <div>
      <p className="radar-note">Un prévisionnel budgétaire simple sur plusieurs années — étend la vue Trésorerie (limitée à l'année en cours) dans le temps.</p>
      {byYear.length > 0 && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          {byYear.map((y) => <p key={y.year} style={{ margin: "4px 0" }}>{y.year} : {y.total}€</p>)}
        </div>
      )}
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle ligne</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Catégorie
            <select value={form.category} onChange={(e) => setForm((f) => ({ ...f, category: e.target.value }))}>
              {BUDGET_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </label>
          <div className="roster-physical-grid">
            <label>Année<input type="number" value={form.year} onChange={(e) => setForm((f) => ({ ...f, year: Number(e.target.value) }))} /></label>
            <label>Montant (€)<input type="number" min="0" step="0.01" value={form.amount} onChange={(e) => setForm((f) => ({ ...f, amount: Number(e.target.value) }))} /></label>
          </div>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {lines.length === 0 && <div className="empty-state">Aucune ligne pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {lines.map((l) => (
          <div className="scouting-card" key={l.id}>
            <div className="scouting-info">
              <div className="scouting-name">{l.category} <span className="scouting-club">{l.year}</span></div>
              <div className="scouting-meta">{l.amount}€</div>
            </div>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(l)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(l.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

