function VuePluriannuelleTab() {
  const [seasons, setSeasons] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [records, setRecords] = useState([]);

  useEffect(() => {
    try {
      const allSeasons = JSON.parse(localStorage.getItem("tf_seasons") || "[]");
      setSeasons(allSeasons);
      const teamId = getActiveTeamId();
      const results = allSeasons.map((s) => {
        let wins = 0, draws = 0, losses = 0, goalsFor = 0, goalsAgainst = 0;
        try {
          const index = JSON.parse(readScopedKeyFor(MATCHES_INDEX_KEY, teamId, s.id) || "[]");
          const full = index.map((m) => readMatchFromCache(m.id)).filter((m) => m && m.closed);
          full.forEach((m) => {
            const gf = m.tags.filter((t) => t.eventKey === "but" && t.team === "us").length;
            const ga = m.tags.filter((t) => t.eventKey === "but" && t.team === "opp").length;
            goalsFor += gf; goalsAgainst += ga;
            if (gf > ga) wins++; else if (gf < ga) losses++; else draws++;
          });
        } catch (e) {}
        return { season: s, wins, draws, losses, goalsFor, goalsAgainst, played: wins + draws + losses };
      });
      setRecords(results);
    } catch (e) {}
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Le bilan sportif de chaque saison, comparé dans le temps — pour juger la progression du club au-delà de l'instantané d'une seule saison.</p>
      {records.length === 0 && <div className="empty-state">Aucune saison enregistrée pour l'instant.</div>}
      <div className="scouting-list">
        {records.map((r) => (
          <div className="scouting-card" key={r.season.id}>
            <div className="scouting-info">
              <div className="scouting-name">{r.season.name || r.season.id}</div>
              <div className="scouting-meta">{r.played} match{r.played !== 1 ? "s" : ""} — {r.wins}V {r.draws}N {r.losses}D · {r.goalsFor} buts marqués, {r.goalsAgainst} encaissés</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

