function EffortParPosteTab() {
  const [scouted, setScouted] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setScouted(JSON.parse(localStorage.getItem("tf_scouting") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const positions = [...new Set(scouted.map((p) => p.position).filter(Boolean))];
  const byPosition = positions.map((pos) => ({ position: pos, count: scouted.filter((p) => p.position === pos).length })).sort((a, b) => b.count - a.count);
  const maxCount = Math.max(1, ...byPosition.map((b) => b.count));

  return (
    <div>
      <p className="radar-note">Où sont concentrées tes ressources de scouting, poste par poste — pour repérer d'un coup d'œil les angles morts.</p>
      {byPosition.length === 0 && <div className="empty-state">Aucun joueur suivi pour l'instant — ajoutes-en depuis Analyse et vidéo → Scouting.</div>}
      <div className="scouting-list">
        {byPosition.map((b) => (
          <div className="scouting-card" key={b.position}>
            <div className="scouting-info">
              <div className="scouting-name">{b.position} <span className="scouting-club">{b.count} joueur{b.count !== 1 ? "s" : ""} suivi{b.count !== 1 ? "s" : ""}</span></div>
              <div style={{ background: "rgba(255,255,255,0.1)", borderRadius: 4, height: 6, marginTop: 6 }}>
                <div style={{ background: "var(--gold)", borderRadius: 4, height: 6, width: `${(b.count / maxCount) * 100}%` }} />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function BudgetRecrutementTab() {
  const [expenses, setExpenses] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyScoutingExpense());

  useEffect(() => {
    try { setExpenses(JSON.parse(localStorage.getItem("tf_scouting_expenses") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) { setExpenses(next); try { localStorage.setItem("tf_scouting_expenses", JSON.stringify(next)); } catch (e) {} }
  function openNew() { setForm(emptyScoutingExpense()); setEditingId(null); setShowForm(true); }
  function openEdit(e) { setForm(e); setEditingId(e.id); setShowForm(true); }
  function save() {
    if (!form.description.trim()) { alert("Décris cette dépense."); return; }
    if (!form.amount || form.amount <= 0) { alert("Indique un montant supérieur à 0."); return; }
    persist(editingId ? expenses.map((e) => (e.id === editingId ? form : e)) : [...expenses, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyScoutingExpense());
  }
  function remove(id) {
    if (!confirm("Supprimer cette ligne budgétaire ?")) return;
    persist(expenses.filter((e) => e.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const total = expenses.reduce((s, e) => s + Number(e.amount || 0), 0);
  const byCategory = SCOUTING_EXPENSE_CATEGORIES.map((c) => ({ category: c, total: expenses.filter((e) => e.category === c).reduce((s, e) => s + Number(e.amount || 0), 0) }));

  return (
    <div>
      <p className="radar-note">Frais de déplacement scouting, indemnités — {total}€ au total.</p>
      <div className="new-match-card" style={{ marginBottom: 16 }}>
        {byCategory.map((b) => <p key={b.category} style={{ margin: "4px 0" }}>{b.category} : {b.total}€</p>)}
      </div>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvelle dépense</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Catégorie
            <select value={form.category} onChange={(e) => setForm((f) => ({ ...f, category: e.target.value }))}>
              {SCOUTING_EXPENSE_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </label>
          <div className="roster-physical-grid">
            <label>Montant (€)<input type="number" min="0" step="0.01" value={form.amount} onChange={(e) => setForm((f) => ({ ...f, amount: Number(e.target.value) }))} /></label>
            <label>Date<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
          </div>
          <label>Description<input type="text" placeholder="ex. Déplacement match vs Nice" value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {expenses.length === 0 && <div className="empty-state">Aucune dépense pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
      <div className="scouting-list">
        {[...expenses].sort((a, b) => new Date(b.date) - new Date(a.date)).map((e) => (
          <div className="scouting-card" key={e.id}>
            <div className="scouting-info">
              <div className="scouting-name">{e.description} <span className="scouting-club">{e.amount}€</span></div>
              <div className="scouting-meta">{e.category} · {formatDateFr(e.date)}</div>
            </div>
            <button className="btn btn-ghost btn-small" onClick={() => openEdit(e)}>Modifier</button>
            <button className="icon-btn" onClick={() => remove(e.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function BilanPluriannuelTab() {
  const [roster, setRoster] = useState([]);
  const [assessments, setAssessments] = useState({});
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setRoster(JSON.parse(localStorage.getItem("tf_roster") || "[]")); } catch (e) {}
    try { setAssessments(JSON.parse(localStorage.getItem("tf_recruit_assessments") || "{}")); } catch (e) {}
    setLoaded(true);
  }, []);

  function setAssessment(playerId, value) {
    const next = { ...assessments, [playerId]: value };
    setAssessments(next);
    try { localStorage.setItem("tf_recruit_assessments", JSON.stringify(next)); } catch (e) {}
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const recruits = roster.filter((p) => p.recruitedFromScoutingId).sort((a, b) => new Date(b.recruitedDate) - new Date(a.recruitedDate));
  const assessed = recruits.filter((p) => assessments[p.id] && assessments[p.id] !== "Trop tôt pour juger");
  const successCount = assessed.filter((p) => assessments[p.id] === "Réussi").length;

  return (
    <div>
      <p className="radar-note">Les joueurs recrutés depuis le scouting, avec leur ancienneté au club — se construit à partir de maintenant, puisque le lien vers l'origine scouting n'était pas conservé auparavant pour les recrutements déjà faits.</p>
      {assessed.length > 0 && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <p style={{ margin: 0 }}>{successCount}/{assessed.length} recrue{assessed.length !== 1 ? "s" : ""} évaluée{assessed.length !== 1 ? "s" : ""} jugée{successCount !== 1 ? "s" : ""} "Réussi" ({Math.round((successCount / assessed.length) * 100)}%).</p>
        </div>
      )}
      {recruits.length === 0 && <div className="empty-state">Aucun recrutement suivi depuis le scouting pour l'instant.</div>}
      <div className="scouting-list">
        {recruits.map((p) => {
          const monthsAgo = Math.floor((new Date(todayIso()) - new Date(p.recruitedDate)) / (30 * 86400000));
          return (
            <div className="scouting-card" key={p.id}>
              <div className="scouting-info">
                <div className="scouting-name">{playerFullName(p)} <span className="scouting-club">{monthsAgo} mois</span></div>
                <div className="scouting-meta">Ancien club : {p.recruitedFromClub || "non renseigné"}</div>
              </div>
              <select value={assessments[p.id] || "Trop tôt pour juger"} onChange={(e) => setAssessment(p.id, e.target.value)}>
                {RECRUIT_ASSESSMENTS.map((a) => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
          );
        })}
      </div>
    </div>
  );
}

