function ReseauContactsTab() {
  const [contacts, setContacts] = useState([]);
  const [exchanges, setExchanges] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyScoutingContact());
  const [openContactId, setOpenContactId] = useState(null);
  const [exchangeText, setExchangeText] = useState("");

  useEffect(() => {
    try { setContacts(JSON.parse(localStorage.getItem("tf_scouting_contacts") || "[]")); } catch (e) {}
    try { setExchanges(JSON.parse(localStorage.getItem("tf_scouting_exchanges") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persistContacts(next) { setContacts(next); try { localStorage.setItem("tf_scouting_contacts", JSON.stringify(next)); } catch (e) {} }
  function persistExchanges(next) { setExchanges(next); try { localStorage.setItem("tf_scouting_exchanges", JSON.stringify(next)); } catch (e) {} }

  function openNew() { setForm(emptyScoutingContact()); setEditingId(null); setShowForm(true); }
  function openEdit(c) { setForm(c); setEditingId(c.id); setShowForm(true); }
  function save() {
    if (!form.name.trim()) { alert("Donne un nom à ce contact."); return; }
    persistContacts(editingId ? contacts.map((c) => (c.id === editingId ? form : c)) : [...contacts, form]);
    setShowForm(false);
    setEditingId(null);
    setForm(emptyScoutingContact());
  }
  function removeContact(id) {
    if (!confirm("Supprimer ce contact et son historique d'échanges ?")) return;
    persistContacts(contacts.filter((c) => c.id !== id));
    persistExchanges(exchanges.filter((e) => e.contactId !== id));
    if (openContactId === id) setOpenContactId(null);
  }
  function addExchange() {
    if (!exchangeText.trim()) { alert("Décris l'échange avant de l'ajouter."); return; }
    persistExchanges([...exchanges, { ...emptyContactExchange(openContactId), content: exchangeText.trim() }]);
    setExchangeText("");
  }
  function removeExchange(id) {
    if (!confirm("Supprimer cet échange ?")) return;
    persistExchanges(exchanges.filter((e) => e.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  if (openContactId) {
    const contact = contacts.find((c) => c.id === openContactId);
    if (!contact) { setOpenContactId(null); return null; }
    const contactExchanges = exchanges.filter((e) => e.contactId === openContactId).sort((a, b) => new Date(b.date) - new Date(a.date));
    return (
      <div>
        <button className="btn btn-ghost btn-small" onClick={() => setOpenContactId(null)} style={{ marginBottom: 14 }}>‹ Retour</button>
        <div className="panel-heading" style={{ marginTop: 0 }}>{contact.name}</div>
        <p className="hint" style={{ marginTop: 0 }}>{contact.role}{contact.phone ? ` · ${contact.phone}` : ""}{contact.email ? ` · ${contact.email}` : ""}</p>
        {!showForm && <button className="btn btn-ghost btn-small" onClick={() => openEdit(contact)} style={{ marginBottom: 16 }}>Modifier ce contact</button>}
        {showForm && (
          <div className="new-match-card" style={{ marginBottom: 16 }}>
            <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
            <label>Rôle
              <select value={form.role} onChange={(e) => setForm((f) => ({ ...f, role: e.target.value }))}>
                {SCOUTING_CONTACT_ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
              </select>
            </label>
            <div className="roster-physical-grid">
              <label>Téléphone<input type="text" value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></label>
              <label>Email<input type="text" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></label>
            </div>
            <div className="form-actions">
              <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
              <button className="btn btn-primary" onClick={save}>Enregistrer</button>
            </div>
          </div>
        )}
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Nouvel échange<textarea rows={2} value={exchangeText} onChange={(e) => setExchangeText(e.target.value)} /></label>
          <button className="btn btn-primary btn-small" onClick={addExchange} style={{ marginTop: 8 }}>Ajouter</button>
        </div>
        {contactExchanges.length === 0 && <div className="empty-state">Aucun échange enregistré pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
        <div className="scouting-list">
          {contactExchanges.map((e) => (
            <div className="scouting-card" key={e.id}>
              <div className="scouting-info">
                <div className="scouting-name">{formatDateFr(e.date)}</div>
                <div className="scouting-meta">{e.content}</div>
              </div>
              <button className="icon-btn" onClick={() => removeExchange(e.id)} aria-label="Supprimer"><X size={14} /></button>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Un réseau de contacts scouting — agents, autres recruteurs — avec l'historique des échanges.</p>
      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouveau contact</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
          <label>Rôle
            <select value={form.role} onChange={(e) => setForm((f) => ({ ...f, role: e.target.value }))}>
              {SCOUTING_CONTACT_ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
            </select>
          </label>
          <div className="roster-physical-grid">
            <label>Téléphone<input type="text" value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></label>
            <label>Email<input type="text" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></label>
          </div>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}
      {contacts.length === 0 && <div className="empty-state">Aucun contact pour l'instant. Utilise le bouton ci-dessus pour en ajouter un.</div>}
      <div className="scouting-list">
        {contacts.map((c) => {
          const count = exchanges.filter((e) => e.contactId === c.id).length;
          return (
            <div className="scouting-card" key={c.id} onClick={() => setOpenContactId(c.id)} style={{ cursor: "pointer" }}>
              <div className="scouting-info">
                <div className="scouting-name">{c.name} <span className="scouting-club">{c.role}</span></div>
                <div className="scouting-meta">{count} échange{count !== 1 ? "s" : ""}</div>
              </div>
              <button className="icon-btn" onClick={(e) => { e.stopPropagation(); removeContact(c.id); }} aria-label="Supprimer"><X size={14} /></button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

