function EngagementTab({ roster, engagement, persistEngagement }) {
  const [selectedId, setSelectedId] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(null);

  function openNew() { setForm(emptyEngagementEntry(selectedId)); setEditingId(null); setShowForm(true); }
  function openEdit(e) { setForm(e); setEditingId(e.id); setShowForm(true); }
  function save() {
    if (!selectedId) { alert("Choisis un joueur."); return; }
    persistEngagement(editingId ? engagement.map((e) => (e.id === editingId ? { ...form, playerId: selectedId } : e)) : [...engagement, { ...form, playerId: selectedId }]);
    setShowForm(false);
    setEditingId(null);
  }
  function remove(id) {
    if (!confirm("Supprimer cette entrée ?")) return;
    persistEngagement(engagement.filter((e) => e.id !== id));
  }

  const playerEntries = selectedId ? engagement.filter((e) => e.playerId === selectedId).sort((a, b) => new Date(b.date) - new Date(a.date)) : [];
  const ENJOYMENT_LABELS = { 1: "Ne s'amuse pas", 2: "Mitigé", 3: "Content", 4: "Très content", 5: "Adore ça" };

  return (
    <div>
      <p className="radar-note">Le plaisir de jouer et l'engagement du jeune — pas sa performance. Un indicateur qualitatif simple, à suivre dans le temps.</p>
      <label style={{ display: "inline-block", marginBottom: 16 }}>
        Joueur
        <select value={selectedId} onChange={(e) => setSelectedId(e.target.value)} style={{ display: "block", marginTop: 4 }}>
          <option value="">Choisir…</option>
          {roster.map((p) => <option key={p.id} value={p.id}>{playerFullName(p)}</option>)}
        </select>
      </label>
      {selectedId && (
        <>
          {!showForm && <button className="btn btn-primary btn-small" onClick={openNew} style={{ marginBottom: 16, display: "block" }}>+ Nouvelle observation</button>}
          {showForm && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <div className="radar-range-label">Niveau de plaisir observé</div>
              <div className="qcm-options">
                {[1, 2, 3, 4, 5].map((n) => (
                  <button key={n} type="button" className={`qcm-option ${form.enjoymentLevel === n ? "selected" : ""}`} onClick={() => setForm((f) => ({ ...f, enjoymentLevel: n }))}>{ENJOYMENT_LABELS[n]}</button>
                ))}
              </div>
              <label>Note (optionnel)<textarea rows={2} value={form.note} onChange={(e) => setForm((f) => ({ ...f, note: e.target.value }))} /></label>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => { setShowForm(false); setEditingId(null); }}>Annuler</button>
                <button className="btn btn-primary" onClick={save}>Enregistrer</button>
              </div>
            </div>
          )}
          {playerEntries.length === 0 && <div className="empty-state">Aucune observation pour l'instant. Utilise le bouton ci-dessus pour en ajouter une.</div>}
          <div className="scouting-list">
            {playerEntries.map((e) => (
              <div className="scouting-card" key={e.id}>
                <div className="scouting-info">
                  <div className="scouting-name">{ENJOYMENT_LABELS[e.enjoymentLevel]} <span className="scouting-club">{formatDateFr(e.date)}</span></div>
                  {e.note && <div className="scouting-meta">{e.note}</div>}
                </div>
                <button className="btn btn-ghost btn-small" onClick={() => openEdit(e)}>Modifier</button>
                <button className="icon-btn" onClick={() => remove(e.id)} aria-label="Supprimer"><X size={14} /></button>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function PhilosophieParentsTab({ teams, philosophies, persistPhilosophies }) {
  const [selectedCategory, setSelectedCategory] = useState("");
  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];
  const current = philosophies.find((p) => p.category === selectedCategory);

  function updateText(text) {
    if (current) {
      persistPhilosophies(philosophies.map((p) => (p.category === selectedCategory ? { ...p, philosophyText: text } : p)));
    } else {
      persistPhilosophies([...philosophies, { ...emptyParentPhilosophy(selectedCategory), philosophyText: text }]);
    }
  }

  return (
    <div className="match-report" style={{ maxWidth: 700, margin: "0 auto" }}>
      <p className="radar-note no-print">Explique aux parents pourquoi tu abordes le jeu comme ça à cet âge — pourquoi pas de classement en U9, pourquoi la polyvalence des postes, etc. Un texte que tu peux imprimer et distribuer.</p>
      <label className="no-print" style={{ display: "inline-block", marginBottom: 16 }}>
        Catégorie
        <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} style={{ display: "block", marginTop: 4 }}>
          <option value="">Choisir…</option>
          {knownCategories.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
      </label>
      {selectedCategory && (
        <>
          <button className="btn btn-ghost btn-small no-print" onClick={() => window.print()} style={{ marginBottom: 12, display: "block" }}><Download size={13} /> Exporter en PDF</button>
          <div className="match-report-header">
            <div className="match-report-title">Notre approche en {selectedCategory}</div>
          </div>
          <textarea className="no-print" rows={10} style={{ width: "100%", marginTop: 12 }} placeholder="Pourquoi on fait comme ça à cet âge..." value={current?.philosophyText || ""} onChange={(e) => updateText(e.target.value)} />
          <div style={{ whiteSpace: "pre-wrap", marginTop: 12 }}>{current?.philosophyText || <span className="gameplan-empty">Rien d'écrit pour l'instant.</span>}</div>
        </>
      )}
    </div>
  );
}

