                <button className={`btn btn-small ${shortlistIds.includes(p.id) ? "btn-primary" : "btn-ghost"}`} onClick={() => toggleShortlist(p.id)}>{shortlistIds.includes(p.id) ? "✓ Short-list" : "+ Short-list"}</button>
