function loadCompetitionsData() {
  try {
    const raw = localStorage.getItem("tf_competitions");
    return migrateCompetitionsData(raw ? JSON.parse(raw) : null);
  } catch (e) {
    return emptyCompetitionsData();
  }
}

function buildAccueilEvents(comp, sessions, clubEvents) {
  const events = [];
  comp.competitions.forEach((c) => {
    c.fixtures.forEach((f) => events.push({ date: f.date, type: c.type, title: `${c.name} — vs ${f.opponent}`, fixture: f }));
  });
  sessions.forEach((s) => events.push({ date: s.date, type: "seance", title: s.name, session: s }));
  (clubEvents || []).forEach((e) => events.push({ date: e.date, type: e.type || "club", title: e.name, clubEvent: e }));
  return events;
}


